SYSTEM_SETTING_DEFINITIONS = {
    setting['key']: setting
    for group in SYSTEM_SETTING_GROUPS
    for setting in group['settings']
}

def inventory_alert_enabled():
    default = '1' if app.config.get('INVENTORY_ALERT_ENABLED', False) else '0'
    return get_system_setting('inventory_alert_enabled', default) == '1'

def get_system_setting(key, default=''):
    # BUG-2026-08-23-002：请求级缓存。库存批量操作的每条明细都会读
    # location_management_enabled / allow_negative_stock 等开关——100 明细的
    # “提交采购入库单+自动下推领料单”曾触发 202 次 system_setting 查询
    # （占该请求全部 SQL 的 24%），在生产机（杀软扫盘/低配 CPU/写锁排队）上
    # 放大为秒级卡顿。flask.g 随请求销毁，跨请求无陈旧；set_system_setting
    # 会同步更新缓存，保证同请求内写后读一致。非请求线程（调度器/打印代理）
    # 维持原每次查询行为。
    cache = None
    if has_request_context():
        cache = getattr(g, '_system_setting_cache', None)
        if cache is None:
            cache = {}
            g._system_setting_cache = cache
        elif key in cache:
            value = cache[key]
            return default if value is None else value
    try:
        setting = SystemSetting.query.filter_by(key=key).first()
    except OperationalError as exc:
        db.session.rollback()
        if 'system_setting' in str(exc):
            app.logger.warning('System settings table is missing; using default for %s.', key)
            return default
        raise
    value = setting.value if setting and setting.value is not None else None
    if cache is not None:
        cache[key] = value
    return default if value is None else value

def set_system_setting(key, value):
    try:
        # SYS-AUDIT-011：加行锁防止并发保存 last-write-wins
        # SQLite 忽略 with_for_update（no-op），MySQL/PostgreSQL 生效
        setting = SystemSetting.query.filter_by(key=key).with_for_update().first()
    except OperationalError as exc:
        db.session.rollback()
        if 'system_setting' in str(exc):
            raise RuntimeError('系统设置表不存在；当前为不改数据库更新模式，不能保存该设置') from exc
        raise
    if not setting:
        setting = SystemSetting(key=key)
        db.session.add(setting)
    setting.value = str(value)
    setting.updated_at = datetime.now()
    # BUG-2026-08-23-002：同步请求级缓存，保证同请求写后读一致
    if has_request_context():
        cache = getattr(g, '_system_setting_cache', None)
        if cache is None:
            cache = {}
            g._system_setting_cache = cache
        cache[key] = setting.value
    return setting

def location_management_enabled():
    return get_system_setting('location_management_enabled', '0') == '1'

def github_auto_update_enabled():
    """Whether startup should pull from GitHub. Default off (AI-DEPLOY-F01-FIX-01)."""
    return get_system_setting_bool('github_auto_update_enabled', False)

def get_system_setting_bool(key, default=False):
    fallback = '1' if default else '0'
    return get_system_setting(key, fallback) == '1'

def get_system_setting_int(key, default=0):
    try:
        value = int(get_system_setting(key, str(default)))
    except (TypeError, ValueError):
        return default
    definition = SYSTEM_SETTING_DEFINITIONS.get(key) or {}
    min_value = definition.get('min')
    max_value = definition.get('max')
    if min_value is not None:
        value = max(int(min_value), value)
    if max_value is not None:
        value = min(int(max_value), value)
    return value

def get_system_setting_float(key, default=0.0):
    try:
        return float(get_system_setting(key, str(default)))
    except (TypeError, ValueError):
        return default

def max_login_failures():
    return get_system_setting_int('max_login_failures', MAX_LOGIN_FAILURES)

