def get_grouped_system_settings():
    grouped = []
    for group in SYSTEM_SETTING_GROUPS:
        items = []
        for definition in group['settings']:
            key = definition['key']
            raw_value = get_system_setting(key, definition.get('default', ''))
            item = dict(definition)
            item['value'] = raw_value
            if item.get('type') == 'bool':
                item['checked'] = raw_value == '1'
            elif item.get('type') == 'secret':
                env_key = definition.get('config_key')
                item['has_value'] = bool(raw_value or (env_key and app.config.get(env_key)))
                item['value'] = ''
            items.append(item)
        grouped.append({
            'key': group['key'],
            'title': group['title'],
            'icon': group.get('icon', 'bi-gear'),
            'description': group.get('description', ''),
            'settings': items,
        })
    return grouped

@app.context_processor
def inject_query_helpers():
    def url_with_query(**updates):
        args = request.args.to_dict(flat=True)
        for key, value in updates.items():
            if value is None or value == '':
                args.pop(key, None)
            else:
                args[key] = value
        query = urlencode(args)
        return f'{request.path}?{query}' if query else request.path

    return {
        'url_with_query': url_with_query,
        'inventory_alert_enabled': inventory_alert_enabled(),
        'location_management_enabled': location_management_enabled(),
        'material_code_editable': material_code_editable(),
        'now': datetime.now(),
        # BUG-2026-07-28-011 修复：登录页模板用得到
        'max_login_failures': max_login_failures,
        'account_lock_minutes': account_lock_minutes,
    }

@app.before_request
def block_location_modules_when_disabled():
    """Keep core transfer/adjustment available when location control is off.

    Location management controls location-level validation only; it must not
    disable warehouse-level transfer or inventory adjustment workflows.
    """
    return None

@app.before_request
def refresh_session_lifetime():
    """滑动会话过期时间：每次请求时刷新会话，避免用户活跃期间突然过期"""
    if current_user.is_authenticated and session.permanent:
        session.permanent = True  # 触发 Flask 重新计算过期时间

@app.before_request
def enforce_initial_password_change():
    # BUG-2026-07-29-008: 打印/导出路由纳入白名单，避免初始密码未改时被强制重定向到 change_password
    # 导致 admin 无法查看单据（影响 /in_order/<id>/print 等）
    EXEMPT_ENDPOINTS = {
        'static', 'login', 'change_own_password', 'logout',
        'print_in_order', 'print_in_order_direct', 'print_in_order_with_template',
        'print_out_order', 'print_after_sale_out', 'print_purchase_request',
        'print_purchase_order', 'print_adjustment', 'print_check',
        'print_requisition', 'print_transfer', 'print_sales',
        'print_bom', 'print_subcontract', 'print_subcontract_issue',
        'print_subcontract_receive', 'print_labels', 'print_in_order_labels',
    }
    if request.endpoint in EXEMPT_ENDPOINTS:
        return None
    if current_user.is_authenticated and getattr(current_user, 'must_change_password', False):
        if request.path.startswith('/api/') or request.is_json:
            return jsonify({'status': 'error', 'msg': '请先修改初始密码', 'redirect': url_for('change_own_password')}), 403
        return redirect(url_for('change_own_password'))
    return None

# BUG-2026-07-29-007: URL 查询参数长度限制
# 防止超长查询串（>2KB）被静默接受。Werkzeug 默认 8KB 限制太宽松，
# 业务侧 2KB 已经足够任何合理条件组合。返回 414 URI Too Long。
QUERY_STRING_MAX_LENGTH = 2048

@app.before_request
def limit_query_string_length():
    if len(request.query_string) > QUERY_STRING_MAX_LENGTH:
        return api_error(f'查询参数过长（{len(request.query_string)} > {QUERY_STRING_MAX_LENGTH} 字节）', code=414)
    return None

# Error handlers
def _db_safe_rollback():
    """错误处理器专用的安全回滚：连接已损坏时 rollback 可能再次抛错，
    绝不能让异常逃出错误处理器（waitress 会兜底返回英文纯文本 500）。"""
    try:
        db.session.rollback()
    except Exception:
        pass


def wants_json_error_response():
    # BUG-2026-08-04-004: 之前只判断 /api/ 前缀，导致 /material/import 等
    # AJAX POST 路径在 CSRF 失效或 4xx/5xx 时返回 302 重定向或 HTML 错误页，
    # 前端 fetch().then(r => r.json()) 解析失败，丢失错误原因。
    # 现在额外识别 X-Requested-With: XMLHttpRequest 与 Accept: application/json，
    # 让 AJAX 请求统一拿到 JSON 错误响应。
    if request.path.startswith('/api/') or request.path.startswith('/mobile/api/'):
        return True
    if request.headers.get('X-Requested-With') == 'XMLHttpRequest':
        return True
    # BUG-2026-08-05-005: 前端 csrfFetch/postJsonForAction 发 JSON POST 时只带
    # Content-Type: application/json，浏览器 fetch 默认 Accept: */* 且不带
    # X-Requested-With，仅靠上面两个条件会漏判，导致 5xx 返回纯文本
    # "Internal Server Error"，前端 r.json() 抛 "Unexpected token 'I'..."。
    # 请求体本身是 JSON 即视为 AJAX JSON 调用，统一回 JSON 错误。
    if request.is_json:
        return True
    accept = request.headers.get('Accept', '') or ''
    if 'application/json' in accept and 'text/html' not in accept:
        return True
    return False

@app.errorhandler(404)
def not_found(e):
    """404错误处理"""
    if wants_json_error_response():
        return jsonify({'status': 'error', 'msg': '请求的资源不存在'}), 404
    return render_template('404.html'), 404

@app.errorhandler(405)
def method_not_allowed(e):
    """405错误处理"""
    if wants_json_error_response():
        return jsonify({'status': 'error', 'msg': '请求方式不被允许'}), 405
    return render_template('405.html'), 405

@app.errorhandler(CSRFError)
def handle_csrf_error(e):
    """CSRF 错误处理

    WMS-BUG-2026-07-30-003：用户停留超过 30 分钟后点登录或提交表单，
    旧版本直接渲染 csrf_error.html 并显示"5 秒后自动刷新"，但 5 秒倒计时结束后
    浏览器会携带**同一个已过期的 csrftoken cookie**重新发起请求，循环失败，
    用户无法继续操作。
    修复：根据请求路径和 referrer 智能重定向，让浏览器拿到新 csrftoken 再操作。
    """
    _db_safe_rollback()
    msg = '请求已过期或缺少安全令牌，请刷新页面后重试'
    if wants_json_error_response():
        return jsonify({'status': 'error', 'msg': msg}), 400

    # 业务路径智能跳转
    try:
        target = None
        if request.method == 'POST':
            path = (request.path or '').rstrip('/')
            # 1) 登录页 POST 失败：直接重定向到 GET /login，让浏览器重新拿到 csrftoken
            if path == '/login' or path.endswith('/login'):
                target = url_for('login')
            # 2) 修改密码页 POST 失败：跳到 change_own_password（保持 next）
            elif path.endswith('/user/change_password'):
                target = url_for('change_own_password')
            # 3) 其他业务 POST：回首页（清掉旧 token，让下一个 GET 拿新 token）
            else:
                target = url_for('index')
        if target:
            # 用 redirect 而不是 render，避免浏览器在原 POST URL 上再次提交
            resp = redirect(target)
            # 强制覆盖 csrftoken cookie，使下一次 GET 拿到新 token
            resp.set_cookie('csrf_token', '', expires=0, path='/')
            return resp, 302
    except Exception:
        app.logger.exception('handle_csrf_error 智能重定向失败，回退到错误页')

    try:
        return render_template('csrf_error.html'), 400
    except Exception:
        return msg, 400

@app.errorhandler(500)
def internal_error(e):
    """500错误处理"""
    app.logger.error(f"500 Error: {str(e)}")
    # BUG-2026-08-05-005: 连接已损坏时 rollback 可能再次抛错，异常会逃出 Flask，
    # waitress 直接返回纯文本 "Internal Server Error"，前端 r.json() 解析失败。
    _db_safe_rollback()
    if wants_json_error_response():
        return jsonify({'status': 'error', 'msg': '服务器内部错误'}), 500
    return '服务器内部错误，请稍后重试', 500

@app.errorhandler(Exception)
def handle_exception(e):
    """全局异常处理"""
    if isinstance(e, HTTPException):
        if wants_json_error_response():
            return jsonify({'status': 'error', 'msg': e.description or e.name}), e.code
        return e

    import traceback
    error_trace = traceback.format_exc()
    app.logger.error(f"Exception: {str(e)}\n{error_trace}")
    # BUG-2026-08-05-005: rollback 失败不得逃出错误处理器，否则 waitress 兜底
    # 返回英文纯文本，前端完全看不到真实错误。
    _db_safe_rollback()
    if wants_json_error_response():
        resp = {'status': 'error', 'msg': '服务器内部错误，请稍后重试'}
        if app.config.get('DEBUG'):
            resp['trace'] = error_trace
        return jsonify(resp), 500
    # BUG-2026-08-05-005: 原先 DEBUG/非 DEBUG 两个分支都返回英文
    # "Internal Server Error" 纯文本，AJAX 调用方 r.json() 直接解析失败。
    # 与 internal_error 对齐，非 JSON 场景返回可读的中文提示。
    if app.config.get('DEBUG'):
        return f"服务器内部错误，请稍后重试\n{error_trace}", 500
    return '服务器内部错误，请稍后重试', 500

# ==================== 权限检查装饰器 ====================
# ==================== Document number ====================
def generate_order_no(prefix='NO'):
    """Generate order number with database lock to prevent duplicates in concurrent environment."""
    if prefix == 'OUT':
        prefix = 'OU'

    # BUG-2026-08-16-020：SQLite 下 with_for_update 是 no-op，并发取号可能撞号，
    # 而撞号在调用方 INSERT/commit 时才暴露（约束兜底但用户吃 500）。
    # 这里用进程内互斥锁把「读末号 + 算新号」串行化，单进程（WMS 常见部署）
    # 不再撞号；多进程仍由库表唯一约束兜底。
    with _order_no_generation_lock:
        return _generate_order_no_locked(prefix)


# 模块级取号锁：串行化 read-seq+1，避免 SQLite 并发撞号
_order_no_generation_lock = threading.Lock()


def _generate_order_no_locked(prefix):
    now = datetime.now()
    year_month = now.strftime('%y%m')

    max_retries = 3
    for attempt in range(max_retries):
        try:
            if prefix in ('IN', 'PI'):
                last_order = InOrder.query.filter(InOrder.order_no.like(f'{prefix}{year_month}%')).order_by(InOrder.id.desc()).with_for_update().first()
            elif prefix in ('OU', 'SO', 'OO'):
                last_order = OutOrder.query.filter(OutOrder.order_no.like(f'{prefix}{year_month}%')).order_by(OutOrder.id.desc()).with_for_update().first()
            elif prefix == 'CK':
                last_order = InventoryCheck.query.filter(InventoryCheck.check_no.like(f'{prefix}{year_month}%')).order_by(InventoryCheck.id.desc()).with_for_update().first()
            elif prefix == 'CS':
                last_order = InventoryCheckScan.query.filter(InventoryCheckScan.check_no.like(f'{prefix}{year_month}%')).order_by(InventoryCheckScan.id.desc()).with_for_update().first()
            elif prefix == 'SC':
                last_order = SubcontractOrder.query.filter(SubcontractOrder.order_no.like(f'{prefix}{year_month}%')).order_by(SubcontractOrder.id.desc()).with_for_update().first()
            elif prefix == 'SF':
                last_order = SubcontractIssue.query.filter(SubcontractIssue.issue_no.like(f'{prefix}{year_month}%')).order_by(SubcontractIssue.id.desc()).with_for_update().first()
            elif prefix == 'SR':
                last_order = SubcontractReceive.query.filter(SubcontractReceive.receive_no.like(f'{prefix}{year_month}%')).order_by(SubcontractReceive.id.desc()).with_for_update().first()
            elif prefix == 'PR':
                last_order = PurchaseRequest.query.filter(PurchaseRequest.request_no.like(f'{prefix}{year_month}%')).order_by(PurchaseRequest.id.desc()).with_for_update().first()
            elif prefix == 'PO':
                last_order = PurchaseOrder.query.filter(PurchaseOrder.order_no.like(f'{prefix}{year_month}%')).order_by(PurchaseOrder.id.desc()).with_for_update().first()
            elif prefix == 'ASO':
                last_order = AfterSaleOutOrder.query.filter(AfterSaleOutOrder.order_no.like(f'{prefix}{year_month}%')).order_by(AfterSaleOutOrder.id.desc()).with_for_update().first()
            elif prefix == 'BOM':
                last_order = BOM.query.filter(BOM.bom_no.like(f'{prefix}{year_month}%')).order_by(BOM.id.desc()).with_for_update().first()
            elif prefix == 'REQ':
                last_order = ProductionRequisition.query.filter(ProductionRequisition.req_no.like(f'{prefix}{year_month}%')).order_by(ProductionRequisition.id.desc()).with_for_update().first()
            elif prefix == 'TF':
                last_order = TransferOrder.query.filter(TransferOrder.transfer_no.like(f'{prefix}{year_month}%')).order_by(TransferOrder.id.desc()).with_for_update().first()
            elif prefix == 'ADJ':
                last_order = AdjustmentOrder.query.filter(AdjustmentOrder.adjustment_no.like(f'{prefix}{year_month}%')).order_by(AdjustmentOrder.id.desc()).with_for_update().first()
            else:
                last_order = None

            if last_order:
                if prefix in ('IN', 'PI', 'OU', 'SO', 'SE', 'PO'):
                    last_no = last_order.order_no
                elif prefix in ('CK', 'SC'):
                    last_no = last_order.check_no
                elif prefix == 'CS':
                    last_no = last_order.check_no
                elif prefix == 'SF':
                    last_no = last_order.issue_no
                elif prefix == 'SR':
                    last_no = last_order.receive_no
                elif prefix == 'PR':
                    last_no = last_order.request_no
                elif prefix == 'ASO':
                    last_no = last_order.order_no
                elif prefix == 'BOM':
                    last_no = last_order.bom_no
                elif prefix == 'REQ':
                    last_no = last_order.req_no
                elif prefix == 'TF':
                    last_no = last_order.transfer_no
                elif prefix == 'ADJ':
                    last_no = last_order.adjustment_no
                else:
                    last_no = last_order.order_no if hasattr(last_order, 'order_no') else ''

                base = f"{prefix}{year_month}"
                suffix = last_no[len(base):] if last_no and last_no.startswith(base) else ''
                if not suffix:
                    match = re.search(r'(\d+)$', last_no or '')
                    suffix = match.group(1) if match else ''
                try:
                    seq = int(suffix) + 1
                except (ValueError, TypeError):
                    seq = 1
            else:
                seq = 1

            return f"{prefix}{year_month}{seq:04d}"
        except Exception as e:
            if attempt == max_retries - 1:
                raise
            import time
            time.sleep(0.1)

def deduct_stock(material, quantity, transaction_type=None, reference_type=None, reference_id=None, remark=None, warehouse=None):
    """扣减库存，返回(是否成功, 错误信息)"""
    if not material:
        return False, '物料不存在'
    ok, error_msg, _ = deduct_stock_atomic(
        material.id,
        quantity,
        transaction_type=transaction_type,
        reference_type=reference_type,
        reference_id=reference_id,
        remark=remark,
        warehouse=warehouse,
    )
    return ok, error_msg

def _stock_location_from_warehouse(warehouse):
    """把仓库表示解析为流水 location 字符串（关库位管理模式下按仓库聚合）。

    BUG-2026-08-16-006：get_warehouse_stock_quantities 关库位管理分支按
    StockTransaction.location IN (仓库名/编码) 聚合，而 add_stock /
    deduct_stock_atomic 写流水时不填 location（NULL 不入列），导致多仓库
    +关库位管理时仓库级库存恒为 0。调用方传入 warehouse 后，这里把
    仓库名/编码提取出来作为流水 location 写入。
    """
    if warehouse is None:
        return None
    if isinstance(warehouse, Warehouse):
        return (warehouse.name or '').strip() or (warehouse.code or '').strip() or None
    txt = str(warehouse).strip()
    return txt or None


def deduct_stock_atomic(material_id, quantity, transaction_type=None, reference_type=None, reference_id=None, remark=None, warehouse=None):
    """原子扣减库存：用条件 UPDATE 保证并发安全。
    返回 (是否成功, 错误信息, material 对象)。
    仅当 material.stock >= quantity 时才会把库存减掉；并发冲突下 rowcount==0，
    调用方应 rollback 并返回业务失败。
    不改动 material 实例的 Python 属性；扣减完后由上层按需 refresh/读回。
    """
    qty = normalize_stock_quantity(quantity or 0)
    if qty <= 0:
        return False, '扣减数量必须大于 0', None
    mat = Material.query.get(material_id)
    if not mat:
        return False, '物料不存在', None

    condition = Material.id == material_id
    if not allow_negative_stock():
        condition = db.and_(condition, Material.stock >= qty)
    rowcount = db.session.execute(
        sa_update(Material)
        .where(condition)
        .values(stock=Material.stock - qty)
    ).rowcount

    if not rowcount:
        current = normalize_stock_quantity(mat.stock or 0)
        return False, f'物料 {mat.code} 库存不足或并发冲突，当前库存：{current:.2f}', mat

    # 让 ORM 实例和 DB 状态一致，避免 session 里旧 stock 污染后续逻辑
    db.session.expire(mat, ['stock'])

    if transaction_type:
        db.session.add(StockTransaction(
            material_id=material_id,
            transaction_type=transaction_type,
            quantity=-qty,
            location=_stock_location_from_warehouse(warehouse),
            reference_type=reference_type or '',
            reference_id=reference_id or 0,
            operator_id=current_user.id if current_user.is_authenticated else None,
            remark=remark or ''
        ))
    return True, '', mat

def add_stock(material, quantity, transaction_type=None, reference_type=None, reference_id=None, remark=None, warehouse=None):
    """增加库存，返回(是否成功, 错误信息)。

    BUG-2026-08-16-006：新增 warehouse 参数，写流水时把仓库名写入
    StockTransaction.location，使关库位管理模式下 get_warehouse_stock_quantities
    能按仓库聚合（否则 NULL 不入列，仓库级库存恒为 0）。

    P0-BUGFIX: 补 qty>0 校验，与 deduct_stock_atomic 对称。
    原实现无下限校验，负数/NaN 会静默扣减或污染 Material.stock。
    """
    if not material:
        return False, '物料不存在'
    qty = normalize_stock_quantity(quantity or 0)
    if qty <= 0:
        return False, '入库数量必须大于 0'
    rowcount = db.session.execute(
        sa_update(Material)
        .where(Material.id == material.id)
        .values(stock=Material.stock + qty)
    ).rowcount
    if not rowcount:
        return False, '物料不存在'
    db.session.expire(material, ['stock'])
    if transaction_type:
        transaction = StockTransaction(
            material_id=material.id,
            transaction_type=transaction_type,
            quantity=qty,
            location=_stock_location_from_warehouse(warehouse),
            reference_type=reference_type or '',
            reference_id=reference_id or 0,
            operator_id=current_user.id if current_user.is_authenticated else None,
            remark=remark or ''
        )
        db.session.add(transaction)
    return True, ''

def resolve_inventory_warehouse_id(warehouse):
    """把多种仓库表示解析为 LocationInventory.warehouse_id 用的整数 ID。

    INV-AUDIT-002 / INV-AUDIT-001 修复：库存写入口必须把 warehouse_id
    写入 location_inventory，避免不同仓库的同名库位被旧 (material_id,
    location) 唯一约束合并。

    接受：
      - None / 空字符串：返回 None（历史兼容模式，仅匹配 warehouse_id IS NULL 的行）
      - Warehouse 实例：返回 warehouse.id
      - int：直接返回（不查表，由调用方保证有效）
      - str（仓库名或编码）：按 name / code 查 Warehouse，找不到返回 None
    """
    if warehouse is None:
        return None
    if isinstance(warehouse, Warehouse):
        return warehouse.id
    if isinstance(warehouse, int):
        return warehouse
    if isinstance(warehouse, str):
        text = warehouse.strip()
        if not text:
            return None
        wh = Warehouse.query.filter(
            db.or_(Warehouse.name == text, Warehouse.code == text)
        ).order_by(Warehouse.id.asc()).first()
        return wh.id if wh else None
    # 未知类型：尝试取 .id 属性，否则放弃
    return getattr(warehouse, 'id', None)

def update_location_inventory(material, location, quantity_delta, warehouse=None):
    """Update per-location inventory without changing total material stock.

    正负 delta 都通过原子条件 UPDATE 修改库位库存，避免 read-modify-write
    并发丢失更新。新增库位记录仍由本函数在原子 UPDATE 失败后补建。

    INV-AUDIT-002 修复：新增 warehouse 参数。传入时会把 warehouse_id
    写入 location_inventory，并按 (material_id, warehouse_id, location)
    精确匹配；不传时保持旧行为（仅按 material_id + location 匹配
    warehouse_id IS NULL 的历史行）。新代码必须显式传入仓库。
    """
    location = (location or '').strip()
    if not material or not location or not quantity_delta:
        return True, ''

    warehouse_id = resolve_inventory_warehouse_id(warehouse)

    if quantity_delta < 0:
        # 校验库位库存记录存在性时也要带 warehouse_id 维度，
        # 否则不同仓库的同名库位会互相误判。
        query = LocationInventory.query.filter_by(
            material_id=material.id,
            location=location,
        )
        if warehouse_id is not None:
            query = query.filter_by(warehouse_id=warehouse_id)
        else:
            query = query.filter(LocationInventory.warehouse_id.is_(None))
        inventory = query.first()
        if not inventory and not allow_negative_location_stock():
            # BUG-2026-08-04-002 修复：原代码返回 True, ''（静默成功），
            # 导致调用方（如 batch_complete_out_order）在总库存已扣减但
            # 库位库存未扣减时仍认为操作成功，造成账实不一致。
            # 与 deduct_location_inventory_atomic 的行为对齐：无库位记录
            # 且不允许负库存时返回失败。
            code = material.code if material else str(material.id)
            return False, f'物料 {code} 在 {location} 无库位库存记录'
        return deduct_location_inventory_atomic(
            material.id,
            location,
            abs(quantity_delta),
            material_code_hint=material.code,
            warehouse_id=warehouse_id,
        )

    return add_location_inventory_atomic(
        material.id,
        location,
        quantity_delta,
        material_code_hint=material.code,
        warehouse_id=warehouse_id,
    )

def add_location_inventory_atomic(material_id, location, quantity, material_code_hint=None, warehouse_id=None):
    """原子增加库位库存：用条件 UPDATE 避免并发丢失更新。

    若库位记录不存在，先用 INSERT 建立基线再 UPDATE；
    若已存在，直接执行原子增量 UPDATE。
    返回 (是否成功, 错误信息)。

    INV-AUDIT-002 修复：warehouse_id 非 None 时按
    (material_id, warehouse_id, location) 精确匹配并写入 warehouse_id；
    warehouse_id 为 None 时仅匹配 warehouse_id IS NULL 的历史行
    （兼容未传仓库的旧调用方）。
    """
    location = (location or '').strip()
    qty = normalize_stock_quantity(quantity or 0)
    if not location:
        return True, ''
    if qty == 0:
        return True, ''
    if qty < 0:
        return False, 'add_location_inventory_atomic 仅支持非负增量'

    # 规范化 warehouse_id：None / 0 / 负数 视作未提供
    if warehouse_id is not None:
        try:
            wid = int(warehouse_id)
        except (TypeError, ValueError):
            wid = None
        if wid <= 0:
            wid = None
    else:
        wid = None

    filter_clauses = [
        LocationInventory.material_id == material_id,
        LocationInventory.location == location,
    ]
    if wid is not None:
        filter_clauses.append(LocationInventory.warehouse_id == wid)
    else:
        filter_clauses.append(LocationInventory.warehouse_id.is_(None))

    existing = LocationInventory.query.filter(*filter_clauses).first()
    if not existing:
        # 并发下两个事务可能同时进入此分支，但 SQLite BEGIN IMMEDIATE
        # 已串行化写事务；MySQL/PG 依赖 UNIQUE 约束兜底。
        # BUG-2026-08-04-001 修复：原代码在冲突时调用 db.session.rollback()
        # 会回滚整个外层事务（包括已完成的 add_stock 总库存增减），导致总库存
        # 与库位库存、单据状态永久不一致。改用 SAVEPOINT（begin_nested），
        # 冲突时只回滚保存点，不影响外层事务；随后重查记录走原子 UPDATE。
        try:
            nested = db.session.begin_nested()
            db.session.add(LocationInventory(
                material_id=material_id,
                warehouse_id=wid,
                location=location,
                quantity=normalize_stock_quantity(qty),
                updated_at=datetime.now(),
            ))
            db.session.flush()
            return True, ''
        except Exception as e:
            nested.rollback()
            app.logger.warning(
                'add_location_inventory_atomic 建账冲突，转 UPDATE: %s', e
            )
            # 保存点已回滚，外层事务仍可继续；重查确认并发对手已建账
            existing = LocationInventory.query.filter(*filter_clauses).first()
            if not existing:
                # 对手事务建的行不可见或非唯一冲突异常，安全失败
                code = material_code_hint or str(material_id)
                return False, f'物料 {code} 在 {location} 库位建账失败: {e}'

    rowcount = db.session.execute(
        sa_update(LocationInventory)
        .where(db.and_(*filter_clauses))
        .values(
            quantity=LocationInventory.quantity + qty,
            updated_at=datetime.now(),
        )
    ).rowcount
    if not rowcount:
        code = material_code_hint or str(material_id)
        return False, f'物料 {code} 在 {location} 库位库存更新失败或并发冲突'
    return True, ''

def deduct_location_inventory_atomic(material_id, location, quantity, material_code_hint=None, warehouse_id=None):
    """原子扣减库位库存：用条件 UPDATE 避免库位级 TOCTOU。
    不处理"不存在库位记录"的新增加库——那只发生在入库/调入方向。
    返回 (是否成功, 错误信息)。

    INV-AUDIT-002 修复：warehouse_id 非 None 时按
    (material_id, warehouse_id, location) 精确扣减；为 None 时仅扣减
    warehouse_id IS NULL 的历史行。
    """
    location = (location or '').strip()
    qty = normalize_stock_quantity(quantity or 0)
    if not location or qty <= 0:
        return True, ''  # 没有库位或零数量时保持旧行为：不改库位账

    if warehouse_id is not None:
        try:
            wid = int(warehouse_id)
        except (TypeError, ValueError):
            wid = None
        if wid <= 0:
            wid = None
    else:
        wid = None

    condition = db.and_(
        LocationInventory.material_id == material_id,
        LocationInventory.location == location,
    )
    if wid is not None:
        condition = db.and_(condition, LocationInventory.warehouse_id == wid)
    else:
        condition = db.and_(condition, LocationInventory.warehouse_id.is_(None))
    if not allow_negative_location_stock():
        condition = db.and_(condition, LocationInventory.quantity >= qty)
    rowcount = db.session.execute(
        sa_update(LocationInventory)
        .where(condition)
        .values(
            quantity=LocationInventory.quantity - qty,
            updated_at=datetime.now(),
        )
    ).rowcount
    if not rowcount:
        if allow_negative_location_stock():
            inventory = LocationInventory.query.filter(condition).first()
            if not inventory:
                db.session.add(LocationInventory(
                    material_id=material_id,
                    warehouse_id=wid,
                    location=location,
                    quantity=-qty,
                    updated_at=datetime.now(),
                ))
                return True, ''
        code = material_code_hint or str(material_id)
        return False, f'物料 {code} 在 {location} 库存不足或并发冲突'
    return True, ''

def add_stock_transaction(material, quantity, transaction_type, reference_type=None, reference_id=None, location=None, remark=None):
    """Record a stock movement without changing total material stock."""
    if not material or not transaction_type:
        return

    db.session.add(StockTransaction(
        material_id=material.id,
        transaction_type=transaction_type,
        quantity=quantity,
        location=(location or '').strip() or None,
        reference_type=reference_type or '',
        reference_id=reference_id or 0,
        operator_id=current_user.id if current_user.is_authenticated else None,
        remark=remark or ''
    ))

# ==================== Operation ====================
def log_audit(operation, target_type, target_id, target_name=None, old_data=None, new_data=None, status='success', reason=None):
    """Write an operation audit record."""
    try:
        audit = OperationAudit(
            user_id=current_user.id if current_user.is_authenticated else None,
            username=current_user.username if current_user.is_authenticated else 'anonymous',
            operation=operation,
            target_type=target_type,
            target_id=target_id,
            target_name=target_name,
            old_data=json.dumps(old_data, ensure_ascii=False) if old_data else None,
            new_data=json.dumps(new_data, ensure_ascii=False) if new_data else None,
            # BUG-2026-08-16-019：复用 get_request_ip 信任代理逻辑，避免 XFF 可被客户端伪造
            ip_address=get_request_ip(),
            user_agent=request.headers.get('User-Agent', '')[:500],
            status=status,
            reason=reason
        )
        db.session.add(audit)
        try:
            db.session.commit()
        except Exception as e:
            db.session.rollback()
            app.logger.error(f'数据库操作失败: {e}')
    except Exception as e:
        # Best-effort logging; do not fail the main operation if audit logging fails.
        app.logger.error("Audit log failed")
        db.session.rollback()

