def get_active_warehouses():
    """Return selectable warehouses from warehouse master data."""
    return Warehouse.query.filter_by(status='active').order_by(Warehouse.code.asc(), Warehouse.id.asc()).all()

def is_warehouse_active(warehouse_name):
    """BUG-F02-04 修复：判断名称/编码对应的仓库是否处于启用状态。
    返回 (active: bool, message: str)
    - 名称/编码为空时返回 (True, '') 视作不启用库位管理时的宽松模式
    - 找不到对应仓库返回 (False, '仓库 {name} 不存在，请先在仓库主数据中维护')
    - 状态非 active 返回 (False, '仓库 {name} 已停用，禁止新单据')
    """
    if not warehouse_name:
        return True, ''
    wh = Warehouse.query.filter(
        (Warehouse.name == warehouse_name) | (Warehouse.code == warehouse_name)
    ).first()
    if not wh:
        return False, f'仓库 {warehouse_name} 不存在，请先在仓库主数据中维护'
    if (wh.status or 'active') != 'active':
        return False, f'仓库 {warehouse_name} 已停用，禁止新单据（停用仓库的历史库存保留，可在查询/报表中查看）'
    return True, ''

def assert_warehouse_active(warehouse_name, allow_empty=True):
    """BUG-F02-04 修复：若仓库被停用/不存在，返回 (False, message)；
    返回 (True, '') 表示可继续。allow_empty=True 时空值视为通过。"""
    if not warehouse_name and allow_empty:
        return True, ''
    ok, msg = is_warehouse_active(warehouse_name)
    return ok, msg

def prefer_default_warehouse():
    """录单时是否优先自动带出默认仓库。"""
    return get_system_setting_bool('prefer_default_warehouse', True)

def get_default_warehouse():
    """返回当前启用的默认仓库；未设置或不启用自动带出时返回 None。"""
    if not prefer_default_warehouse():
        return None
    return Warehouse.query.filter_by(status='active', is_default=True).first()

def resolve_request_warehouse(params):
    """解析请求中的仓库参数，返回 (warehouse, error)。

    BUG-2026-08-12-004：移动端读取接口统一仓库解析规则（AGENTS.md 仓库必填）。
    - warehouse_id / warehouse_code / warehouse(name) 显式提供时必须存在且 active；
    - 未提供时回退 get_default_warehouse()；
    - 无显式仓库且无默认仓库时返回 (None, '请选择仓库')。
    params 为 request.args 或任意带 .get 的映射。
    """
    def _text(value):
        return str(value).strip() if value is not None else ''

    warehouse = None
    raw_id = _text(params.get('warehouse_id'))
    raw_code = _text(params.get('warehouse_code'))
    raw_name = _text(params.get('warehouse'))

    if raw_id:
        try:
            warehouse = db.session.get(Warehouse, int(raw_id))
        except (TypeError, ValueError):
            warehouse = None
        if not warehouse:
            return None, f'仓库不存在（ID: {raw_id}）'
    elif raw_code:
        warehouse = Warehouse.query.filter_by(code=raw_code).first()
        if not warehouse:
            return None, f'仓库不存在（编码: {raw_code}）'
    elif raw_name:
        warehouse = Warehouse.query.filter(
            db.or_(Warehouse.name == raw_name, Warehouse.code == raw_name)
        ).order_by(Warehouse.id.asc()).first()
        if not warehouse:
            return None, f'仓库不存在：{raw_name}'

    if warehouse:
        if (warehouse.status or 'active') != 'active':
            return None, f'仓库 [{warehouse.name}] 已停用'
        return warehouse, None

    default_wh = get_default_warehouse()
    if default_wh:
        return default_wh, None
    return None, '请选择仓库'

def get_warehouse_stock_quantities(warehouse):
    """按仓库汇总物料库存 {material_id: quantity}，绝不回退全局 Material.stock。

    INV-AUDIT-001 / INV-AUDIT-002 修复：优先按 warehouse_id 汇总，
    兼容旧数据（warehouse_id 为 NULL 但 location == 仓库名的历史行）。
    - 库位管理开启：汇总 LocationInventory
        * 优先 warehouse_id == warehouse.id
        * 兼容 OR location == 仓库名/编码 AND warehouse_id IS NULL
    - 库位管理关闭：按 StockTransaction.location == 仓库名/编码 的流水净额汇总。
    - 仓库无任何记录时返回空 dict（调用方对缺失物料按 0 处理）。
    """
    if not warehouse:
        return {}
    warehouse_key = (warehouse.name or '').strip()
    warehouse_code = (warehouse.code or '').strip()
    if not warehouse_key and not warehouse_code:
        return {}

    if location_management_enabled():
        # 优先按 warehouse_id 精确汇总；OR 兼容旧数据：warehouse_id 为 NULL
        # 且 location 字符串等于仓库名或编码的历史行。
        name_clauses = [LocationInventory.warehouse_id == warehouse.id]
        if warehouse_key:
            name_clauses.append(db.and_(
                LocationInventory.warehouse_id.is_(None),
                LocationInventory.location == warehouse_key,
            ))
        if warehouse_code and warehouse_code != warehouse_key:
            name_clauses.append(db.and_(
                LocationInventory.warehouse_id.is_(None),
                LocationInventory.location == warehouse_code,
            ))
        rows = (db.session.query(LocationInventory.material_id,
                                 func.coalesce(func.sum(LocationInventory.quantity), 0))
                .filter(db.or_(*name_clauses))
                .group_by(LocationInventory.material_id).all())
    else:
        # 库位管理关闭时仍用流水 location 字符串（仓库名/编码）汇总
        # BUG-2026-08-17-00X fallback：系统仅一个仓库时，所有库存必然属于该
        # 仓库，直接以全局 Material.stock 为准，避免历史 NULL-location 流水
        # 无法按 location 聚合导致"有库存查不出来"。
        if Warehouse.query.count() == 1:
            return {m.id: float(m.stock or 0) for m in Material.query.all()}
        # BUG-2026-08-18-003：历史数据 location 可能写的是仓库编号（如 WH001）
        # 而不是仓库名，需要同时匹配编号和名称。
        loc_names = [n for n in (warehouse_key, warehouse_code) if n]
        if not loc_names:
            return {}
        rows = (db.session.query(StockTransaction.material_id,
                                 func.coalesce(func.sum(StockTransaction.quantity), 0))
                .filter(StockTransaction.location.in_(loc_names))
                .group_by(StockTransaction.material_id).all())
    return {material_id: float(quantity or 0) for material_id, quantity in rows}

def _material_stock_unattributed(material_id):
    """物料库存是否全部为无法归属到具体仓库的历史遗留数据。

    用于反提交/完成单明细删除的库存校验兜底（BUG-2026-08-18-002）：
    - 关库位管理：StockTransaction.location 全为空（NULL/''），流水无法按仓库聚合；
    - 开库位管理：LocationInventory.warehouse_id 全为 NULL，无法按仓库聚合。

    此时 get_warehouse_stock_quantities 对该物料仓库级查不到，但 Material.stock
    实际有库存，反提交会误报“库存不足”导致单据卡在 completed、无法删除。
    返回 True 时调用方回退全局 Material.stock 口径；存在任何可归属流水时返回
    False，保持仓库级严格校验，避免 A 仓掩护 B 仓（BUG-2026-08-16-009）。
    """
    if location_management_enabled():
        attributed = db.session.query(LocationInventory.id).filter(
            LocationInventory.material_id == material_id,
            LocationInventory.warehouse_id.isnot(None),
        ).first()
    else:
        attributed = db.session.query(StockTransaction.id).filter(
            StockTransaction.material_id == material_id,
            StockTransaction.location.isnot(None),
            StockTransaction.location != '',
        ).first()
    return attributed is None

def resolve_active_sales_warehouse(value=None, warehouse_id=None):
    """Resolve a sales warehouse from its ID, name, or code.

    New sales documents must resolve to an active master record. The legacy
    warehouse name is still written for compatibility with existing stock
    documents and reports.
    """
    if warehouse_id:
        try:
            warehouse = db.session.get(Warehouse, int(warehouse_id))
        except (TypeError, ValueError):
            warehouse = None
        if warehouse and warehouse.status == 'active':
            return warehouse
        return None
    normalized = (value or '').strip()
    if not normalized:
        return None
    return Warehouse.query.filter(
        Warehouse.status == 'active',
        db.or_(Warehouse.name == normalized, Warehouse.code == normalized),
    ).order_by(Warehouse.id.asc()).first()

def validate_sales_warehouse(value=None, warehouse_id=None):
    warehouse = resolve_active_sales_warehouse(value, warehouse_id)
    if not warehouse:
        return None, '请选择有效且启用的发货仓库'
    return warehouse, None


def resolve_active_inventory_warehouse(value=None, warehouse_id=None):
    """Resolve an inventory warehouse (调拨/盘点/调整/普通出库) by ID, name, or code.

    INV-AUDIT-005：与销售仓库解析对称，但语义为"库存单据仓库"。
    - warehouse_id 优先解析为整数主键；
    - 否则用 value（仓库名或编码）匹配 Warehouse.name / Warehouse.code；
    - 必须存在且 status='active' 才返回，否则返回 None。
    - 未提供 value 与 warehouse_id 时返回 None（不自动回退默认仓库；
      回退由调用方决定，避免在多个分支重复默认仓逻辑）。
    """
    if warehouse_id:
        try:
            warehouse = db.session.get(Warehouse, int(warehouse_id))
        except (TypeError, ValueError):
            warehouse = None
        if warehouse and (warehouse.status or 'active') == 'active':
            return warehouse
        return None
    normalized = (value or '').strip()
    if not normalized:
        return None
    return Warehouse.query.filter(
        Warehouse.status == 'active',
        db.or_(Warehouse.name == normalized, Warehouse.code == normalized),
    ).order_by(Warehouse.id.asc()).first()


def validate_inventory_warehouse(value=None, warehouse_id=None):
    """Validate a non-sales inventory warehouse, returning (warehouse, error).

    INV-AUDIT-005：调拨/盘点/调整/普通出库统一仓库存在性 + active 校验。
    返回的 warehouse 已确认 active，调用方仍需用 warehouse.name 写入单据
    字段以兼容历史字符串字段。
    """
    warehouse = resolve_active_inventory_warehouse(value, warehouse_id)
    if not warehouse:
        if value or warehouse_id:
            return None, f'仓库不存在或已停用：{value or warehouse_id}'
        return None, '请选择有效且启用的仓库'
    if (warehouse.status or 'active') != 'active':
        return None, f'仓库 [{warehouse.name}] 已停用'
    return warehouse, None


def validate_sales_outbound_warehouse(outbound):
    """Validate the canonical warehouse and every linked sales source row."""
    warehouse, error = validate_sales_warehouse(outbound.warehouse)
    if error:
        return None, error
    if outbound.source_sales_order_id:
        source_order = db.session.get(SalesOrder, outbound.source_sales_order_id)
        if source_order and source_order.warehouse_id and source_order.warehouse_id != warehouse.id:
            return None, '销售出库仓库必须与来源销售订单一致'
    for item in outbound.items:
        source_item = item.source_sales_order_item
        source_order = source_item.sales_order if source_item else None
        if source_order and source_order.warehouse_id and source_order.warehouse_id != warehouse.id:
            return None, '销售出库明细包含跨仓库来源，不能完成出库'
    outbound.warehouse = warehouse.name
    return warehouse, None

def ensure_default_warehouses():
    """Keep legacy document warehouse choices available in warehouse master data."""
    changed = False
    for item in DEFAULT_WAREHOUSES:
        if Warehouse.query.filter_by(name=item['name']).first():
            continue

        code = item['code']
        suffix = 1
        while Warehouse.query.filter_by(code=code).first():
            suffix += 1
            code = f'WH{suffix:03d}'

        db.session.add(Warehouse(
            code=code,
            name=item['name'],
            type=item['type'],
            status='active',
            remark='系统默认仓库'
        ))
        changed = True

    if changed:
        db.session.commit()

def ensure_default_system_settings():
    changed = False
    for key, definition in SYSTEM_SETTING_DEFINITIONS.items():
        if SystemSetting.query.filter_by(key=key).first():
            continue
        db.session.add(SystemSetting(
            key=key,
            value=definition.get('default', ''),
            remark=definition.get('remark', '')
        ))
        changed = True
    if changed:
        db.session.commit()

