DEFAULT_LABEL_CELLS = [
    {'row': 0, 'col': 0, 'field': 'name', 'style': {'fontSize': 13, 'fontWeight': 'bold', 'textAlign': 'center', 'color': '#111827'}},
    {'row': 1, 'col': 0, 'field': 'barcode', 'barcodeWidth': 55, 'barcodeHeight': 14, 'style': {'fontSize': 10, 'textAlign': 'center', 'color': '#111827'}},
    {'row': 2, 'col': 0, 'field': 'code', 'style': {'fontSize': 10, 'textAlign': 'center', 'color': '#111827'}},
    {'row': 3, 'col': 0, 'field': 'spec', 'style': {'fontSize': 10, 'textAlign': 'left', 'color': '#374151'}},
    {'row': 4, 'col': 0, 'field': 'unit', 'style': {'fontSize': 10, 'textAlign': 'left', 'color': '#374151'}},
]

DEFAULT_LABEL_LAYOUT = {
    'cells': DEFAULT_LABEL_CELLS,
    'rowHeights': [24, 36, 22, 22, 22],
}
for cell in DEFAULT_LABEL_CELLS:
    DEFAULT_LABEL_LAYOUT[f"{cell['row']}-{cell['col']}"] = {
        'field': cell['field'],
        'label': {
            'name': '物料名称',
            'barcode': '条码',
            'code': '物料编码',
            'spec': '规格',
            'unit': '单位',
        }.get(cell['field'], cell['field']),
        'style': cell.get('style', {}),
    }

def _normalize_label_template_layout(layout):
    if not isinstance(layout, dict):
        return {}

    normalized = dict(layout)
    keyed_cells = []
    for key, cell in layout.items():
        if not isinstance(key, str) or '-' not in key or not isinstance(cell, dict):
            continue
        row_text, col_text = key.split('-', 1)
        if not row_text.isdigit() or not col_text.isdigit():
            continue
        field = cell.get('field')
        if not field:
            continue
        keyed_cells.append({
            'row': int(row_text),
            'col': int(col_text),
            'field': field,
            'label': cell.get('label') or field,
            'style': cell.get('style') or {},
            'barcodeWidth': cell.get('barcodeWidth'),
            'barcodeHeight': cell.get('barcodeHeight'),
            'colSpan': cell.get('colSpan') or 1,
        })

    if keyed_cells:
        normalized['cells'] = sorted(keyed_cells, key=lambda item: (item['row'], item['col']))
    elif not isinstance(normalized.get('cells'), list):
        normalized['cells'] = []
    return normalized

def ensure_default_print_templates():
    """Create the built-in print templates when an installation has none.

    BUG-2026-08-20-003：存量库的「系统默认入库单模板」内容仍是旧样式
    （含副标题 RECEIPT、序号列、备注列、四格签名行），用户已按样式图
    重写 DEFAULT_IN_ORDER_HTML_TEMPLATE。此处对「系统默认」模板做内容
    对齐：若 html_template_content 与常量不一致则覆盖更新，保证重启
    后默认模板自动同步到新样式，同时保留用户自建模板不动。
    """
    changed = False
    defaults = (
        (InOrderPrintTemplate, '系统默认入库单模板', DEFAULT_IN_ORDER_HTML_TEMPLATE, 'excel', 'in_order_print_template'),
        (OutOrderPrintTemplate, '系统默认领料单模板', DEFAULT_OUT_ORDER_HTML_TEMPLATE, 'excel', 'out_order_print_template'),
    )
    for model, name, content, template_type, table in defaults:
        existing = model.query.filter_by(name=name).first()
        has_default = bool(model.query.filter_by(is_default=True).first())
        if not existing:
            db.session.add(model(
                name=name,
                template_type=template_type,
                html_template_content=content,
                excel_template_path=_ensure_builtin_excel_template_file(table),
                is_default=not has_default,
            ))
            changed = True
        else:
            if not has_default:
                existing.is_default = True
                changed = True
            if (existing.html_template_content or '') != content:
                existing.html_template_content = content
                changed = True
            if (existing.template_type or '') != template_type:
                existing.template_type = template_type
                changed = True
            # BUG-2026-08-22-002：内置模板缺 Excel 文件时补静态示例副本；
            # builtin_* 前缀为系统管理的内置副本，随内置版式升级
            cur_path = (existing.excel_template_path or '').strip()
            if not cur_path or cur_path.startswith('/static/uploads/print_templates/builtin_'):
                excel_path = _ensure_builtin_excel_template_file(table)
                if excel_path and excel_path != cur_path:
                    existing.excel_template_path = excel_path
                    changed = True

    label_default = LabelTemplate.query.filter_by(name='系统默认物料标签模板').first()
    has_label_default = bool(LabelTemplate.query.filter_by(is_default=True).first())
    if not label_default:
        db.session.add(LabelTemplate(
            name='系统默认物料标签模板',
            width=90,
            height=50,
            cols=1,
            rows=5,
            layout=json.dumps(DEFAULT_LABEL_LAYOUT, ensure_ascii=False),
            is_default=not has_label_default,
        ))
        # 物料标签默认打印模板统一为 90×50mm（手机端 / 电脑端共用 print_batch_labels.html）。
        label_default = LabelTemplate.query.filter_by(name='系统默认物料标签模板').first()
        changed = True
    elif not has_label_default:
        label_default.is_default = True
        changed = True

    # 存量库：把「系统默认物料标签模板」强制对齐到默认尺寸 90×50mm，
    # 并确保其为默认模板，保证物料标签打印默认出纸为 90×50（幂等）。
    if label_default:
        if (label_default.width or 0) != 90 or (label_default.height or 0) != 50:
            label_default.width = 90
            label_default.height = 50
            changed = True
        if not label_default.is_default and not has_label_default:
            label_default.is_default = True
            changed = True

    if changed:
        db.session.commit()


def _ensure_builtin_excel_template_file(table):
    """内置默认打印模板补 Excel 模板文件（BUG-2026-08-22-002）。

    「系统默认入库单模板」「系统默认领料单模板」历史只有
    html_template_content、excel_template_path 为空，导致模板管理页
    下载/在线编辑按钮不显示、「下载当前默认打印模板」入口隐藏、
    Excel 填充打印只能回退内置版式。

    把 static/templates 下的示例 xlsx 复制为 uploads/print_templates 下的
    内置模板副本（在线编辑改写副本，不动静态示例原件），返回应写入
    excel_template_path 的 /static/... URL；源文件缺失或异常返回 None。
    """
    sources = {
        'in_order_print_template': ('入库单打印模板示例.xlsx', 'builtin_in_order_default_v2.xlsx'),
        'out_order_print_template': ('领料单打印模板示例.xlsx', 'builtin_out_order_default_v2.xlsx'),
    }
    spec = sources.get(table)
    if spec is None:
        return None
    src_name, dst_name = spec
    try:
        static_root = os.path.join(os.path.dirname(__file__), 'static')
        src = os.path.join(static_root, 'templates', src_name)
        if not os.path.exists(src):
            return None
        dst_dir = os.path.join(static_root, 'uploads', 'print_templates')
        os.makedirs(dst_dir, exist_ok=True)
        dst = os.path.join(dst_dir, dst_name)
        if not os.path.exists(dst):
            import shutil
            shutil.copyfile(src, dst)
        return '/static/uploads/print_templates/' + dst_name
    except Exception:  # noqa: BLE001 - 补文件失败不阻断启动，下载仍按原逻辑 404
        return None


def _ensure_default_print_templates_unconditional(db_path=None):
    """启动期无条件同步内置打印模板类型/内容（BUG-2026-08-21-002）。

    ensure_default_print_templates() 仅在 initialize_database() 未被
    WMS_NO_DB_TOUCH=1 / WMS_SKIP_STARTUP_DB_UPGRADE=1 / *.flag 跳过时才运行；
    而 start_wms_offline.bat / start_wms_auto.bat 默认 WMS_NO_DB_TOUCH=1，
    导致「系统默认入库单模板」「系统默认领料单模板」的 template_type 始终为
    'html'、内容仍是旧样式（RECEIPT 副标题、序号/备注列、合计行、四格签名），
    修改后的 Excel 默认模板在线上永远不生效。

    本函数仿照 backfill_empty_warehouse_documents，用独立 sqlite 连接、独立于
    迁移开关无条件执行、幂等：把两个内置模板的 template_type 对齐为 'excel'、
    html_template_content 对齐为常量，并保证各自表内存在 is_default=1。
    """
    conn = None
    try:
        if db_path is None:
            db_path = _resolve_sqlite_db_path()
            if db_path is None:
                db_path = os.path.join(os.path.dirname(__file__), 'instance', 'inventory.db')
        if not os.path.exists(db_path):
            return
        import sqlite3
        conn = sqlite3.connect(db_path, timeout=60)
        conn.row_factory = sqlite3.Row
        cur = conn.cursor()
        cur.execute('PRAGMA busy_timeout=60000')

        # 表名单一、逻辑一致；表名来自下方固定白名单（非用户输入），
        # 仅作标识符拼接，值全部走 ? 参数化，无注入风险。
        builtins = (
            ('in_order_print_template', '系统默认入库单模板', DEFAULT_IN_ORDER_HTML_TEMPLATE),
            ('out_order_print_template', '系统默认领料单模板', DEFAULT_OUT_ORDER_HTML_TEMPLATE),
        )
        changed = False
        for table, name, content in builtins:
            tbl = cur.execute(
                "SELECT 1 FROM sqlite_master WHERE type='table' AND name=?", (table,)
            ).fetchone()
            if not tbl:
                continue
            row = cur.execute(
                "SELECT id, template_type, html_template_content, excel_template_path FROM "
                + table + " WHERE name=?",
                (name,),
            ).fetchone()
            if row is None:
                has_default = cur.execute(
                    "SELECT 1 FROM " + table + " WHERE is_default=1 LIMIT 1"
                ).fetchone() is not None
                cur.execute(
                    "INSERT INTO " + table +
                    " (name, template_type, html_template_content, excel_template_path,"
                    " is_default, created_at, updated_at)"
                    " VALUES (?, 'excel', ?, ?, ?, datetime('now'), datetime('now'))",
                    (name, content, _ensure_builtin_excel_template_file(table),
                     0 if has_default else 1),
                )
                changed = True
            else:
                tid = row['id']
                if (row['template_type'] or '') != 'excel':
                    cur.execute(
                        "UPDATE " + table + " SET template_type='excel', updated_at=datetime('now') WHERE id=?",
                        (tid,),
                    )
                    changed = True
                if (row['html_template_content'] or '') != content:
                    cur.execute(
                        "UPDATE " + table + " SET html_template_content=?, updated_at=datetime('now') WHERE id=?",
                        (content, tid),
                    )
                    changed = True
                # BUG-2026-08-22-002：内置模板缺 Excel 文件时补静态示例副本，
                # 下载/在线编辑/Excel 填充打印即刻可用；builtin_* 前缀为系统
                # 管理的内置副本，随内置版式升级；用户自己上传的文件不动。
                cur_path = (row['excel_template_path'] or '').strip()
                if not cur_path or cur_path.startswith('/static/uploads/print_templates/builtin_'):
                    excel_path = _ensure_builtin_excel_template_file(table)
                    if excel_path and excel_path != cur_path:
                        cur.execute(
                            "UPDATE " + table + " SET excel_template_path=?, updated_at=datetime('now') WHERE id=?",
                            (excel_path, tid),
                        )
                        changed = True
            default_row = cur.execute(
                "SELECT 1 FROM " + table + " WHERE is_default=1 LIMIT 1"
            ).fetchone()
            if default_row is None:
                cur.execute("UPDATE " + table + " SET is_default=1 WHERE name=?", (name,))
                changed = True
        if changed:
            conn.commit()
            logging.getLogger(__name__).info('[DB] 内置打印模板已同步为 Excel 默认样式')
    except Exception as e:
        try:
            logging.getLogger(__name__).error(
                f'_ensure_default_print_templates_unconditional 同步失败: {e}', exc_info=True)
        except Exception:
            pass
        if conn is not None:
            try:
                conn.rollback()
            except Exception:
                pass
    finally:
        if conn is not None:
            try:
                conn.close()
            except Exception:
                pass


_ensure_default_print_templates_unconditional()


class LocationInventory(db.Model):
    """Inventory quantity by location."""
    __tablename__ = 'location_inventory'

    id = db.Column(db.Integer, primary_key=True)
    material_id = db.Column(db.Integer, db.ForeignKey('material.id'), nullable=False)  # Material ID
    warehouse_id = db.Column(db.Integer, db.ForeignKey('warehouse.id'), nullable=True)
    location = db.Column(db.String(100), nullable=False)  # Location code
    quantity = db.Column(db.Float, default=0)  # Inventory quantity at this location
    created_at = db.Column(db.DateTime, default=datetime.now)
    updated_at = db.Column(db.DateTime, default=datetime.now, onupdate=datetime.now)

    material = db.relationship('Material', backref='location_inventories')
    warehouse = db.relationship('Warehouse', backref='location_inventories')

    __table_args__ = (
        # INV-AUDIT-002 修复：唯一约束从 (material_id, location) 改为
        # (material_id, warehouse_id, location)，禁止不同仓库的同名库位被
        # 强行合并到同一条库存记录。旧约束名保留在迁移历史中，新写入统一走
        # 新约束；warehouse_id 为 NULL 的历史行按 SQLite/大多数数据库语义各自
        # 视为不同值，不会与已归属仓库的行冲突。
        db.UniqueConstraint('material_id', 'warehouse_id', 'location', name='uix_material_warehouse_location'),
        db.Index('idx_location_inventory_warehouse', 'warehouse_id'),
    )

