def ensure_bootstrap_admin_user():
    """Create an initial admin account when the user table is empty."""
    if User.query.count() > 0:
        return None

    username = (os.environ.get('WMS_BOOTSTRAP_USERNAME') or 'admin').strip() or 'admin'
    # 禁止系统生成随机密码（AGENTS.md 规则）：未设置环境变量时使用固定默认 'admin' 并警告弱密码
    password = os.environ.get('WMS_BOOTSTRAP_PASSWORD') or 'admin'
    if not os.environ.get('WMS_BOOTSTRAP_PASSWORD'):
        app.logger.warning(
            "WMS_BOOTSTRAP_PASSWORD not set. Using default password 'admin'. "
            "Please set WMS_BOOTSTRAP_PASSWORD environment variable for a secure password."
        )
    user = User(
        username=username,
        password_hash=generate_password_hash(password),
        role='admin',
        status='normal',
        created_at=datetime.now(),
        must_change_password=False,
    )
    db.session.add(user)
    try:
        db.session.commit()
    except Exception as e:
        db.session.rollback()
        app.logger.error(f"Failed to create bootstrap admin user: {e}")
        raise
    app.logger.warning("Bootstrap admin account created: username=%s.", username)
    return user

def ensure_admin_user_exists():
    """Ensure admin user exists; create if missing, unlock only if disabled."""
    user = User.query.filter_by(username='admin').first()
    if user:
        # 不再强制首次登录改密码；保留环境变量覆盖能力（设置 WMS_BOOTSTRAP_PASSWORD 时清除标记）
        if os.environ.get('WMS_BOOTSTRAP_PASSWORD') and user.must_change_password:
            user.must_change_password = False
            try:
                db.session.commit()
            except Exception as e:
                db.session.rollback()
                app.logger.error(f'Failed to reset must_change_password for admin: {e}')
        # 仅在账号被显式 disabled 时启动期解锁；is_locked（因登录失败次数过多触发的临时锁定）
        # 应等待 locked_until 自然到期，避免攻击者通过触发重启重置锁定计数绕过暴力破解保护。
        if user.status == 'disabled':
            user.status = 'normal'
            try:
                db.session.commit()
            except Exception as e:
                db.session.rollback()
                app.logger.error(f"Failed to unlock admin account: {e}")
            app.logger.info("Admin account unlocked (was disabled)")
        return user

    bootstrap_password = os.environ.get('WMS_BOOTSTRAP_PASSWORD') or 'admin'
    if not os.environ.get('WMS_BOOTSTRAP_PASSWORD'):
        app.logger.warning(
            "WMS_BOOTSTRAP_PASSWORD not set. Using default password 'admin'. "
            "Please set WMS_BOOTSTRAP_PASSWORD environment variable for a secure password."
        )
    user = User(
        username='admin',
        password_hash=generate_password_hash(bootstrap_password),
        role='admin',
        status='normal',
        created_at=datetime.now(),
        must_change_password=False,
    )
    db.session.add(user)
    try:
        db.session.commit()
    except Exception as e:
        db.session.rollback()
        app.logger.error(f"Failed to create admin user: {e}")
        raise
    app.logger.warning("Admin user created with default password 'admin'. Please set WMS_BOOTSTRAP_PASSWORD for a secure password.")
    return user

# BUG-2026-08-24-003：connect 期 PRAGMA（WAL/synchronous/busy_timeout/foreign_keys）
# 只关乎「连接行为」，与 schema 迁移无关，此前却放在 initialize_database() 的
# startup_db_upgrade_disabled() 早退之后——start_wms_offline.bat/start_wms_auto.bat
# 默认 WMS_NO_DB_TOUCH=1 时 initialize_database() 提前 return，监听器从不注册，
# 生产 ORM 连接退回 sqlite3 默认 5s busy_timeout，打印心跳等高频写与其他写事务
# 相撞即抛 database is locked（心跳 500）。故拆成独立函数并在早退之前无条件注册。
_SQLITE_PRAGMA_REGISTERED = False


def _register_sqlite_pragma_listener():
    """为 ORM 引擎注册 SQLite connect 期 PRAGMA（幂等，与 schema 迁移开关解耦）。

    SQLite 并发优化：WAL 允许读写并发，busy_timeout 避免短暂写锁直接失败。
    PERF-2026-08-23-001：WAL 默认 synchronous=FULL，每次 commit 强制 fsync；
    Windows + 杀软实时扫描 + 机械盘下单次 fsync 可达几十~几百毫秒，且写锁
    在事务提交前不释放，导致"完成/下推"等写请求排队卡顿（实测：持锁 2 秒
    期间发起的请求等待 1797ms）。改为 NORMAL（WAL 官方推荐组合）：commit
    不再逐次强制刷盘，仅在 checkpoint 时同步；代价为掉电丢最后数百毫秒
    事务（系统有幂等键 + 单据可重推兜底），换取慢盘写性能 5~50 倍提升。
    """
    global _SQLITE_PRAGMA_REGISTERED
    if _SQLITE_PRAGMA_REGISTERED:
        return
    from sqlalchemy import event as sa_event

    @sa_event.listens_for(db.engine, 'connect')
    def set_sqlite_pragma(dbapi_connection, connection_record):
        cursor = dbapi_connection.cursor()
        cursor.execute('PRAGMA journal_mode=WAL')
        cursor.execute('PRAGMA synchronous=NORMAL')
        cursor.execute('PRAGMA busy_timeout=30000')
        cursor.execute('PRAGMA foreign_keys=ON')
        cursor.close()

    _SQLITE_PRAGMA_REGISTERED = True


# no-test:reason=存量函数非新增；BUG-2026-08-24-003 改动行为由
# tests/test_bug_2026_08_24_003_sqlite_pragma_gating.py 专项覆盖
def initialize_database():
    """Create missing tables and ensure the bootstrap admin account exists."""
    # BUG-2026-08-24-003：PRAGMA 注册与 schema 迁移解耦，WMS_NO_DB_TOUCH=1 跳过
    # 迁移时也必须生效（否则生产连接只有 sqlite3 默认 5s busy_timeout，心跳写库 500）。
    _register_sqlite_pragma_listener()

    if startup_db_upgrade_disabled():
        app.logger.warning('Startup database initialization skipped by environment.')
        return

    db.create_all()
    ensure_bootstrap_admin_user()
    ensure_admin_user_exists()
    ensure_default_warehouses()
    ensure_default_system_settings()
    ensure_default_print_templates()
    # PRINT-TEMPLATE-F03：全新部署时模块级无条件同步早于 create_all 执行，
    # 彼时 excel_print_template 表还不存在会被跳过；此处表已建好，再跑一次
    # raw sqlite 幂等同步（函数自身容忍表/库缺失，重复执行无变化）。
    ensure_builtin_excel_doc_templates()
    ensure_material_category_tree_defaults()
    _wechat_share_default_config()
    # 修复已有物料的空分类/单位
    try:
        default_unit = Unit.query.filter_by(name='个').first() or Unit.query.first()
        default_cat = MaterialCategory.query.filter_by(name='默认分类').first() or MaterialCategory.query.first()
        if default_unit:
            cnt = Material.query.filter(db.or_(Material.unit_id.is_(None), Material.unit_id == 0)).update(
                {Material.unit_id: default_unit.id}, synchronize_session=False)
            if cnt:
                app.logger.info(f'修复物料单位: {cnt} 条 → "{default_unit.name}"')
        if default_cat:
            cnt = Material.query.filter(db.or_(Material.category_id.is_(None), Material.category_id == 0)).update(
                {Material.category_id: default_cat.id}, synchronize_session=False)
            if cnt:
                app.logger.info(f'修复物料分类: {cnt} 条 → "{default_cat.name}"')
        db.session.commit()
    except Exception as e:
        db.session.rollback()
        app.logger.warning(f'修复物料字段跳过: {e}')

# ==================== Login management ====================

@login_manager.user_loader
def load_user(user_id):
    return db.session.get(User, int(user_id))

def get_request_ip():
    """Return the client IP, respecting reverse proxy headers only from trusted proxies."""
    # 仅当请求来自可信代理时才信任 X-Forwarded-For
    trusted_proxies = current_app.config.get('TRUSTED_PROXIES', [])
    remote_addr = request.remote_addr or ''
    if remote_addr in trusted_proxies:
        forwarded_for = request.headers.get('X-Forwarded-For', '')
        if forwarded_for:
            return forwarded_for.split(',')[0].strip()
    return remote_addr

def get_next_target():
    if request.query_string:
        return f'{request.path}?{request.query_string.decode("utf-8")}'
    return request.path

def is_safe_redirect_target(target):
    if not target:
        return False

    ref_url = urlparse(request.host_url)
    test_url = urlparse(urljoin(request.host_url, target))

    if test_url.scheme not in {'http', 'https'}:
        return False
    if test_url.netloc != ref_url.netloc:
        return False
    if test_url.path in {url_for('login'), url_for('logout')}:
        return False
    return True

def resolve_redirect_target(target, default_endpoint='index'):
    if is_safe_redirect_target(target):
        return target
    return url_for(default_endpoint)

def add_login_log(status, username, user=None, fail_reason=None):
    db.session.add(LoginLog(
        user_id=user.id if user else None,
        username=username,
        login_ip=get_request_ip(),
        user_agent=request.headers.get('User-Agent', '')[:500],
        status=status,
        fail_reason=fail_reason
    ))

@login_manager.unauthorized_handler
def unauthorized():
    if wants_json_error_response():
        return jsonify({'status': 'error', 'msg': '未登录或登录已过期'}), 401
    flash('请先登录后再继续', 'warning')
    next_target = get_next_target()
    return redirect(url_for('login', next=next_target))

# Bearer Token 续期与 last_used_at 刷新策略（BUG-2026-08-13-005）：
# - LAST_USED_FLUSH_SECONDS：last_used_at 最多每 5 分钟写一次
# - RENEW_THRESHOLD_SECONDS：仅当剩余有效期 < 1 天才顺延 7 天
# - TOKEN_TTL_DAYS：每次续期固定 7 天
LAST_USED_FLUSH_SECONDS = 300
RENEW_THRESHOLD_SECONDS = 24 * 3600
TOKEN_TTL_DAYS = 7

# ==================== Permission ====================
def get_bearer_user():
    auth = request.headers.get('Authorization', '')
    if not auth.startswith('Bearer '):
        return None
    token_value = auth.split(' ', 1)[1].strip()
    if not token_value:
        return None
    token = ApiToken.query.filter_by(token=token_value, revoked=False).first()
    if not token or token.expires_at < datetime.now():
        return None
    now = datetime.now()
    need_flush_last_used = (
        token.last_used_at is None
        or (now - token.last_used_at).total_seconds() >= LAST_USED_FLUSH_SECONDS
    )
    need_renew = (token.expires_at - now).total_seconds() < RENEW_THRESHOLD_SECONDS
    if need_flush_last_used or need_renew:
        try:
            if need_flush_last_used:
                token.last_used_at = now
            if need_renew:
                token.expires_at = now + timedelta(days=TOKEN_TTL_DAYS)
            db.session.commit()
        except Exception:
            db.session.rollback()
    return token.user if token.user and token.user.is_active else None

def api_required(f):
    @wraps(f)
    def decorated_function(*args, **kwargs):
        user = get_bearer_user()
        if not user:
            return jsonify({'status': 'error', 'msg': 'Bearer Token 无效或已过期'}), 401
        return f(user, *args, **kwargs)
    return decorated_function

def api_role_required(*roles):
    """Require a bearer token user with one of the allowed business roles."""
    allowed = set(roles or ())

    def decorator(f):
        @wraps(f)
        def decorated_function(*args, **kwargs):
            user = get_bearer_user()
            if not user:
                return jsonify({'status': 'error', 'msg': 'Bearer Token 无效或已过期'}), 401
            if user.role != 'admin' and user.role not in allowed:
                return jsonify({'status': 'error', 'msg': '当前账号没有权限执行该操作'}), 403
            return f(user, *args, **kwargs)
        return decorated_function
    return decorator

def mobile_api_idempotent(endpoint):
    """Replay a successful native mobile submission when a client retries it."""
    def decorator(f):
        @wraps(f)
        def decorated_function(user, *args, **kwargs):
            payload = request.get_json(silent=True) or {}
            request_key = (
                request.headers.get('X-Idempotency-Key')
                or payload.get('request_id')
                or ''
            ).strip()
            if request_key:
                if len(request_key) > 120:
                    return api_json_error('幂等请求号不能超过120个字符', 400)
                existing = MobileApiRequest.query.filter_by(
                    user_id=user.id,
                    endpoint=endpoint,
                    request_key=request_key,
                ).first()
                if existing:
                    try:
                        replay_payload = json.loads(existing.response_json)
                    except (TypeError, ValueError):
                        replay_payload = {'status': 'error', 'success': False, 'msg': '历史响应无法读取'}
                    return jsonify(replay_payload), existing.status_code

            response = f(user, *args, **kwargs)
            if not request_key:
                return response

            response_obj = response[0] if isinstance(response, tuple) else response
            status_code = response[1] if isinstance(response, tuple) and len(response) > 1 else response_obj.status_code
            if not 200 <= status_code < 300:
                return response
            response_payload = response_obj.get_json(silent=True) or {}
            try:
                db.session.add(MobileApiRequest(
                    user_id=user.id,
                    endpoint=endpoint,
                    request_key=request_key,
                    status_code=status_code,
                    response_json=json.dumps(response_payload, ensure_ascii=False),
                ))
                db.session.commit()
            except Exception:
                # The business transaction has already committed. A failed audit
                # record must not turn a successful warehouse operation into an error.
                db.session.rollback()
                app.logger.exception('Mobile idempotency record failed')
            return response
        return decorated_function
    return decorator

def web_or_api_required(f):
    @wraps(f)
    def decorated_function(*args, **kwargs):
        if current_user.is_authenticated:
            return f(*args, **kwargs)
        if get_bearer_user():
            return f(*args, **kwargs)
        return jsonify({'status': 'error', 'success': False, 'msg': '未登录或 Bearer Token 无效'}), 401
    return decorated_function

def web_or_api_role_required(*roles):
    """Require a web session or bearer token user with one of the allowed business roles."""
    allowed = set(roles or ())

    # no-test:reason=装饰器工厂内部包装，由 web_or_api_role_required 的端点测试覆盖
    def decorator(f):
        # no-test:reason=装饰器包装函数，由 endpoint 测试覆盖
        @wraps(f)
        def decorated_function(*args, **kwargs):
            user = current_user if current_user.is_authenticated else None
            if user is None:
                user = get_bearer_user()
            if user is None:
                return jsonify({'status': 'error', 'success': False, 'msg': '未登录或 Bearer Token 无效'}), 401
            if user.role != 'admin' and user.role not in allowed:
                return jsonify({'status': 'error', 'success': False, 'msg': '当前账号没有权限执行该操作'}), 403
            return f(*args, **kwargs)
        return decorated_function
    return decorator

def role_required(*roles):
    """Require one of the given roles for page access."""
    def decorator(f):
        @wraps(f)
        def decorated_function(*args, **kwargs):
            if not current_user.is_authenticated:
                flash('请先登录后再继续', 'warning')
                return redirect(url_for('login', next=get_next_target()))
            if current_user.role != 'admin' and current_user.role not in roles:
                flash('当前账号没有权限访问该页面', 'danger')
                return redirect(url_for('index'))
            return f(*args, **kwargs)
        return decorated_function
    return decorator

