# ==================== Operation ====================
def log_operation(operation_type, operation_content, target_type=None, target_id=None):
    """Write an operation log record."""
    try:
        if not current_user or not current_user.is_authenticated:
            return

        log = OperationLog(
            user_id=current_user.id,
            operation_type=operation_type or '其他操作',
            operation_content=operation_content or '',
            target_type=target_type,
            target_id=target_id,
            ip_address=request.remote_addr if request else None
        )
        db.session.add(log)
        try:
            db.session.commit()
        except Exception as e:
            db.session.rollback()
            app.logger.error(f'数据库操作失败: {e}')
    except Exception as e:
        db.session.rollback()
        app.logger.error(f'log_operation failed: {e}')

def get_recent_operation_logs(target_type, target_id, limit=10):
    """IO-AUDIT-FIX-2026-07-27 m-07: 只读查询某单据最近 N 条操作日志.

    失败时返回空列表，确保不影响详情页主流程渲染。
    """
    try:
        if not target_type or not target_id:
            return []
        return (
            OperationLog.query
            .options(joinedload(OperationLog.user))
            .filter(
                OperationLog.target_type == target_type,
                OperationLog.target_id == target_id,
            )
            .order_by(OperationLog.created_at.desc(), OperationLog.id.desc())
            .limit(limit)
            .all()
        )
    except Exception as e:
        app.logger.warning(f'get_recent_operation_logs failed: {e}')
        return []

def api_material_payload(material):
    warehouse_code = getattr(material, 'warehouse', '') or ''
    location_code = ''
    if location_management_enabled():
        location_row = LocationInventory.query.filter_by(material_id=material.id).order_by(
            LocationInventory.quantity.desc(),
            LocationInventory.location.asc()
        ).first()
        location_code = location_row.location if location_row else ''
    return {
        'id': material.id,
        'code': material.code or '',
        'name': material.name or '',
        'brand': material.brand or '',
        'spec': material.spec or '',
        'unit': material.unit.name if material.unit else '',
        'price': float(material.price or 0),
        'stock': material.stock or 0,
        'warehouse_code': warehouse_code,
        'location_code': location_code,
    }

def api_json_error(message, status_code=400):
    return jsonify({'status': 'error', 'success': False, 'msg': message, 'message': message}), status_code

def api_json_success(data=None, message='操作成功'):
    return jsonify({'status': 'success', 'success': True, 'msg': message, 'message': message, 'data': data or {}})

def parse_api_lines(payload):
    lines = payload.get('lines') if isinstance(payload, dict) else None
    if not isinstance(lines, list) or not lines:
        return None, '明细不能为空'

    parsed = []
    for index, line in enumerate(lines, start=1):
        if not isinstance(line, dict):
            return None, f'第 {index} 行格式错误'
        code = (line.get('material_code') or line.get('code') or '').strip()
        if not code:
            return None, f'第 {index} 行缺少物料编码'
        quantity = parse_bounded_number(line.get('quantity'), 0)
        if quantity is None or quantity <= 0:
            return None, f'第 {index} 行数量必须是 0 至 1000000000000 的有限数字'
        material = Material.query.filter_by(code=code).first()
        if not material:
            return None, f'物料不存在：{code}'
        parsed.append((material, quantity, line))
    return parsed, None






