@app.route('/')
@login_required
def index():
    total_materials = Material.query.count()
    low_stock = Material.query.filter(_material_low_stock_filter()).count() if inventory_alert_enabled() else 0
    pending_in = InOrder.query.filter_by(status='pending').count()
    pending_out = OutOrder.query.filter_by(status='pending').count()
    pending_purchase = PurchaseRequest.query.filter_by(status='pending').count()
    purchase_order_summary = build_purchase_order_todo_summary()
    pending_stock_tasks = pending_in + pending_out + purchase_order_summary.get('open_count', 0) + low_stock
    today_in = InOrder.query.filter_by(date=date.today(), status='completed').count()
    today_out = OutOrder.query.filter_by(date=date.today(), status='completed').count()

    recent_in = InOrder.query.options(joinedload(InOrder.supplier)).order_by(InOrder.created_at.desc()).limit(5).all()
    recent_out = OutOrder.query.options(joinedload(OutOrder.department)).order_by(OutOrder.created_at.desc()).limit(5).all()
    recent_purchase = PurchaseRequest.query.order_by(PurchaseRequest.created_at.desc()).limit(5).all()

    in_progress_orders = (
        InOrder.query.options(joinedload(InOrder.supplier))
        .filter(InOrder.status == 'pending')
        .order_by(InOrder.created_at.desc(), InOrder.id.desc())
        .limit(5)
        .all()
    )
    out_progress_orders = (
        OutOrder.query.options(joinedload(OutOrder.department))
        .filter(OutOrder.status == 'pending')
        .order_by(OutOrder.created_at.desc(), OutOrder.id.desc())
        .limit(5)
        .all()
    )
    purchase_pending_orders = (
        PurchaseRequest.query.filter(PurchaseRequest.status == 'pending')
        .order_by(PurchaseRequest.created_at.desc(), PurchaseRequest.id.desc())
        .limit(5)
        .all()
    )
    purchase_order_pending_orders = (
        PurchaseOrder.query.options(joinedload(PurchaseOrder.supplier))
        .filter(PurchaseOrder.status.in_(('pending', 'partial')))
        .order_by(
            PurchaseOrder.expected_date.asc().nullslast(),
            PurchaseOrder.date.asc(),
            PurchaseOrder.id.asc()
        )
        .limit(5)
        .all()
    )

    recent_work_items = []
    for order in recent_in[:3]:
        recent_work_items.append({
            'type': '入库单',
            'icon': 'bi-box-arrow-in-down',
            'badge': 'success',
            'order_no': order.order_no,
            'date': order.date,
            'status': order.status,
            'link': url_for('in_order_detail', id=order.id),
            'summary': order.supplier.name if order.supplier else '未选择供应商'
        })
    for order in recent_out[:3]:
        recent_work_items.append({
            'type': '领料单',
            'icon': 'bi-box-arrow-up',
            'badge': 'primary',
            'order_no': order.order_no,
            'date': order.date,
            'status': order.status,
            'link': url_for('out_order_detail', id=order.id),
            'summary': (order.department.name if order.department else '') or order.purpose or '未填写领用对象'
        })
    for order in recent_purchase[:3]:
        recent_work_items.append({
            'type': '采购申请',
            'icon': 'bi-cart-plus',
            'badge': 'warning',
            'order_no': order.request_no,
            'date': order.date,
            'status': order.status,
            'link': url_for('purchase_request_detail', id=order.id),
            'summary': order.applicant or '未填写申请人'
        })
    recent_work_items.sort(key=lambda item: item['date'] or date.min, reverse=True)
    recent_work_items = recent_work_items[:6]

    return render_template('index.html',
                         total_materials=total_materials,
                         low_stock=low_stock,
                         pending_in=pending_in,
                         pending_out=pending_out,
                         pending_purchase=pending_purchase,
                         pending_stock_tasks=pending_stock_tasks,
                         purchase_order_summary=purchase_order_summary,
                         today_in=today_in,
                         today_out=today_out,
                         today_date=date.today().strftime('%Y-%m-%d'),
                         recent_in=recent_in,
                         recent_out=recent_out,
                         in_progress_orders=in_progress_orders,
                         out_progress_orders=out_progress_orders,
                         purchase_pending_orders=purchase_pending_orders,
                         purchase_order_pending_orders=purchase_order_pending_orders,
                         recent_work_items=recent_work_items)

@app.route('/api/subcontract/quick_issue', methods=['POST'])
@require_role('production')
@login_required
def api_subcontract_quick_issue():
    """Issue subcontract materials quickly."""
    if current_user.role not in ['admin', 'production']:
        return api_error('当前账号没有权限执行发料')

    data = request.get_json(silent=True) or {}
    order_id = data.get('order_id')
    items = data.get('items', [])

    if not order_id:
        return api_error('缺少委外单 ID')
    if not items:
        return api_error('请至少选择一条发料明细')

    order = db.session.get(SubcontractOrder, order_id)
    if not order:
        return api_error('委外单不存在，请刷新后重试')

    # P0-BUGFIX: 仓库必填，从父委外单继承（AGENTS.md 规则一）
    warehouse = getattr(order, 'warehouse', '') or ''
    if not warehouse:
        return api_error('委外单未指定仓库，请先编辑委外单补充仓库')

    validated_items = []
    for item in items:
        material_id = item.get('material_id')
        quantity = item.get('quantity', 0)
        if not material_id or quantity <= 0:
            continue

        material = db.session.get(Material, material_id)
        if not material:
            return jsonify({'status': 'error', 'msg': f'物料 ID {material_id} 不存在，请刷新后重试'}), 404

        current_stock = normalize_stock_quantity(material.stock or 0)
        quantity = normalize_stock_quantity(quantity)
        if not allow_negative_stock() and not is_stock_sufficient(current_stock, quantity):
            return jsonify({
                'status': 'error',
                'msg': f'库存不足，当前库存 {current_stock:.2f}，发料数量 {quantity:.2f}'
            }), 400

        validated_items.append((material, quantity))

    if not validated_items:
        return api_error('发料明细无效，请检查数量后重试')

    # 创建发料单时显式设置 status='completed'，与 quick_issue_subcontract 对齐，
    # 否则 status 默认 'pending' 但库存已扣，会导致单据卡在 pending 无法后续完成
    issue_no = generate_order_no('SF')
    issue = SubcontractIssue(
        issue_no=issue_no,
        subcontract_order_id=order_id,
        supplier_id=order.supplier_id,
        warehouse=warehouse,
        status='completed',
        operator_id=current_user.id
    )
    db.session.add(issue)
    db.session.flush()

    # Add issue details
    for material, quantity in validated_items:
        issue_item = SubcontractIssueItem(
            issue_id=issue.id,
            material_id=material.id,
            quantity=quantity
        )
        db.session.add(issue_item)

        # 使用原子扣减并检查返回值，避免并发超卖与失败仍提交
        ok, error_msg, _ = deduct_stock_atomic(material.id, quantity,
                     transaction_type='subcontract_issue',
                     reference_type='subcontract_issue',
                     reference_id=issue.id,
                     warehouse=issue.warehouse)
        if not ok:
            db.session.rollback()
            return jsonify({'status': 'error', 'msg': error_msg or '库存扣减失败'}), 400

    # Update order status
    if order.status == 'pending':
        order.status = 'processing'

    try:
        db.session.commit()
    except Exception as e:
        db.session.rollback()
        app.logger.error(f"委外发料失败: {e}")
        return jsonify({'status': 'error', 'msg': '发料失败，请稍后重试'}), 500
    log_operation('委外发料', f'委外发料单：{issue_no}', 'subcontract_issue', issue.id)
    return jsonify({'status': 'success', 'msg': '发料成功'})

@app.route('/api/subcontract/quick_receive', methods=['POST'])
@require_role('production')
@login_required
def api_subcontract_quick_receive():
    """Receive subcontract finished goods quickly."""
    if current_user.role not in ['admin', 'production']:
        return api_error('当前账号没有权限执行收货')

    data = request.get_json(silent=True) or {}
    order_id = data.get('order_id')
    material_id = data.get('material_id')
    quantity = data.get('quantity', 0)
    scrap_qty = data.get('scrap_qty', 0)

    if not order_id:
        return api_error('缺少委外单 ID')
    if not material_id:
        return api_error('缺少成品物料 ID')
    if quantity <= 0:
        return api_error('收货数量必须大于 0')

    order = db.session.get(SubcontractOrder, order_id)
    if not order:
        return api_error('委外单不存在，请刷新后重试')

    # P0-BUGFIX: 仓库必填，从父委外单继承（AGENTS.md 规则一）
    warehouse = getattr(order, 'warehouse', '') or ''
    if not warehouse:
        return api_error('委外单未指定仓库，请先编辑委外单补充仓库')

    material = db.session.get(Material, material_id)
    if not material:
        return api_error('成品物料不存在，请刷新后重试')

    # Create receive order
    # 显式设置 status='completed'，与 quick_receive_subcontract 对齐
    receive_no = generate_order_no('SR')
    receive = SubcontractReceive(
        receive_no=receive_no,
        subcontract_order_id=order_id,
        supplier_id=order.supplier_id,
        warehouse=warehouse,
        status='completed',
        operator_id=current_user.id
    )
    db.session.add(receive)
    db.session.flush()

    # Add receive detail
    receive_item = SubcontractReceiveItem(
        receive_id=receive.id,
        material_id=material_id,
        quantity=quantity,
        scrap_quantity=scrap_qty
    )
    db.session.add(receive_item)

    # Add received material stock
    ok, msg = add_stock(material, quantity,
                        transaction_type='subcontract_receive',
                        reference_type='subcontract_receive',
                        reference_id=receive.id,
                        warehouse=receive.warehouse)
    if not ok:
        db.session.rollback()
        return jsonify({'status': 'error', 'msg': msg or '库存增加失败'}), 500

    # Update order status
    # 注意：上面 db.session.add(receive_item) 后，SQLAlchemy 默认 autoflush 会在下次查询前
    # 把 receive_item 刷入数据库，因此下面的 sum 查询已包含本次 quantity，不能再 + quantity，
    # 否则 received_qty 会被双倍计算，可能把未完成订单误判为 completed
    order_items = SubcontractItem.query.filter_by(subcontract_order_id=order_id).all()
    total_qty = sum(item.quantity for item in order_items)
    received_qty = sum(item.quantity for item in
                      SubcontractReceiveItem.query.join(SubcontractReceive)
                      .filter(SubcontractReceive.subcontract_order_id == order_id).all())

    if received_qty >= total_qty:
        order.status = 'completed'
    elif received_qty > 0:
        order.status = 'partial' if order.status != 'processing' else 'processing'

    try:
        db.session.commit()
    except Exception as e:
        db.session.rollback()
        app.logger.error(f"委外收货失败: {e}")
        return jsonify({'status': 'error', 'msg': '收货失败，请稍后重试'}), 500
    log_operation('委外收货', f'委外收货单：{receive_no}', 'subcontract_receive', receive.id)
    return jsonify({'status': 'success', 'msg': '收货成功'})

def validate_password_strength(password):
    """Validate password strength rules.

    策略：最小长度 6 位（可通过环境变量 PASSWORD_MIN_LENGTH 覆盖）。
    """
    if not password:
        return False, '密码不能为空'
    min_length = int(os.environ.get('PASSWORD_MIN_LENGTH', SYSTEM_CONFIG.get('PASSWORD_MIN_LENGTH', 6)))
    if len(password) < min_length:
        return False, f'密码长度不能少于 {min_length} 位'
    return True, None




