def _audit_date_arg(name):
    value = (request.args.get(name) or '').strip()
    if not value:
        return ''
    try:
        datetime.strptime(value, '%Y-%m-%d')
        return value
    except ValueError:
        return ''

def _audit_datetime_bounds(date_start, date_end):
    if date_start:
        start_dt = datetime.strptime(date_start, '%Y-%m-%d')
    else:
        start_dt = datetime.combine(date.today() - timedelta(days=7), time.min)
    if date_end:
        end_dt = datetime.strptime(date_end, '%Y-%m-%d') + timedelta(days=1)
    else:
        end_dt = datetime.now() + timedelta(seconds=1)
    if start_dt > end_dt:
        start_dt, end_dt = end_dt - timedelta(days=1), start_dt + timedelta(days=1)
    return start_dt, end_dt

def _audit_risk_condition(model, operation_attr, content_attrs):
    conditions = [
        operation_attr.ilike('%delete%'),
        operation_attr.ilike('%删除%'),
        operation_attr.ilike('%反审%'),
        operation_attr.ilike('%恢复%'),
        operation_attr.ilike('%备份%'),
        operation_attr.ilike('%清理%'),
    ]
    for attr in content_attrs:
        conditions.extend([
            attr.ilike('%删除%'),
            attr.ilike('%反审%'),
            attr.ilike('%恢复%'),
            attr.ilike('%备份%'),
            attr.ilike('%清理%'),
        ])
    return db.or_(*conditions)

def _audit_iter_pages(page, pages):
    if pages <= 0:
        return []
    values = []
    for num in range(1, pages + 1):
        if num <= 2 or num > pages - 2 or abs(num - page) <= 2:
            values.append(num)
        elif values and values[-1] is not None:
            values.append(None)
    return values




DISABLED_USER_STATUSES = {'disabled', 'inactive'}
USER_STATUS_LABELS = {
    'normal': '正常/启用',
    'disabled': '禁用',
    'inactive': '停用',
}

def _normalize_user_status(status):
    status = (status or 'normal').strip()
    return status if status in USER_STATUS_LABELS else 'normal'

def _user_status_label(status):
    return USER_STATUS_LABELS.get(_normalize_user_status(status), status or 'normal')

def _has_other_active_admin(user_id):
    return User.query.filter(
        User.role == 'admin',
        User.id != user_id,
        db.or_(User.status.is_(None), User.status.notin_(list(DISABLED_USER_STATUSES)))
    ).first() is not None

