def _revert_completed_to_pending():
    """将全部 completed 单据改为 pending，模拟「人工反提交后单据回到草稿」。

    AGENTS.md 硬规则：禁止直接删除已完成单据 → 必须先反提交 → 单据回到草稿 → 再删除草稿。
    库存回退通过下方 _zero_all_material_stock 一次性归零（语义等价于逐张反提交）。
    """
    # 业务单据主表：completed -> pending
    completed_models = [
        InOrder, OutOrder, TransferOrder, AdjustmentOrder,
        InventoryCheck, InventoryCheckScan, SubcontractOrder, SubcontractIssue,
        SubcontractReceive, SubcontractProgress, ProductionRequisition,
        PurchaseRequest, PurchaseOrder, SalesOrder, AfterSaleOutOrder,
    ]
    reverted_count = 0
    for model_cls in completed_models:
        try:
            count = model_cls.query.filter_by(status='completed').update(
                {model_cls.status: 'pending'},
                synchronize_session=False,
            )
            reverted_count += count
        except Exception as exc:
            app.logger.warning('revert %s failed: %s', model_cls.__name__, exc)
    return reverted_count

def _zero_all_material_stock():
    """把所有物料的 stock 设为 0，语义等价于「回退所有已完成单据的库存变动」。"""
    try:
        return Material.query.update({Material.stock: 0}, synchronize_session=False)
    except Exception as exc:
        app.logger.warning('zero stock failed: %s', exc)
        return 0

def _bulk_delete_model(model_cls):
    """单表全量删除，返回删除条数。"""
    try:
        count = model_cls.query.delete(synchronize_session=False)
        return count
    except Exception as exc:
        app.logger.warning('delete %s failed: %s', model_cls.__name__, exc)
        db.session.rollback()
        return 0

def _init_business_data_keep_users_and_settings(include_master_data=False):
    """执行核心清理逻辑。

    注意（SYS-AUDIT-001）：函数名中的 keep_users_and_settings 是历史命名，
    SystemSetting 实际上在 INIT_LOG_TABLES 中，会被全量删除。调用方
    （execute_init_business_data 路由）在清理完成后会立即调用
    ensure_default_system_settings() 恢复默认值，避免设置表空窗期。

    1. 全部 completed 单据先变 pending（模拟人工反提交）
    2. 物料库存归零（等价于回退全部库存）
    3. 删除全部业务单据主表 + 明细表
    4. 删除库存流水/下推/期初
    5. 删除日志表（业务日志/通知/登录/Token/微信分享，含 SystemSetting）
    6. 删除全部 AI 子表
    7. 可选：删除主数据（物料/分类/单位/供应商/客户/仓库/部门/员工/合同/BOM/模板/字段配置）
    8. 保留 User、当前管理员自身（SystemSetting 由调用方恢复默认值）
    9. 最后清空 OperationAudit 自身（init 操作本身的审计需要先写入，所以最后清）
    """
    deleted = {
        'reverted_to_pending': 0,
        'zeroed_materials': 0,
        'business': 0,
        'business_items': 0,
        'inventory': 0,
        'logs': 0,
        'ai': 0,
        'master': 0,
    }

    # 1. 已完成单据先变 pending
    deleted['reverted_to_pending'] = _revert_completed_to_pending()

    # 2. 库存归零
    deleted['zeroed_materials'] = _zero_all_material_stock()

    # 3. 业务单据主表（先主表后明细，避免外键报错）
    # 明细表在主表之前先删，但有外键反向引用时需要按依赖顺序
    for label, model_cls in INIT_BUSINESS_ITEM_TABLES:
        deleted['business_items'] += _bulk_delete_model(model_cls)
    db.session.commit()
    for label, model_cls in INIT_BUSINESS_TABLES:
        deleted['business'] += _bulk_delete_model(model_cls)
    db.session.commit()

    # 4. 库存/流水
    for label, model_cls in INIT_INVENTORY_TABLES:
        deleted['inventory'] += _bulk_delete_model(model_cls)
    db.session.commit()

    # 5. 日志
    for label, model_cls in INIT_LOG_TABLES:
        deleted['logs'] += _bulk_delete_model(model_cls)
    db.session.commit()

    # 6. AI 子表
    for label, model_cls in INIT_AI_TABLES:
        deleted['ai'] += _bulk_delete_model(model_cls)
    db.session.commit()

    # 7. 可选主数据
    if include_master_data:
        for label, model_cls in INIT_MASTER_TABLES:
            deleted['master'] += _bulk_delete_model(model_cls)
        db.session.commit()

    return deleted



def _opening_stock_payload_from_request():
    material_id = request.form.get('material_id', type=int)
    warehouse_id = request.form.get('warehouse_id', type=int)
    # AI-OS-APP-001：支持表单日期，缺省当天
    raw_date = (request.form.get('date') or '').strip()
    doc_date = _parse_opening_stock_date(raw_date)
    # BUG-2026-08-16-002：期初库位（可选，空则以仓库名作占位行落库位账）
    location = (request.form.get('location') or '').strip()
    try:
        quantity = float(request.form.get('quantity') or '')
    except (TypeError, ValueError):
        quantity = None
    price = parse_float_value(request.form.get('price'), 0)
    remark = (request.form.get('remark') or '').strip()
    if not material_id:
        return None, '请选择物料'
    material = Material.query.filter_by(id=material_id).with_for_update().first()
    if not material:
        return None, '物料不存在'
    if not warehouse_id:
        return None, '请选择仓库'  # AI-OS-MW-001: 仓库必填
    warehouse = Warehouse.query.filter_by(id=warehouse_id).with_for_update().first()
    if not warehouse:
        return None, '仓库不存在'
    if (warehouse.status or 'active') != 'active':
        return None, f'仓库 {warehouse.name} 已停用，禁止期初建账'  # AI-OS-MW-001: 禁止停用仓库
    if quantity is None:
        return None, '请输入数量'
    if quantity < 0:
        return None, '期初数量不能小于 0'
    if price < 0:
        return None, '单价不能小于 0'
    return {
        'material': material,
        'warehouse': warehouse,
        'date': doc_date,
        'location': location,
        'quantity': normalize_stock_quantity(quantity),
        'price': round_to_2_decimals(price),
        'amount': round_to_2_decimals(quantity * price),
        'remark': remark or None,
    }, None

def _parse_opening_stock_date(raw):
    """解析期初建账日期，非法或缺省返回当天。"""
    raw = (raw or '').strip()
    if raw:
        try:
            return datetime.strptime(raw, '%Y-%m-%d').date()
        except (ValueError, TypeError):
            pass
    return date.today()

def _apply_opening_stock_balance(opening, material, new_quantity, new_price, new_amount, remark, warehouse=None, doc_date=None, location=''):
    old_quantity = normalize_stock_quantity(opening.quantity or 0) if opening else 0
    quantity_delta = normalize_stock_quantity(new_quantity - old_quantity)
    doc_date = doc_date or getattr(opening, 'date', None) or date.today()
    location = (location or getattr(opening, 'location', '') or '').strip()

    if opening is None:
        opening = OpeningStock(
            material_id=material.id,
            warehouse_id=warehouse.id if warehouse else None,
            date=doc_date,
            location=location,
            quantity=new_quantity,
            price=new_price,
            amount=new_amount,
            remark=remark,
            operator_id=current_user.id if current_user.is_authenticated else None,
        )
        db.session.add(opening)
        db.session.flush()
    else:
        opening.quantity = new_quantity
        opening.price = new_price
        opening.amount = new_amount
        opening.remark = remark
        opening.date = doc_date
        opening.location = location
        opening.operator_id = current_user.id if current_user.is_authenticated else None
        opening.updated_at = datetime.now()
        db.session.flush()

    if abs(quantity_delta) > STOCK_COMPARE_EPSILON:
        db.session.execute(
            sa_update(Material)
            .where(Material.id == material.id)
            .values(stock=Material.stock + quantity_delta)
        )
        db.session.expire(material, ['stock'])
        # AI-OS-MW-001：台账和月报都依赖 location 字段
        location_value = warehouse.name if warehouse else (opening.warehouse.name if opening.warehouse else '')
        db.session.add(StockTransaction(
            material_id=material.id,
            transaction_type='opening',
            quantity=quantity_delta,
            location=location_value,
            reference_type='opening_stock',
            reference_id=opening.id,
            operator_id=current_user.id if current_user.is_authenticated else None,
            remark=remark or '期初库存调整'
        ))

    # BUG-2026-08-16-002：开启库位管理时同步库位账，防止 Material.stock 总账与
    # LocationInventory 库位账分叉（此前期初只改总账，库存查询/报表/移动端全部看不到）。
    # 未填库位时以仓库名作占位行，保证仓库级库存聚合（get_warehouse_stock_quantities）可见。
    if location_management_enabled() and warehouse and abs(quantity_delta) > STOCK_COMPARE_EPSILON:
        effective_location = location or (warehouse.name or '').strip()
        if effective_location:
            if quantity_delta < 0 and old_quantity > 0:
                # 历史数据回填：老库位账缺行时先按旧期初数量补基线再扣差额，
                # 最终行值 == new_quantity，与 Material.stock 口径一致。
                legacy_row = LocationInventory.query.filter(
                    LocationInventory.material_id == material.id,
                    LocationInventory.location == effective_location,
                    LocationInventory.warehouse_id == warehouse.id,
                ).first()
                if not legacy_row:
                    ok_backfill, msg_backfill = add_location_inventory_atomic(
                        material.id, effective_location, old_quantity,
                        material_code_hint=material.code, warehouse_id=warehouse.id,
                    )
                    if not ok_backfill:
                        raise ValueError(msg_backfill)
            ok_inv, msg_inv = update_location_inventory(
                material, effective_location, quantity_delta, warehouse=warehouse)
            if not ok_inv:
                raise ValueError(msg_inv)
    return opening, quantity_delta


def _material_image_search_terms(material):
    """按名称+规格构造搜索词，品牌作为补充，去噪声后缀。

    用户要求：查找要按名称规格找图。
    """
    parts = [
        material.name or '',
        material.spec or '',
        material.brand or '',
    ]
    tokens = []
    seen = set()
    for part in parts:
        for token in re.split(r'[\s,，;；/|]+', str(part).strip()):
            token = token.strip()
            if not token or token.lower() in seen:
                continue
            seen.add(token.lower())
            tokens.append(token)
    return ' '.join(tokens[:8]).strip()

def _extract_bing_image_candidates(html, limit=12):
    candidates = []
    seen = set()
    patterns = [
        r'm="(?P<meta>{.*?})"',
        r'&quot;m&quot;:&quot;(?P<meta>{.*?})&quot;',
    ]
    for pattern in patterns:
        for match in re.finditer(pattern, html or '', flags=re.S):
            raw = match.group('meta')
            raw = raw.replace('&quot;', '"').replace('&amp;', '&')
            try:
                meta = json.loads(raw)
            except Exception:
                continue
            image_url = (meta.get('murl') or '').strip()
            if not image_url or image_url in seen:
                continue
            if not image_url.lower().startswith(('http://', 'https://')):
                continue
            seen.add(image_url)
            candidates.append({
                'image_url': image_url,
                'thumb_url': (meta.get('turl') or image_url).strip(),
                'source_url': (meta.get('purl') or '').strip(),
                'title': (meta.get('t') or meta.get('desc') or '').strip()[:120],
            })
            if len(candidates) >= limit:
                return candidates
    return candidates

def _extract_baidu_image_candidates(data, limit=12):
    """解析百度图片 acjson 接口返回的 JSON，提取候选图列表。

    百度返回的 objURL/fromURL 常为编码串不可直接用，
    取 middleURL（百度缓存中等图）为 image_url，thumbURL 为缩略图。
    """
    candidates = []
    seen = set()
    items = data.get('data', []) if isinstance(data, dict) else []
    for item in items:
        if not isinstance(item, dict):
            continue
        image_url = (item.get('middleURL') or item.get('thumbURL') or '').strip()
        if not image_url or image_url in seen:
            continue
        if not image_url.lower().startswith(('http://', 'https://')):
            continue
        seen.add(image_url)
        thumb_url = (item.get('thumbURL') or image_url).strip()
        # fromPageTitle 含 <strong> 等 HTML 标签，需清理
        title_raw = item.get('fromPageTitle') or item.get('title') or ''
        title = re.sub(r'<[^>]+>', '', title_raw).strip()[:120]
        source_url = item.get('fromURL') or ''
        if not source_url.lower().startswith(('http://', 'https://')):
            source_url = ''
        candidates.append({
            'image_url': image_url,
            'thumb_url': thumb_url,
            'source_url': source_url,
            'title': title,
        })
        if len(candidates) >= limit:
            return candidates
    return candidates

def _search_material_images_online(material, limit=12):
    """按名称+规格搜索物料图片。

    搜索方向：国内优先。首选百度图片（JSON API，结果丰富、国内速度快），
    百度无结果或异常时 fallback 到 Bing 图片（HTML 解析）。
    """
    query = _material_image_search_terms(material)
    if not query:
        return [], ''
    headers = {
        'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 '
                      '(KHTML, like Gecko) Chrome/126.0 Safari/537.36',
        'Accept-Language': 'zh-CN,zh;q=0.9,en;q=0.6',
    }

    # 1) 首选：百度图片 acjson 接口（国内 JSON API）
    try:
        baidu_url = (
            f'https://image.baidu.com/search/acjson?tn=resultjson_com'
            f'&word={quote_plus(query)}&queryWord={quote_plus(query)}'
            f'&pn=0&rn={limit}&ie=utf-8&oe=utf-8&cl=2&lm=-1&st=-1&face=0&nc=1'
        )
        baidu_headers = {**headers, 'Referer': 'https://image.baidu.com/'}
        resp = requests.get(baidu_url, headers=baidu_headers, timeout=8)
        resp.raise_for_status()
        candidates = _extract_baidu_image_candidates(resp.json(), limit=limit)
        if candidates:
            return candidates, query
        # 百度返回空结果，继续尝试 Bing
    except Exception:
        pass  # 百度失败不阻断，继续 fallback

    # 2) Fallback：Bing 图片（HTML 解析）
    try:
        bing_url = f'https://www.bing.com/images/search?q={quote_plus(query)}&form=HDRSC2&first=1'
        resp = requests.get(bing_url, headers=headers, timeout=8)
        resp.raise_for_status()
        return _extract_bing_image_candidates(resp.text, limit=limit), query
    except Exception:
        return [], query

def _is_private_or_loopback_host(hostname):
    """检查主机名是否指向内网/回环/私有地址，用于阻止 SSRF。

    解析 hostname 的所有 A/AAAA 记录，只要有一个落在私有/回环/链路本地/
    保留地址段即判定为内网地址。
    """
    try:
        infos = socket.getaddrinfo(hostname, None, proto=socket.IPPROTO_TCP)
    except socket.gaierror:
        # DNS 解析失败：保守拒绝，避免攻击者用不存在的域名绕过校验
        return True
    for info in infos:
        ip_str = info[4][0]
        try:
            ip = ipaddress.ip_address(ip_str)
        except ValueError:
            return True
        if ip.is_private or ip.is_loopback or ip.is_link_local or ip.is_reserved or ip.is_multicast:
            return True
    return False

def _save_material_image_from_url(material, image_url):
    image_url = (image_url or '').strip()
    if not image_url.lower().startswith(('http://', 'https://')):
        return None, '图片地址无效'

    # SSRF 防护：解析 URL 主机名，拒绝指向内网/回环/私有地址的请求
    parsed_url = urlparse(image_url)
    hostname = parsed_url.hostname
    if not hostname:
        return None, '图片地址无效'
    if _is_private_or_loopback_host(hostname):
        return None, '不允许访问内网地址'

    headers = {
        'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 '
                      '(KHTML, like Gecko) Chrome/126.0 Safari/537.36',
        'Referer': 'https://www.bing.com/',
    }
    # BUG-2026-08-13-003: requests.get 不接受 max_redirects 参数，改用手动逐跳跟随
    # BUG-2026-08-13-004: 对每一跳 Location 主机重新做内网校验
    MAX_REDIRECTS = 5
    next_url = image_url
    response = requests.get(next_url, headers=headers, timeout=12, stream=True, allow_redirects=False)
    redirects = 0
    while response.is_redirect or response.is_permanent_redirect:
        if redirects >= MAX_REDIRECTS:
            response.close()
            return None, '图片地址重定向次数过多'
        redirects += 1
        location = response.headers.get('Location')
        response.close()
        if not location:
            return None, '图片地址重定向目标缺失'
        next_url = urljoin(next_url, location)
        redir_parsed = urlparse(next_url)
        if redir_parsed.scheme not in ('http', 'https'):
            return None, '不允许的重定向协议'
        redir_host = redir_parsed.hostname
        if not redir_host or _is_private_or_loopback_host(redir_host):
            return None, '不允许访问内网地址'
        response = requests.get(next_url, headers=headers, timeout=12, stream=True, allow_redirects=False)
    try:
        response.raise_for_status()
        content_type = (response.headers.get('Content-Type') or '').split(';', 1)[0].lower()
        if content_type and not content_type.startswith('image/'):
            response.close()
            return None, '远程地址不是图片'
        max_bytes = 8 * 1024 * 1024
        image_bytes = bytearray()
        for chunk in response.iter_content(chunk_size=65536):
            if not chunk:
                continue
            image_bytes.extend(chunk)
            if len(image_bytes) > max_bytes:
                response.close()
                return None, '图片文件过大'
    finally:
        response.close()

    try:
        from PIL import Image, ImageOps
        with Image.open(io.BytesIO(bytes(image_bytes))) as image:
            image = ImageOps.exif_transpose(image)
            if image.mode not in ('RGB', 'L'):
                if image.mode in ('RGBA', 'LA'):
                    background = Image.new('RGB', image.size, 'white')
                    rgba = image.convert('RGBA')
                    background.paste(rgba, mask=rgba.split()[-1])
                    image = background
                else:
                    image = image.convert('RGB')
            elif image.mode == 'L':
                image = image.convert('RGB')
            if max(image.size) > 1600:
                image.thumbnail((1600, 1600), Image.Resampling.LANCZOS)
            relative_dir = os.path.join('uploads', 'material_images')
            absolute_dir = os.path.join(app.static_folder, relative_dir)
            os.makedirs(absolute_dir, exist_ok=True)
            filename = f'material_{material.id}_{uuid.uuid4().hex}.jpg'
            absolute_path = os.path.join(absolute_dir, filename)
            image.save(absolute_path, format='JPEG', quality=88, optimize=True)
    except Exception as exc:
        app.logger.warning('Material image download validation failed: %s', exc)
        return None, '图片下载后无法识别，请换一张'

    return f'uploads/material_images/{filename}', ''

def generate_material_copy_code(source):
    """
    根据源物料生成新的物料编码：原物料分类 + 流水号。

    - 以源物料所属分类的编码为前缀，取该前缀下已存在物料的最大流水号 + 1，
      生成 `{分类编码}{三位流水号}`。例如分类编码 101，已有最大编号 101009，
      则复制生成 101010（流水号 009 → 010，可见三位补零）。
    - 原物料无分类时，退回到基于原编码的旧逻辑（末尾数字递增，或追加 -COPY 后缀）。
    """
    if source is None:
        raise ValueError("物料不能为空")

    # 优先使用原物料分类编码作为前缀
    category = getattr(source, 'category', None)
    prefix = (category.code if category and category.code else '').strip()
    if not prefix:
        # 原物料无分类：回退到基于原编码的旧逻辑
        source_code = (source.code or '').strip()
        if not source_code:
            raise ValueError("物料编码不能为空")
        match = re.match(r'^(.*?)(\d+)$', source_code)
        if match:
            old_prefix, number_text = match.groups()
            width = len(number_text)
            max_number = int(number_text)
            for (code,) in Material.query.with_entities(Material.code).filter(Material.code.like(f'{old_prefix}%')).all():
                code_match = re.match(rf'^{re.escape(old_prefix)}(\d+)$', code or '')
                if code_match:
                    max_number = max(max_number, int(code_match.group(1)))
            for next_number in range(max_number + 1, max_number + 10000):
                candidate = f'{old_prefix}{next_number:0{width}d}' if len(str(next_number)) <= width else f'{old_prefix}{next_number}'
                if not Material.query.filter_by(code=candidate).first():
                    return candidate
            raise ValueError("无法生成唯一编码，请检查数据")
        base_code = f"{source_code}-COPY"
        if not Material.query.filter_by(code=base_code).first():
            return base_code
        for index in range(2, 10000):
            candidate = f"{base_code}{index}"
            if not Material.query.filter_by(code=candidate).first():
                return candidate
        raise ValueError("无法生成唯一编码，请检查数据")

    # 有分类：按分类前缀 + 三位流水号（取该前缀下最大流水号 + 1）
    max_number = 0
    for (code,) in Material.query.with_entities(Material.code).filter(Material.code.like(f'{prefix}%')).all():
        code_match = re.match(rf'^{re.escape(prefix)}(\d+)$', code or '')
        if code_match:
            max_number = max(max_number, int(code_match.group(1)))
    for next_number in range(max_number + 1, max_number + 10000):
        candidate = f'{prefix}{next_number:03d}'
        if not Material.query.filter_by(code=candidate).first():
            return candidate
    raise ValueError("无法生成唯一编码，请检查数据")

def generate_material_copy_name(source_name, source_spec):
    base_name = (source_name or '').strip()
    if not base_name:
        return ''
    return base_name

def material_name_spec_exists(name, spec, exclude_id=None):
    query = Material.query.filter(
        Material.name == name,
        func.coalesce(Material.spec, '') == (spec or '')
    )
    if exclude_id:
        query = query.filter(Material.id != exclude_id)
    return query.first() is not None

def _nonempty_reference_values(*values):
    result = []
    seen = set()
    for value in values:
        text = str(value or '').strip()
        if text and text not in seen:
            seen.add(text)
            result.append(text)
    return result

def _format_delete_blockers(blockers):
    return '；'.join(f'{label} {count} 条' for label, count in blockers if count)

def _warehouse_delete_blockers(warehouse):
    values = _nonempty_reference_values(warehouse.name, warehouse.code)
    if not values:
        return []
    checks = [
        ('入库单', InOrder.query.filter(InOrder.warehouse.in_(values)).count()),
        ('领料单', OutOrder.query.filter(OutOrder.warehouse.in_(values)).count()),
        ('销售订单', SalesOrder.query.filter(SalesOrder.warehouse_id == warehouse.id).count()),
        ('调拨单', TransferOrder.query.filter(db.or_(TransferOrder.from_location.in_(values), TransferOrder.to_location.in_(values))).count()),
        ('库存调整明细', AdjustmentOrderItem.query.filter(AdjustmentOrderItem.location.in_(values)).count()),
        ('库位库存', LocationInventory.query.filter(LocationInventory.location.in_(values)).count()),
        ('库存流水', StockTransaction.query.filter(StockTransaction.location.in_(values)).count()),
    ]
    return [(label, count) for label, count in checks if count]

def _department_delete_blockers(department):
    values = _nonempty_reference_values(department.name, department.code)
    checks = [
        ('员工档案', Employee.query.filter(Employee.department_id == department.id).count()),
        ('领料单', OutOrder.query.filter(OutOrder.department_id == department.id).count()),
    ]
    if values:
        checks.extend([
            ('领料单文本部门', OutOrder.query.filter(OutOrder.customer.in_(values)).count()),
            ('采购申请部门', PurchaseRequest.query.filter(PurchaseRequest.department.in_(values)).count()),
        ])
    return [(label, count) for label, count in checks if count]

def _contract_delete_blockers(contract):
    """检查合同是否被业务单据引用，返回阻断原因列表。"""
    blockers = []
    refs = []
    if InOrder.query.filter_by(contract_id=contract.id).count() > 0:
        refs.append('采购入库单(头)')
    # M-05：明细行的 contract_id / contract_no 字符串引用也要校验，避免硬删后历史明细合同字段悬空
    if hasattr(InOrderItem, 'contract_id') and InOrderItem.query.filter_by(contract_id=contract.id).count() > 0:
        refs.append('采购入库单(明细行 contract_id)')
    if hasattr(InOrderItem, 'contract_no') and contract.contract_no and \
            InOrderItem.query.filter(InOrderItem.contract_no == contract.contract_no,
                                     InOrderItem.contract_id.is_(None)).count() > 0:
        refs.append('采购入库单(明细行 contract_no 字符串)')
    if OutOrder.query.filter_by(contract_id=contract.id).count() > 0:
        refs.append('领料出库单(头)')
    if hasattr(OutOrder, 'contract_no') and contract.contract_no and \
            OutOrder.query.filter(OutOrder.contract_no == contract.contract_no,
                                  OutOrder.contract_id.is_(None)).count() > 0:
        refs.append('领料出库单(contract_no 字符串)')
    if PurchaseOrder.query.filter_by(contract_id=contract.id).count() > 0:
        refs.append('采购订单(头)')
    # M-05：采购订单明细行 contract_no 字符串引用也要校验
    if hasattr(PurchaseOrderItem, 'contract_no') and contract.contract_no and \
            PurchaseOrderItem.query.filter(PurchaseOrderItem.contract_no == contract.contract_no,
                                            PurchaseOrderItem.contract_id.is_(None)).count() > 0:
        refs.append('采购订单(明细行 contract_no 字符串)')
    if SalesOrder.query.filter_by(contract_id=contract.id).count() > 0:
        refs.append('销售订单(头)')
    # M-05：销售订单明细行 contract_no 字符串引用也要校验
    if hasattr(SalesOrderItem, 'contract_no') and contract.contract_no and \
            SalesOrderItem.query.filter(SalesOrderItem.contract_no == contract.contract_no,
                                        SalesOrderItem.contract_id.is_(None)).count() > 0:
        refs.append('销售订单(明细行 contract_no 字符串)')
    # M-05：领料出库单明细行 contract_no 字符串引用也要校验
    if hasattr(OutOrderItem, 'contract_no') and contract.contract_no and \
            OutOrderItem.query.filter(OutOrderItem.contract_no == contract.contract_no,
                                       OutOrderItem.contract_id.is_(None)).count() > 0:
        refs.append('领料出库单(明细行 contract_no 字符串)')
    if refs:
        blockers.append('已被' + '、'.join(refs) + '引用')
    return blockers

# ==================== Category management ====================

def build_category_tree_rows(categories):
    category_list = list(categories)
    by_parent = {}
    by_id = {cat.id: cat for cat in category_list}
    for cat in category_list:
        parent_id = cat.parent_id if cat.parent_id in by_id and cat.parent_id != cat.id else None
        by_parent.setdefault(parent_id, []).append(cat)

    for siblings in by_parent.values():
        siblings.sort(key=lambda item: ((item.code or '').lower(), (item.name or '').lower(), item.id))

    rows = []
    visited = set()

    def walk(parent_id, level, path):
        children = by_parent.get(parent_id, [])
        for index, cat in enumerate(children):
            if cat.id in visited:
                continue
            visited.add(cat.id)
            is_last = index == len(children) - 1
            branch_parts = []
            for ancestor_last in path:
                branch_parts.append('    ' if ancestor_last else '│   ')
            branch_parts.append('└─ ' if is_last else '├─ ')
            rows.append({
                'category': cat,
                'level': level,
                'branch': ''.join(branch_parts) if level > 0 else '',
                'has_children': bool(by_parent.get(cat.id)),
            })
            walk(cat.id, level + 1, path + [is_last])

    walk(None, 0, [])
    for cat in category_list:
        if cat.id not in visited:
            rows.append({'category': cat, 'level': 0, 'branch': '', 'has_children': bool(by_parent.get(cat.id))})
    return rows

def build_category_parent_options(categories, exclude_id=None):
    rows = build_category_tree_rows(categories)
    options = []
    for row in rows:
        cat = row['category']
        if exclude_id and cat.id == exclude_id:
            continue
        options.append({
            'id': cat.id,
            'label': f"{row['branch']}{cat.code} {cat.name}",
            'level': row['level'],
        })
    return options

def ensure_material_category_tree_defaults():
    """Create practical root categories and attach existing flat categories once."""
    if startup_db_upgrade_disabled():
        return

    roots = [
        ('100', '配件/耗材'),
        ('200', '组件配件'),
        ('300', '整机设备'),
        ('400', '用品工具'),
    ]
    root_by_code = {}
    changed = False
    for code, name in roots:
        root = MaterialCategory.query.filter_by(code=code).first()
        if not root:
            root = MaterialCategory.query.filter_by(name=name).first()
            if root:
                root.code = code
                root.parent_id = None
                changed = True
            else:
                root = MaterialCategory(code=code, name=name)
                db.session.add(root)
                db.session.flush()
                changed = True
        root_by_code[code] = root

    mapping = {
        '1': root_by_code['100'].id,
        '2': root_by_code['200'].id,
        '3': root_by_code['300'].id,
        '4': root_by_code['400'].id,
    }
    for cat in MaterialCategory.query.order_by(MaterialCategory.code.asc()).all():
        if cat.code in root_by_code or cat.parent_id:
            continue
        parent_id = mapping.get((cat.code or '')[:1])
        if parent_id and parent_id != cat.id:
            cat.parent_id = parent_id
            changed = True

    if changed:
        db.session.commit()

