def _ai_is_system_api_question(message):
    compact = (message or '').strip().replace(' ', '').lower()
    if not compact:
        return False
    if any(word in compact for word in ('apikey', 'api_key', 'api密钥', 'api-key')):
        return False

    explicit_words = (
        '接口清单', '接口列表', 'api清单', 'api列表', '路由清单', '路由列表',
        '系统接口', '系统api', '当前接口', '当前api', '有哪些接口', '有什么接口',
        '哪些接口', '哪些api', '识别api', '识别接口',
    )
    if any(word in compact for word in explicit_words):
        return True

    api_words = ('api', '接口', '路由', 'endpoint', 'url_map')
    system_words = (
        '当前系统', '本系统', '仓库管理系统', '仓库系统', 'wms', 'c盘', 'c:\\wms',
        '本机', '已注册', '真实', '现有', '所有', '全部', '识别',
    )
    return any(word in compact for word in api_words) and any(word in compact for word in system_words)

def _ai_is_api_route(rule):
    route = (rule.rule or '').lower()
    if rule.endpoint == 'static':
        return False
    return route.startswith('/api/') or '/api/' in route

def _ai_api_route_group(route):
    route = route.lower()
    if route.startswith('/api/ai/'):
        return 'AI助手'
    if route in ('/api/login', '/api/inbound', '/api/outbound', '/api/stocktake'):
        return '原生接口'
    if route.startswith('/mobile/api/'):
        return '移动扫码'
    if route.startswith('/api/material') or route.startswith('/material/api/'):
        return '物料'
    if any(route.startswith(prefix) for prefix in (
        '/api/categories', '/api/units', '/api/suppliers', '/api/customers',
        '/warehouse/api/', '/department/api/',
    )):
        return '基础资料'
    if route.startswith('/api/purchase_order/'):
        return '采购'
    if route.startswith('/api/subcontract/'):
        return '委外'
    if route.startswith('/report/api/') or route.startswith('/api/query/') or route.startswith('/api/document_navigation/'):
        return '查询报表'
    if route.startswith('/api/share_'):
        return '打印分享'
    if route.startswith('/api/field_config/'):
        return '字段配置'
    if route.startswith('/label_template/api/') or route.startswith('/api/barcode/') or route.startswith('/api/qrcode/'):
        return '标签条码'
    if route.startswith('/api/wechat_helper/'):
        return '微信助手'
    return '其他'

def _ai_system_api_catalog():
    routes = []
    for rule in app.url_map.iter_rules():
        if not _ai_is_api_route(rule):
            continue
        methods = sorted(method for method in rule.methods if method not in {'HEAD', 'OPTIONS'})
        if not methods:
            continue
        route = rule.rule
        routes.append({
            'route': route,
            'methods': methods,
            'endpoint': rule.endpoint,
            'module': _ai_api_route_group(route),
        })

    order_index = {name: index for index, name in enumerate(AI_SYSTEM_API_GROUP_ORDER)}
    return sorted(routes, key=lambda item: (order_index.get(item['module'], 999), item['route']))

def _ai_system_api_catalog_response(message):
    if not _ai_is_system_api_question(message):
        return None

    routes = _ai_system_api_catalog()
    group_counts = []
    for group in AI_SYSTEM_API_GROUP_ORDER:
        count = sum(1 for item in routes if item['module'] == group)
        if count:
            group_counts.append(f'{group}{count}个')

    cards = []
    for item in routes:
        methods = ','.join(item['methods'])
        cards.append({
            'title': f'{methods} {item["route"]}',
            'meta': f'{item["module"]}；endpoint：{item["endpoint"]}',
        })

    reply = (
        f'能识别。下面是当前 C:\\wms 仓库管理系统运行时代码里已注册的 Flask API/接口路由，共 {len(routes)} 个。'
        f'按模块统计：{"、".join(group_counts)}。'
        '这些接口来自本机 app.url_map，不是大模型猜出来的。调用时注意：页面内接口通常需要先登录；'
        '原生入库、出库、盘点接口一般要先 POST /api/login 获取令牌；带 <id>、<code>、<path:data> 的路由要替换成真实参数。'
    )
    return _ai_json_response(reply, cards)

