    if not asks_help:
        return None

    general_help = any(word in compact for word in ('不会用', '怎么用', '如何用', '使用系统', '用这个系统', '用这个软件', '管理软件', '教我'))

    stock_shortage_help = _ai_stock_shortage_help_response(message)
