def _ai_page_navigation_response(message, context=None, force=False):
    if not force and not _ai_is_page_navigation_question(message):
        return None

    compact = (message or '').replace(' ', '').lower()
    catalog = _ai_page_navigation_catalog()
    matches = []
    for page in catalog:
        score = 0
        for keyword in page['keywords']:
            key = str(keyword or '').replace(' ', '').lower()
            if not key:
                continue
            if key == compact:
                score += 20
            elif key in compact:
                score += 8 + min(len(key), 8)
        if page['title'].replace(' ', '').lower() in compact:
            score += 12
        if page['module'].replace(' ', '').lower() in compact:
            score += 3
        if score:
            matches.append((score, page))

    matches.sort(key=lambda item: item[0], reverse=True)
    selected = [page for _, page in matches[:8]]
    if not selected:
        selected = [
            page for page in catalog
            if page['title'] in ('首页', '采购订单列表', '物料管理', '操作审计', '报表中心', '系统设置')
        ][:8]

    cards = [
        {
            'title': f'{page["module"]}：{page["title"]}',
            'meta': '点击打开页面；AI只负责导航，不自动提交、审核或修改数据。',
            'url': page['url'],
        }
        for page in selected
    ]
    lines = [
        '**自然语言打开功能**',
        f'- 已匹配到 {len(selected)} 个页面入口。',
        '- 你可以继续说“打开采购订单”“进入操作审计”“去物料管理”“打开系统设置”。',
        '',
        '| 模块 | 页面 |',
        '|---|---|',
    ]
    for page in selected[:6]:
        lines.append(f'| {page["module"]} | {page["title"]} |')
    lines.append('')
    lines.append('AI只做页面导航，不自动保存、审核、反审、删除或修改业务数据。')
    return _ai_json_response(
        '\n'.join(lines),
        cards,
        [{'label': page['title'], 'url': page['url']} for page in selected[:4]],
    )

def _ai_purchase_workbench_response(message, context=None, force=False):
    if not force and not _ai_is_purchase_workbench_question(message):
        return None
    if not _ai_capability_allowed('purchase_insights'):
        return _ai_permission_denied_response('purchase_insights')
    if _ai_is_purchase_followup_agent_question(message):
        task, error = _ai_run_purchase_followup_agent()
        if error:
            return _ai_permission_denied_response('purchase_followup_agent')
        detail_url = url_for('ai_agent_task_detail', id=task.id)
        return _ai_json_response(
            f'采购跟进 Agent 已生成任务 #{task.id}，共记录 {len(task.steps or [])} 个受控步骤。低库存补货只生成草稿建议入口，不会自动提交采购申请、发送催交通知或改动订单状态。',
            [
                {
                    'title': f'采购跟进任务 #{task.id}',
                    'meta': task.summary or '已完成受控跟进',
                    'url': detail_url,
                }
            ],
            [
                {'label': '打开Agent任务', 'url': detail_url},
                {'label': 'AI任务中心', 'url': url_for('ai_agent_task_list')},
                {'label': '采购订单', 'url': url_for('purchase_order_list')},
            ],
        )

    summary = build_purchase_order_todo_summary()
    today_value = date.today()
    overdue_orders = (
        PurchaseOrder.query.options(joinedload(PurchaseOrder.supplier))
        .filter(PurchaseOrder.status.in_(('pending', 'partial')))
        .filter(PurchaseOrder.expected_date.isnot(None))
        .filter(PurchaseOrder.expected_date < today_value)
        .order_by(PurchaseOrder.expected_date.asc(), PurchaseOrder.id.asc())
        .limit(6)
        .all()
    )
    due_soon = (
        PurchaseOrder.query.options(joinedload(PurchaseOrder.supplier))
        .filter(PurchaseOrder.status.in_(('pending', 'partial')))
        .filter(PurchaseOrder.expected_date.isnot(None))
        .filter(PurchaseOrder.expected_date >= today_value)
        .filter(PurchaseOrder.expected_date <= today_value + timedelta(days=3))
        .order_by(PurchaseOrder.expected_date.asc(), PurchaseOrder.id.asc())
        .limit(6)
        .all()
    )
    pending_requests = (
        PurchaseRequest.query
        .filter(PurchaseRequest.status.in_(('pending', 'approved')))
        .order_by(PurchaseRequest.expected_date.asc().nullslast(), PurchaseRequest.created_at.desc(), PurchaseRequest.id.desc())
        .limit(6)
        .all()
    )

    cards = []
    for order in overdue_orders:
        days = (today_value - order.expected_date).days if order.expected_date else 0
        cards.append({
            'title': f'逾期采购 {order.order_no}',
            'meta': f'逾期 {days} 天；供应商 {order.supplier.name if order.supplier else "-"}；状态 {purchase_order_status_label(order.status)}；金额 {round_to_2_decimals(order.total_amount or 0):,.2f}。',
            'url': url_for('purchase_order_detail', id=order.id),
        })
    for order in due_soon:
        cards.append({
            'title': f'即将到货 {order.order_no}',
            'meta': f'预计 {order.expected_date}；供应商 {order.supplier.name if order.supplier else "-"}；状态 {purchase_order_status_label(order.status)}。',
            'url': url_for('purchase_order_detail', id=order.id),
        })
    for request_order in pending_requests:
        cards.append({
            'title': f'待处理请购 {request_order.request_no}',
            'meta': f'状态 {request_order.status}；申请人 {request_order.applicant or "-"}；需求日期 {request_order.expected_date or "-"}。',
            'url': url_for('purchase_request_detail', id=request_order.id),
        })
    replenishment_cards = _ai_purchase_replenishment_cards(limit=6)
    price_risk_cards = _ai_purchase_price_risk_cards(limit=20)
    cards.extend(replenishment_cards)
    cards.extend(price_risk_cards[:5])

    pending_request_count = PurchaseRequest.query.filter(PurchaseRequest.status.in_(('pending', 'approved'))).count()
    low_count = Material.query.filter(_material_low_stock_filter()).count() if inventory_alert_enabled() else 0
    price_risk_count = len(price_risk_cards)
    lines = [
        '**采购工作台**',
        f'- 未完成采购订单：{summary.get("open_count", 0)} 张，未入库数量合计 {normalize_stock_quantity(summary.get("remaining_qty", 0))}。',
        f'- 逾期采购：{summary.get("overdue_count", 0)} 张，优先催交或调整预计到货。',
        f'- 待处理请购：{pending_request_count} 张，建议先处理紧急和低库存关联项。',
        f'- 低库存补货：{low_count} 项，优先转采购申请或采购订单。',
        f'- 采购价异常：{price_risk_count} 项，建议复核供应商报价和历史价。',
        '',
        '建议顺序：1. 逾期采购催交；2. 低库存补货；3. 待处理请购转单；4. 送货单到货识别入库；5. 价格异常复核。'
    ]
    return _ai_json_response(
        '\n'.join(lines),
        cards[:24],
        [
            {'label': '采购订单', 'url': url_for('purchase_order_list')},
            {'label': '采购申请', 'url': url_for('purchase_request_list')},
            {'label': '生成补货申请草稿', 'url': '#', 'prompt': '根据低库存生成采购申请草稿'},
            {'label': '生成催交话术', 'url': '#', 'prompt': '生成催供应商跟进话术'},
            {'label': '新建采购申请', 'url': url_for('purchase_request_add_page')},
            {'label': '送货单入库', 'url': '#', 'prompt': '识别送货单图片并生成采购入库单草稿', 'upload': 'delivery-note'},
        ],
    )

def _ai_is_sales_workbench_question(message):
    compact = (message or '').replace(' ', '').lower()
    if not compact:
        return False
    direct_words = (
        '销售工作台', '销售agent', '销售助手', '销售巡检', '销售待办', '销售风险',
        '销售异常', '销售优先级', '销售建议', '催发货', '发货跟进', '催客户',
        '销售看板', '销售主管看板',
    )
    if any(word in compact for word in direct_words):
        return True
    return '销售' in compact and any(word in compact for word in ('待办', '逾期', '风险', '异常', '建议', '优先', '巡检', '跟进'))

def _ai_is_sales_followup_agent_question(message):
    compact = (message or '').replace(' ', '').lower()
    if not compact:
        return False
    return any(word in compact for word in (
        '销售agent', '销售aiagent', '销售巡检', '销售跟进agent', '发货跟进agent',
        '催客户agent', '销售自动跟进', '自动催发货', '销售任务agent',
    ))

def _ai_sales_workbench_response(message, context=None, force=False):
    """AI-SALES-F02 销售履约跟进工作台响应。

    整合待发货/逾期/部分停滞/缺货/客户催发货/合并发货/客户跟进清单到单一工作台视图。
    验收：指标口径和时间范围明确；对外沟通和业务提交必须人工确认。
    """
    if not force and not _ai_is_sales_workbench_question(message):
        return None
    if not _ai_capability_allowed('sales_insights'):
        return _ai_permission_denied_response('sales_insights')
    if _ai_is_sales_followup_agent_question(message):
        task, error = _ai_run_sales_followup_agent()
        if error:
            return _ai_permission_denied_response('sales_followup_agent')
        detail_url = url_for('ai_agent_task_detail', id=task.id)
        return _ai_json_response(
            f'销售跟进 Agent 已生成任务 #{task.id}，共记录 {len(task.steps or [])} 个受控步骤。催发货话术恒不自动发送，需人工确认后发送；工作台不直接修改订单状态或生成出库草稿。',
            [
                {
                    'title': f'销售跟进任务 #{task.id}',
                    'meta': task.summary or '已完成受控跟进',
                    'url': detail_url,
                }
            ],
            [
                {'label': '打开Agent任务', 'url': detail_url},
                {'label': 'AI任务中心', 'url': url_for('ai_agent_task_list')},
                {'label': '销售订单', 'url': url_for('sales_order_list')},
            ],
        )

    # 汇总销售工作台快照
    try:
        from ai.ops.sales_followup_workbench import (
            build_sales_followup_workbench as _sf_build,
            validate_followup_read_only as _sf_validate_ro,
            validate_metric_scope_clear as _sf_validate_scope,
        )
        snapshot = _sf_build(
            query_pending_shipment=_ai_sf_query_pending_shipment,
            query_overdue_shipment=_ai_sf_query_overdue_shipment,
            query_partial_stalled=_ai_sf_query_partial_stalled,
            query_short_stock=_ai_sf_query_short_stock,
            query_customer_urgency=_ai_sf_query_customer_urgency,
            query_merge_candidates=_ai_sf_query_merge_candidates,
            query_customer_followup_list=_ai_sf_query_customer_followup_list,
            user_id=current_user.id if current_user.is_authenticated else 0,
            role=current_user.role or 'sales',
        )
        ro_valid, _ = _sf_validate_ro(snapshot)
        scope_valid, _ = _sf_validate_scope(snapshot)
        wb = snapshot.to_dict()
    except Exception as exc:  # noqa: BLE001
        app.logger.warning(f'销售工作台构建异常: {exc}')
        return _ai_json_response(
            '销售工作台暂不可用，请稍后重试或联系管理员。',
            None,
            [{'label': '销售订单', 'url': url_for('sales_order_list')}],
        )

    cards = []
    for section in wb.get('sections', []):
        for item in section.get('items', []):
            cards.append({
                'title': f'{section["title"]} · {item["title"]}',
                'meta': f'{item.get("subtitle", "")} | {item.get("detail", "")}',
                'url': item.get('jump_url') or url_for('sales_order_list'),
            })
            if len(cards) >= 20:
                break
        if len(cards) >= 20:
            break

    lines = [
        f'销售履约跟进工作台快照（生成于 {wb.get("generated_at", "-")}）：',
        f'- 需关注总数：{wb.get("total_attention_count", 0)}',
        f'- 待跟进客户数：{len(wb.get("customer_followup_list", []))}',
        f'- 只读校验：{"通过" if ro_valid else "异常"}；指标口径校验：{"通过" if scope_valid else "异常"}',
        '',
        '工作台只读：催发货话术需人工确认后发送，不自动生成出库草稿或修改订单状态。',
    ]
    return _ai_json_response(
        '\n'.join(lines),
        cards[:24],
        [
            {'label': '销售工作台页面', 'url': url_for('ai_sales_workbench_page')},
            {'label': '销售订单', 'url': url_for('sales_order_list')},
            {'label': '生成出库草稿', 'url': '#', 'prompt': '从已确认销售订单生成出库草稿'},
            {'label': '生成催发货话术', 'url': '#', 'prompt': '生成催客户发货话术'},
        ],
    )

