def _ai_run_sales_followup_agent():
    """AI-SALES-F02 销售履约跟进 Agent（4 步受控任务路径）。

    与 purchase_followup_agent 一致：走 AIAgentTask 流程，催发货话术恒不自动发送。
    """
    if not _ai_capability_allowed('sales_followup_agent'):
        return None, 'sales_followup_agent denied'
    task = _ai_create_agent_task('sales_followup', '销售履约跟进：待发货、逾期订单、部分发货停滞、缺货、客户催发货和合单候选。')

    today_value = date.today()
    pending_count = SalesOrder.query.filter(
        SalesOrder.status.in_(('draft', 'confirmed')),
        SalesOrder.shipment_status.in_(('pending', 'partial')),
        SalesOrder.delivery_date.isnot(None),
        SalesOrder.delivery_date >= today_value,
    ).count()
    _ai_add_agent_step(
        task,
        1,
        '待发货销售订单扫描',
        'sales_insights',
        '待发货或部分发货的销售订单',
        f'待发货销售订单：{pending_count} 张。',
        '打开销售订单',
        url_for('sales_order_list'),
    )

    overdue_count = SalesOrder.query.filter(
        SalesOrder.status.in_(('draft', 'confirmed')),
        SalesOrder.shipment_status.in_(('pending', 'partial')),
        SalesOrder.delivery_date.isnot(None),
        SalesOrder.delivery_date < today_value,
    ).count()
    _ai_add_agent_step(
        task,
        2,
        '逾期发货扫描',
        'sales_insights',
        '交货日期早于今天的销售订单',
        f'逾期销售订单：{overdue_count} 张。',
        '打开逾期销售订单',
        url_for('sales_order_list'),
    )

    # 部分发货停滞
    stalled_count = SalesOrder.query.filter(
        SalesOrder.shipment_status == 'partial',
        SalesOrder.status.in_(['draft', 'confirmed']),
    ).count()
    _ai_add_agent_step(
        task,
        3,
        '部分发货停滞扫描',
        'sales_insights',
        '部分发货且停滞超过 7 天的销售订单',
        f'部分发货停滞销售订单：{stalled_count} 张。',
        '打开部分发货停滞订单',
        url_for('sales_order_list'),
    )

    # 客户催发货话术（只读，不自动发送）
    urgency_count = (
        db.session.query(SalesOrder.customer_id)
        .filter(
            SalesOrder.status.in_(('draft', 'confirmed')),
            SalesOrder.shipment_status.in_(('pending', 'partial')),
            SalesOrder.delivery_date < today_value,
        )
        .distinct()
        .count()
    )
    _ai_add_agent_step(
        task,
        4,
        '客户催发货扫描',
        'sales_insights',
        '有逾期订单、需要跟进话术的客户（需人工确认）',
        f'有逾期订单的客户：{urgency_count} 家。催发货话术不会自动发送，需人工确认。',
        '生成客户跟进话术（只读）',
        '#',
        risk_level='read',
    )
    task_summary = (
        f'销售履约跟进完成。待发货 {pending_count} 张，逾期 {overdue_count} 张，'
        f'部分发货停滞 {stalled_count} 张，需跟进客户 {urgency_count} 家。'
    )
    return _ai_finish_agent_task(task, 'completed', task_summary, url_for('sales_order_list')), None

