def _document_nav_value(obj, getter):
    if not getter:
        return ''
    if callable(getter):
        return getter(obj)
    return getattr(obj, getter, '')

def _document_nav_material_terms(item):
    terms = []
    for detail in getattr(item, 'items', []) or []:
        material = getattr(detail, 'material', None)
        if material:
            terms.extend([
                getattr(material, 'code', ''),
                getattr(material, 'name', ''),
                getattr(material, 'spec', ''),
            ])
        terms.extend([
            getattr(detail, 'material_code', ''),
            getattr(detail, 'material_name', ''),
            getattr(detail, 'spec', ''),
        ])
    return terms

