def _apply_header_or_item_contract_filters(query, header_model, item_model, order_fk_name,
                                           contract_no_filter='', project_name_filter=''):
    """表头或任一明细匹配合同编号/工程名称（避免仅明细有值时列表漏查）。"""
    contract_no_filter = (contract_no_filter or '').strip()
    project_name_filter = (project_name_filter or '').strip()
    if not contract_no_filter and not project_name_filter:
        return query
    fk_col = getattr(item_model, order_fk_name)
    if contract_no_filter:
        like = f'%{contract_no_filter}%'
        item_exists = db.session.query(item_model.id).filter(
            fk_col == header_model.id,
            item_model.contract_no.like(like),
        ).correlate(header_model).exists()
        query = query.filter(db.or_(header_model.contract_no.like(like), item_exists))
    if project_name_filter:
        like = f'%{project_name_filter}%'
        item_exists = db.session.query(item_model.id).filter(
            fk_col == header_model.id,
            item_model.project_name.like(like),
        ).correlate(header_model).exists()
        query = query.filter(db.or_(header_model.project_name.like(like), item_exists))
    return query



def _calc_smart_threshold(values, base_threshold=0.5, min_threshold=0.2, max_threshold=1.0):
    """基于历史数据计算智能异常阈值。
    数据稳定（变异系数小）→ 阈值收紧；数据波动大 → 阈值放宽。
    返回 (threshold, mean, std)。
    """
    if not values or len(values) < 2:
        return base_threshold, (sum(values) / len(values) if values else 0), 0
    
    n = len(values)
    mean = sum(values) / n
    if mean <= 0:
        return base_threshold, mean, 0
    
    variance = sum((v - mean) ** 2 for v in values) / (n - 1)
    std = variance ** 0.5
    cv = std / mean  # 变异系数
    
    # 变异系数映射到阈值系数：cv=0 → 0.6倍基础阈值，cv=1 → 1.5倍基础阈值
    scale = 0.6 + cv * 0.9
    scale = max(0.6, min(scale, 2.0))
    threshold = base_threshold * scale
    threshold = max(min_threshold, min(threshold, max_threshold))
    
    return threshold, mean, std

def _check_in_order_anomalies(order):
    """检测入库单异常：数量异常、价格异常、重复单据。返回异常列表。"""
    anomalies = []
    if not order.items:
        return anomalies
    
    today = date.today()
    thirty_days_ago = today - timedelta(days=30)
    
    # 收集所有物料ID
    material_ids = [item.material_id for item in order.items if item.material_id]
    if not material_ids:
        return anomalies
    
    # 一次性查询近30天所有相关物料的入库明细（性能优化）
    recent_items = InOrderItem.query.join(InOrder).filter(
        InOrder.status == 'completed',
        InOrder.date >= thirty_days_ago,
        InOrder.date < today,
        InOrder.id != order.id,
        InOrderItem.material_id.in_(material_ids)
    ).all()
    
    # 按物料ID分组数据
    qty_by_material = {}
    price_by_material = {}
    for ri in recent_items:
        mid = ri.material_id
        if ri.quantity:
            qty_by_material.setdefault(mid, []).append(ri.quantity)
        if ri.price and ri.price > 0:
            price_by_material.setdefault(mid, []).append(ri.price)
    
    for item in order.items:
        if not item.material:
            continue
        
        material_name = item.material.name or item.material.code or '未知物料'
        
        # 1. 数量异常检测：与近30天平均入库量对比（智能阈值）
        recent_quantities = qty_by_material.get(item.material_id, [])
        if recent_quantities:
            qty_threshold, avg_qty, _ = _calc_smart_threshold(recent_quantities, base_threshold=0.5)
            if avg_qty > 0 and item.quantity:
                deviation = abs(item.quantity - avg_qty) / avg_qty
                if deviation > qty_threshold:
                    anomalies.append({
                        'type': 'quantity_deviation',
                        'material': material_name,
                        'current': item.quantity,
                        'average': round(avg_qty, 2),
                        'deviation': f'{deviation*100:.0f}%',
                        'threshold': f'{qty_threshold*100:.0f}%',
                        'msg': f'物料 {material_name} 本次入库量 {item.quantity} 偏离近30天均值 {round(avg_qty, 2)} 达 {deviation*100:.0f}%（动态阈值 {qty_threshold*100:.0f}%），请确认是否正确'
                    })
        
        # 2. 价格异常检测：与近3次采购价对比（智能阈值）
        if item.price and item.price > 0:
            recent_prices = price_by_material.get(item.material_id, [])
            if recent_prices:
                recent_prices_sorted = sorted(recent_prices, reverse=True)[:3]  # 取最近3次
                price_threshold, avg_price, _ = _calc_smart_threshold(recent_prices_sorted, base_threshold=0.3)
                if avg_price > 0:
                    price_deviation = abs(item.price - avg_price) / avg_price
                    if price_deviation > price_threshold:
                        anomalies.append({
                            'type': 'price_deviation',
                            'material': material_name,
                            'current': item.price,
                            'average': round(avg_price, 2),
                            'deviation': f'{price_deviation*100:.0f}%',
                            'threshold': f'{price_threshold*100:.0f}%',
                            'msg': f'物料 {material_name} 本次单价 {item.price} 偏离近期均价 {round(avg_price, 2)} 达 {price_deviation*100:.0f}%（动态阈值 {price_threshold*100:.0f}%），请确认'
                        })
    
    # 3. 重复单据检测：同一天同物料同供应商
    if order.supplier_id and order.date == today:
        today_orders = (
            InOrder.query
            .options(selectinload(InOrder.items))
            .filter(
                InOrder.date == today,
                InOrder.supplier_id == order.supplier_id,
                InOrder.id != order.id
            )
            .all()
        )

        order_material_ids = {oi.material_id for oi in order.items if oi.material_id}
        for to in today_orders:
            for ti in to.items:
                if ti.material_id in order_material_ids:
                    # order.items 的 material 已在外层 selectinload 预加载
                    oi = next((x for x in order.items if x.material_id == ti.material_id), None)
                    material_name = (oi.material.name if oi and oi.material else None) or (oi.material.code if oi and oi.material else '') or str(ti.material_id)
                    anomalies.append({
                        'type': 'duplicate_order',
                        'material': material_name,
                        'existing_order': to.order_no,
                        'msg': f'物料 {material_name} 今天已在单据 {to.order_no} 中入库，请确认是否为重复操作'
                    })
    
    return anomalies


def _acquire_order_write_lock(model_cls, record_id, expected_status, eager_load=None):
    """获取单据写锁并重新读取状态，避免多 worker 并发重复处理同一张单据。

    SQLite 用 BEGIN IMMEDIATE 串行化写事务；其它数据库用 SELECT ... FOR UPDATE 行锁。
    必须在已通过外层 status 检查后调用，本函数再次确认 status 未被并发请求修改。

    expected_status 可为单个字符串或字符串序列（如 ('pending', 'completed')），
    用于允许在多种状态间执行（例如 delete_in_order）。

    eager_load 可为单个 LoaderOption 或 LoaderOption 列表，用于预加载关联
    （如 selectinload(InOrder.items).selectinload(InOrderItem.material)），
    消除循环内 N+1 查询。

    返回 (order, ok)：
    - ok=True：调用方继续在已加锁的事务中执行库存操作。
    - ok=False：单据已被删除、状态已被修改或锁获取失败；session 已 rollback，调用方应直接返回错误。
    """
    if isinstance(expected_status, (list, tuple, set)):
        expected_set = set(expected_status)
    else:
        expected_set = {expected_status}
    # 统一 eager_load 为列表，支持单个选项或列表
    if eager_load is None:
        eager_loads = []
    elif isinstance(eager_load, (list, tuple)):
        eager_loads = list(eager_load)
    else:
        eager_loads = [eager_load]
    try:
        if db.engine.dialect.name == 'sqlite':
            db.session.rollback()
            db.session.connection().exec_driver_sql('BEGIN IMMEDIATE')
            order = db.session.get(model_cls, record_id, options=eager_loads) if eager_loads else db.session.get(model_cls, record_id)
        else:
            query = model_cls.query.with_for_update()
            if eager_loads:
                query = query.options(*eager_loads)
            order = query.get(record_id)
        if not order:
            db.session.rollback()
            return None, False
        if order.status not in expected_set:
            db.session.rollback()
            return order, False
        return order, True
    except Exception:
        db.session.rollback()
        return None, False



@app.route('/api/material/all', methods=['GET', 'POST'])
@web_or_api_required
def material_all_api():
    materials = Material.query.order_by(Material.code.asc()).limit(1000).all()
    return jsonify({
        'status': 'success',
        'success': True,
        'data': [api_material_payload(material) for material in materials]
    })

@app.route('/api/material/search', methods=['GET', 'POST'])
@web_or_api_required
def material_search_api():
    # Native scanners use different query names across released APK builds.
    # Keep the canonical `kw`/`keyword` names and accept the common aliases.
    keyword = (
        request.values.get('kw')
        or request.values.get('keyword')
        or request.values.get('q')
        or request.values.get('code')
        or ''
    ).strip()
    query = Material.query
    if keyword:
        query = query.filter(
            db.or_(
                Material.code.like(f'%{keyword}%'),
                Material.name.like(f'%{keyword}%'),
                Material.spec.like(f'%{keyword}%'),
                Material.brand.like(f'%{keyword}%')
            )
        )
    materials = query.order_by(Material.code.asc()).limit(100).all()
    return jsonify({
        'status': 'success',
        'success': True,
        'data': [api_material_payload(material) for material in materials]
    })

@app.route('/api/material/info', methods=['GET', 'POST'])
@web_or_api_required
def material_info_api():
    code = (request.values.get('code') or '').strip()
    material_id = request.values.get('id', type=int)

    material = None
    if code:
        material = Material.query.filter_by(code=code).first()
    elif material_id:
        material = db.session.get(Material, material_id)

    if not material:
        return api_error('物料不存在')

    return jsonify({
        'status': 'success',
        'success': True,
        'data': api_material_payload(material)
    })

