def get_user_field_config(user_id, page_type):
    """获取用户的字段配置，如果没有则返回默认配置"""
    configs = UserFieldConfig.query.filter_by(user_id=user_id, page_type=page_type).all()
    if configs:
        result = []
        for cfg in configs:
            result.append({
                'key': cfg.field_key,
                'label': cfg.field_label,
                'width': cfg.width,
                'visible': cfg.visible,
                'sort': cfg.sort_order,
            })
        return sorted(result, key=lambda x: x['sort'])
    
    # 返回默认配置
    defaults = DEFAULT_FIELD_CONFIGS.get(page_type, [])
    return [dict(d) for d in defaults]

def save_user_field_config(user_id, page_type, configs):
    """保存用户的字段配置"""
    # 删除旧配置
    UserFieldConfig.query.filter_by(user_id=user_id, page_type=page_type).delete()
    
    # 添加新配置
    for cfg in configs:
        field_cfg = UserFieldConfig(
            user_id=user_id,
            page_type=page_type,
            field_key=cfg['key'],
            field_label=cfg.get('label', ''),
            width=cfg.get('width', 0),
            visible=cfg.get('visible', True),
            sort_order=cfg.get('sort', 0),
        )
        db.session.add(field_cfg)
    
    try:
        db.session.commit()
    except Exception as e:
        db.session.rollback()
        app.logger.error(f"数据库操作失败: {e}")
        raise
    return True

@app.route('/api/field_config/<page_type>', methods=['GET'])
@login_required
def get_field_config_api(page_type):
    """获取字段配置API"""
    configs = get_user_field_config(current_user.id, page_type)
    return jsonify({'status': 'success', 'data': configs})

@app.route('/api/field_config/<page_type>', methods=['POST'])
@require_role('warehouse')
@login_required
def save_field_config_api(page_type):
    """保存字段配置API"""
    data = request.get_json(silent=True)
    if not data or not isinstance(data, list):
        return api_error('配置数据格式不正确')
    
    try:
        save_user_field_config(current_user.id, page_type, data)
        return jsonify({'status': 'success', 'msg': '配置已保存'})
    except Exception as e:
        db.session.rollback()
        return api_error('保存失败，请稍后重试')







