def calculate_bom_cost_value(bom, refresh_unit_cost=True):
    total_cost = 0
    for item in bom.items:
        if refresh_unit_cost:
            item.unit_cost = (item.material.price if item.material else 0) or 0
        else:
            item.unit_cost = item.unit_cost or 0
        item.total_cost = round_to_2_decimals((item.quantity or 0) * item.unit_cost)
        total_cost += item.total_cost
    bom.total_cost = round_to_2_decimals(total_cost)
    return bom.total_cost

def _clean_int(value):
    if value in (None, '', 'None', 'null'):
        return None
    try:
        return int(value)
    except (TypeError, ValueError):
        return None

def _parse_form_date(value, default=None):
    value = (value or '').strip()
    if not value:
        return default or date.today()
    return datetime.strptime(value, '%Y-%m-%d').date()

def _parse_excel_date(value, default=None):
    """Parse dates from Excel cells or strings."""
    if value in (None, ''):
        return default or date.today()
    if isinstance(value, datetime):
        return value.date()
    if isinstance(value, date):
        return value
    text = str(value).strip()
    if not text:
        return default or date.today()
    for fmt in ('%Y-%m-%d', '%Y/%m/%d', '%Y-%m-%d %H:%M:%S', '%Y/%m/%d %H:%M:%S'):
        try:
            return datetime.strptime(text, fmt).date()
        except ValueError:
            continue
    return default or date.today()

def _get_excel_cell(row, col_map, key, default=''):
    idx = col_map.get(key)
    if idx is None or idx >= len(row) or row[idx] is None:
        return default
    value = row[idx]
    if isinstance(value, datetime):
        return value.strftime('%Y-%m-%d')
    if isinstance(value, date):
        return value.strftime('%Y-%m-%d')
    return str(value).strip()

def _get_excel_number(row, col_map, key, default=0):
    idx = col_map.get(key)
    if idx is None or idx >= len(row) or row[idx] in (None, ''):
        return default
    return round_to_2_decimals(parse_float_value(row[idx], default))

def _find_or_create_unit(name):
    name = (name or '').strip()
    if not name:
        return None
    unit = Unit.query.filter_by(name=name).first() or Unit.query.filter_by(code=name).first()
    if not unit:
        unit = Unit(code=name, name=name)
        db.session.add(unit)
        db.session.flush()
    return unit

def _find_or_create_supplier(name):
    name = (name or '').strip()
    if not name:
        return None
    supplier = Supplier.query.filter_by(name=name).first() or Supplier.query.filter_by(code=name).first()
    if not supplier:
        supplier = Supplier(code=name, name=name)
        db.session.add(supplier)
        db.session.flush()
    return supplier

def _find_or_create_customer(name, contact='', phone=''):
    name = (name or '').strip()
    if not name:
        return None
    customer = Customer.query.filter_by(name=name).first() or Customer.query.filter_by(code=name).first()
    if not customer:
        code_base = name if len(name) <= 50 else f'CUS-{Customer.query.count() + 1:03d}'
        code = code_base
        if Customer.query.filter_by(code=code).first():
            code = f'CUS-{Customer.query.count() + 1:03d}'
        customer = Customer(code=code, name=name, contact=contact or '', phone=phone or '')
        db.session.add(customer)
        db.session.flush()
    else:
        if contact and not customer.contact:
            customer.contact = contact
        if phone and not customer.phone:
            customer.phone = phone
    return customer

def _find_or_create_warehouse(name):
    name = (name or '').strip()
    if not name:
        return None
    warehouse = Warehouse.query.filter_by(name=name).first() or Warehouse.query.filter_by(code=name).first()
    if not warehouse:
        seq = Warehouse.query.count() + 1
        code = f'WH{seq:03d}'
        while Warehouse.query.filter_by(code=code).first():
            seq += 1
            code = f'WH{seq:03d}'
        warehouse = Warehouse(code=code, name=name, status='active')
        db.session.add(warehouse)
        db.session.flush()
    return warehouse

def _find_or_create_material(code, name='', spec='', unit_name=''):
    code = (code or '').strip()
    if not code:
        return None
    material = Material.query.filter_by(code=code).first()
    unit = _find_or_create_unit(unit_name)
    if not material:
        material = Material(
            code=code,
            name=(name or '').strip() or code,
            spec=(spec or '').strip(),
            unit_id=unit.id if unit else None,
            stock=0,
            min_stock=0,
            price=0
        )
        db.session.add(material)
        db.session.flush()
    else:
        if name and not material.name:
            material.name = name
        if spec and not material.spec:
            material.spec = spec
        if unit and not material.unit_id:
            material.unit_id = unit.id
    return material

def _build_col_map(header_row, aliases):
    col_map = {}
    for idx, header in enumerate(header_row):
        label = str(header or '').strip().lower()
        if not label:
            continue
        for key, patterns in aliases.items():
            if key in col_map:
                continue
            if any(str(pattern).lower() in label for pattern in patterns):
                col_map[key] = idx
    return col_map

def _workbook_response(filename, sheet_title, columns, rows=None):
    from openpyxl import Workbook
    wb = Workbook()
    ws = wb.active
    ws.title = sheet_title
    ws.append(columns)
    for row in rows or []:
        ws.append(row)
    output = io.BytesIO()
    wb.save(output)
    output.seek(0)
    return send_file(output, download_name=filename, as_attachment=True)

def _read_import_sheet(file, aliases):
    # 底层防御：即使调用方漏校验，也阻止非 Excel 文件进入 openpyxl 解析
    _ext_ok, _ext_msg = validate_excel_extension(getattr(file, 'filename', '') or '')
    if not _ext_ok:
        raise ValueError(_ext_msg)
    # m-03：底层兜底，限制 Excel 上传 ≤ 5MB
    _size_ok, _size_msg = validate_excel_size(file)
    if not _size_ok:
        raise ValueError(_size_msg)
    from openpyxl import load_workbook
    wb = load_workbook(file)
    ws = wb.active
    header = next(ws.iter_rows(min_row=1, max_row=1, values_only=True), None) or []
    header_row = [str(cell).strip() if cell else '' for cell in header]
    return ws, _build_col_map(header_row, aliases), header_row

def _import_result(name, order_count, item_count=0, skip=0, skip_details=None, extra=None):
    msg = f'{name}导入成功，共导入 {order_count} 张单据'
    if item_count:
        msg += f'，{item_count} 条明细'
    if skip:
        msg += f'，跳过 {skip} 行'
    payload = {'status': 'success', 'msg': msg, 'count': order_count, 'item_count': item_count}
    if skip_details:
        payload['warnings'] = '；'.join(skip_details[:20])
    if extra:
        payload.update(extra)
    return jsonify(payload)

def _order_no_from_row(row, col_map, key, prefix):
    return _get_excel_cell(row, col_map, key) or generate_order_no(prefix)

def _material_from_payload(item_data):
    material_id = _clean_int(item_data.get('material_id'))
    if material_id:
        material = db.session.get(Material, material_id)
        if material:
            return material
    material_code = (item_data.get('code') or item_data.get('material_code') or '').strip()
    if material_code:
        return Material.query.filter_by(code=material_code).first()
    return None

def _material_line_data(item, quantity=None, extra=None):
    material = item.material
    unit = getattr(item, 'unit', None) or (material.unit if material and material.unit else None)
    data = {
        'id': item.id,
        'material_id': item.material_id,
        'code': material.code if material else '',
        'name': material.name if material else '',
        'spec': material.spec if material else '',
        'unit_id': unit.id if unit else '',
        'unit': unit.name if unit else '',
        'stock': float(material.stock or 0) if material else 0,
        'quantity': float(quantity if quantity is not None else (getattr(item, 'quantity', 0) or 0)),
        'price': float(getattr(item, 'price', 0) or (material.price if material else 0) or 0),
        'amount': float(getattr(item, 'amount', 0) or 0),
        'remark': getattr(item, 'remark', '') or '',
    }
    if extra:
        data.update(extra)
    return data

def _fmt_date(value):
    if isinstance(value, datetime):
        return value.strftime('%Y-%m-%d %H:%M')
    if isinstance(value, date):
        return value.strftime('%Y-%m-%d')
    return value or ''

def _operator_name(obj):
    operator = getattr(obj, 'operator', None)
    return operator.username if operator else ''

def _material_unit_name(item):
    material = getattr(item, 'material', None)
    unit = getattr(item, 'unit', None) or (material.unit if material and material.unit else None)
    return unit.name if unit else ''

def _material_row_common(item, quantity=None, price=None, amount=None, remark=None, extra=None):
    material = getattr(item, 'material', None)
    row = {
        'code': material.code if material else getattr(item, 'material_code', '') or '',
        'name': material.name if material else getattr(item, 'material_name', '') or '',
        'spec': material.spec if material else getattr(item, 'spec', '') or '',
        'unit': _material_unit_name(item),
        'quantity': quantity if quantity is not None else getattr(item, 'quantity', 0) or 0,
        'price': price if price is not None else getattr(item, 'price', 0) or 0,
        'amount': amount if amount is not None else getattr(item, 'amount', 0) or 0,
        'remark': remark if remark is not None else getattr(item, 'remark', '') or '',
    }
    if extra:
        row.update(extra)
    return row

def _print_status_label(status):
    labels = {
        'pending': '草稿',
        'approved': '已审批',
        'rejected': '已驳回',
        'partial': '部分完成',
        'processing': '加工中',
        'completed': '已完成',
        'closed': '已关闭',
        'cancelled': '已取消',
        'active': '启用',
        'inactive': '停用',
    }
    return labels.get(status, status or '')

def _render_generic_document_print(payload):
    payload.setdefault('print_time', datetime.now())
    payload.setdefault('status_label', _print_status_label(payload.get('status')))
    payload.setdefault('total_quantity', sum(row.get('quantity', 0) or 0 for row in payload.get('rows', [])))
    payload.setdefault('total_amount', sum(row.get('amount', 0) or 0 for row in payload.get('rows', [])))
    return render_template('document_print.html', doc=payload)

