def _create_adjustment_drafts_from_check(check):
    """Create pending adjustment draft(s) from inventory check differences."""
    existing = AdjustmentOrder.query.filter_by(source_type='check', source_id=check.id).all()
    if existing:
        return None, '该盘点单已生成库存调整单，请勿重复生成'

    grouped = {'surplus': [], 'loss': []}
    for item in check.items:
        if not item.material_id:
            continue
        system_stock = normalize_stock_quantity(item.system_stock or 0)
        actual_stock = normalize_stock_quantity(item.actual_stock or 0)
        diff = normalize_stock_quantity(actual_stock - system_stock)
        if abs(diff) <= STOCK_COMPARE_EPSILON:
            continue
        direction = 'surplus' if diff > 0 else 'loss'
        grouped[direction].append((item, abs(diff), system_stock, actual_stock))

    drafts = []
    for adjustment_type, rows in grouped.items():
        if not rows:
            continue
        order = AdjustmentOrder(
            adjustment_no=generate_order_no('ADJ'),
            date=date.today(),
            adjustment_type=adjustment_type,
            source_type='check',
            source_id=check.id,
            status='pending',
            operator_id=current_user.id if current_user.is_authenticated else None,
            # BUG-2026-08-02-013：盘点生成的调整草稿带上盘点仓库，保证 complete_adjustment 能按仓库同步库位库存
            warehouse=getattr(check, 'warehouse', None),
            remark=f'由盘点单 {check.check_no} 自动生成，请审核后提交'
        )
        db.session.add(order)
        db.session.flush()
        for item, qty, system_stock, actual_stock in rows:
            signed_qty = qty if adjustment_type == 'surplus' else -qty
            db.session.add(AdjustmentOrderItem(
                adjustment_order_id=order.id,
                material_id=item.material_id,
                quantity=signed_qty,
                unit_id=item.material.unit_id if item.material else None,
                reason=item.reason or f'盘点差异：账面 {system_stock}，实盘 {actual_stock}'
            ))
        drafts.append(order)
    return drafts, None

def _create_adjustment_drafts_from_check_scan(check):
    """Create pending adjustment draft(s) from mobile/native stocktake differences."""
    existing = AdjustmentOrder.query.filter_by(source_type='check_scan', source_id=check.id).all()
    if existing:
        return None, '该扫码盘点单已生成库存调整单，请勿重复生成'

    grouped = {'surplus': [], 'loss': []}
    for item in check.items:
        if not item.material_id:
            continue
        system_stock = normalize_stock_quantity(item.system_stock or 0)
        actual_stock = normalize_stock_quantity(item.actual_stock or 0)
        diff = normalize_stock_quantity(actual_stock - system_stock)
        if abs(diff) <= STOCK_COMPARE_EPSILON:
            continue
        direction = 'surplus' if diff > 0 else 'loss'
        grouped[direction].append((item, abs(diff), system_stock, actual_stock))

    drafts = []
    for adjustment_type, rows in grouped.items():
        if not rows:
            continue
        order = AdjustmentOrder(
            adjustment_no=generate_order_no('ADJ'),
            date=date.today(),
            adjustment_type=adjustment_type,
            source_type='check_scan',
            source_id=check.id,
            status='pending',
            operator_id=getattr(check, 'operator_id', None) or (current_user.id if current_user.is_authenticated else None),
            # BUG-2026-08-02-013：扫码盘点生成的调整草稿带上盘点仓库
            warehouse=getattr(check, 'warehouse', None),
            remark=f'由扫码盘点单 {check.check_no} 自动生成，请审核后提交'
        )
        db.session.add(order)
        db.session.flush()
        for item, qty, system_stock, actual_stock in rows:
            signed_qty = qty if adjustment_type == 'surplus' else -qty
            db.session.add(AdjustmentOrderItem(
                adjustment_order_id=order.id,
                material_id=item.material_id,
                quantity=signed_qty,
                unit_id=item.material.unit_id if item.material else None,
                reason=f'扫码盘点差异：账面 {system_stock}，实盘 {actual_stock}'
            ))
        drafts.append(order)
    return drafts, None














# ==================== Outbound order management ====================








def _check_out_order_anomalies(order):
    """检测出库单异常：数量异常、金额异常、重复单据。返回异常列表。"""
    anomalies = []
    if not order.items:
        return anomalies
    
    today = date.today()
    thirty_days_ago = today - timedelta(days=30)
    
    # 收集所有物料ID
    material_ids = [item.material_id for item in order.items if item.material_id]
    if not material_ids:
        return anomalies
    
    # 一次性查询近30天所有相关物料的出库明细（性能优化）
    recent_items = OutOrderItem.query.join(OutOrder).filter(
        OutOrder.status == 'completed',
        OutOrder.date >= thirty_days_ago,
        OutOrder.date < today,
        OutOrder.id != order.id,
        OutOrderItem.material_id.in_(material_ids)
    ).all()
    
    # 按物料ID分组数据
    qty_by_material = {}
    price_by_material = {}
    for ri in recent_items:
        mid = ri.material_id
        if ri.quantity:
            qty_by_material.setdefault(mid, []).append(ri.quantity)
        if ri.price and ri.price > 0:
            price_by_material.setdefault(mid, []).append(ri.price)
    
    for item in order.items:
        if not item.material:
            continue
        
        material_name = item.material.name or item.material.code or '未知物料'
        
        # 1. 数量异常检测：与近30天平均出库量对比（智能阈值）
        recent_quantities = qty_by_material.get(item.material_id, [])
        if recent_quantities:
            qty_threshold, avg_qty, _ = _calc_smart_threshold(recent_quantities, base_threshold=0.5)
            if avg_qty > 0 and item.quantity:
                deviation = abs(item.quantity - avg_qty) / avg_qty
                if deviation > qty_threshold:
                    anomalies.append({
                        'type': 'quantity_deviation',
                        'material': material_name,
                        'current': item.quantity,
                        'average': round(avg_qty, 2),
                        'deviation': f'{deviation*100:.0f}%',
                        'threshold': f'{qty_threshold*100:.0f}%',
                        'msg': f'物料 {material_name} 本次出库量 {item.quantity} 偏离近30天均值 {round(avg_qty, 2)} 达 {deviation*100:.0f}%（动态阈值 {qty_threshold*100:.0f}%），请确认是否正确'
                    })
        
        # 2. 金额异常检测：与近3次出库单价对比（智能阈值）
        if item.price and item.price > 0:
            recent_prices = price_by_material.get(item.material_id, [])
            if recent_prices:
                recent_prices_sorted = sorted(recent_prices, reverse=True)[:3]  # 取最近3次
                price_threshold, avg_price, _ = _calc_smart_threshold(recent_prices_sorted, base_threshold=0.3)
                if avg_price > 0:
                    price_deviation = abs(item.price - avg_price) / avg_price
                    if price_deviation > price_threshold:
                        anomalies.append({
                            'type': 'price_deviation',
                            'material': material_name,
                            'current': item.price,
                            'average': round(avg_price, 2),
                            'deviation': f'{price_deviation*100:.0f}%',
                            'threshold': f'{price_threshold*100:.0f}%',
                            'msg': f'物料 {material_name} 本次单价 {item.price} 偏离近期均价 {round(avg_price, 2)} 达 {price_deviation*100:.0f}%（动态阈值 {price_threshold*100:.0f}%），请确认'
                        })
    
    # 3. 重复单据检测：同一天同物料同客户/部门
    if order.date == today:
        today_orders = OutOrder.query.filter(
            OutOrder.date == today,
            OutOrder.id != order.id
        )
        # 按客户或部门过滤（OutOrder 使用 customer 字符串字段，非 customer_id 外键）
        customer_name = getattr(order, 'customer', None)
        if customer_name:
            today_orders = today_orders.filter(OutOrder.customer == customer_name)
        elif order.department_id:
            today_orders = today_orders.filter(OutOrder.department_id == order.department_id)
        else:
            today_orders = None  # 无客户/部门信息时不检测重复
        
        if today_orders:
            today_orders = today_orders.all()
            for to in today_orders:
                for ti in to.items:
                    for oi in order.items:
                        if ti.material_id == oi.material_id:
                            material_name = oi.material.name or oi.material.code
                            anomalies.append({
                                'type': 'duplicate_order',
                                'material': material_name,
                                'existing_order': to.order_no,
                                'msg': f'物料 {material_name} 今天已在单据 {to.order_no} 中出库，请确认是否为重复操作'
                            })
    
    return anomalies





@app.route('/api/ai/out_order/<int:id>/anomaly_analysis')
@login_required
def api_ai_out_order_anomaly_analysis(id):
    """出库单异常AI分析接口"""
    result = _ai_analyze_out_order_anomalies(id)
    if not result.get('order'):
        return jsonify({'status': 'error', 'msg': result.get('summary', '未找到该出库单')}), 404
    return jsonify({'status': 'success', 'data': result})






