def _get_report_definition(report_type):
    return REPORT_DEFINITIONS.get(report_type)

def _shift_month_start(month_start, offset):
    month_index = month_start.month - 1 + offset
    year = month_start.year + month_index // 12
    month = month_index % 12 + 1
    return date(year, month, 1)

def build_report_dashboard_context(warehouse):
    """构建指定仓库的数据仪表盘统计与图表数据。"""
    warehouse_name = (warehouse.name or '').strip()
    warehouse_code = (warehouse.code or '').strip()
    warehouse_stock_map = get_warehouse_stock_quantities(warehouse)
    stocked_material_ids = [
        material_id for material_id, quantity in warehouse_stock_map.items()
        if _safe_float(quantity) > 0
    ]
    today = date.today()
    month_start = today.replace(day=1)
    next_month_start = _shift_month_start(month_start, 1)
    last_month_start = _shift_month_start(month_start, -1)

    month_in_amount = db.session.query(func.coalesce(func.sum(InOrder.total_amount), 0)).filter(
        InOrder.date >= month_start,
        InOrder.date < next_month_start,
        db.or_(InOrder.warehouse == warehouse_name, InOrder.warehouse == warehouse_code),
    ).scalar() or 0
    month_out_amount = db.session.query(func.coalesce(func.sum(OutOrder.total_amount), 0)).filter(
        OutOrder.date >= month_start,
        OutOrder.date < next_month_start,
        db.or_(OutOrder.warehouse == warehouse_name, OutOrder.warehouse == warehouse_code),
    ).scalar() or 0
    month_in_count = db.session.query(func.count(InOrder.id)).filter(
        InOrder.date >= month_start,
        InOrder.date < next_month_start,
        db.or_(InOrder.warehouse == warehouse_name, InOrder.warehouse == warehouse_code),
    ).scalar() or 0
    month_out_count = db.session.query(func.count(OutOrder.id)).filter(
        OutOrder.date >= month_start,
        OutOrder.date < next_month_start,
        db.or_(OutOrder.warehouse == warehouse_name, OutOrder.warehouse == warehouse_code),
    ).scalar() or 0
    
    # 上月数据用于环比分析
    last_month_start = _shift_month_start(month_start, -1)
    last_month_in_amount = db.session.query(func.coalesce(func.sum(InOrder.total_amount), 0)).filter(
        InOrder.date >= last_month_start,
        InOrder.date < month_start,
        db.or_(InOrder.warehouse == warehouse_name, InOrder.warehouse == warehouse_code),
    ).scalar() or 0
    last_month_out_amount = db.session.query(func.coalesce(func.sum(OutOrder.total_amount), 0)).filter(
        OutOrder.date >= last_month_start,
        OutOrder.date < month_start,
        db.or_(OutOrder.warehouse == warehouse_name, OutOrder.warehouse == warehouse_code),
    ).scalar() or 0
    last_month_in_count = db.session.query(func.count(InOrder.id)).filter(
        InOrder.date >= last_month_start,
        InOrder.date < month_start,
        db.or_(InOrder.warehouse == warehouse_name, InOrder.warehouse == warehouse_code),
    ).scalar() or 0
    last_month_out_count = db.session.query(func.count(OutOrder.id)).filter(
        OutOrder.date >= last_month_start,
        OutOrder.date < month_start,
        db.or_(OutOrder.warehouse == warehouse_name, OutOrder.warehouse == warehouse_code),
    ).scalar() or 0

    # 计算环比增长率
    def _calc_mom_rate(current, last):
        if last and last > 0:
            return ((current - last) / last) * 100
        return None

    in_amount_mom = _calc_mom_rate(float(month_in_amount), float(last_month_in_amount))
    out_amount_mom = _calc_mom_rate(float(month_out_amount), float(last_month_out_amount))
    in_count_mom = _calc_mom_rate(int(month_in_count), int(last_month_in_count))
    out_count_mom = _calc_mom_rate(int(month_out_count), int(last_month_out_count))

    material_rows = Material.query.filter(Material.id.in_(stocked_material_ids)).all() if stocked_material_ids else []
    total_stock = sum(_safe_float(warehouse_stock_map.get(material.id)) for material in material_rows)
    material_count = len(material_rows)
    stock_value = sum(
        _safe_float(warehouse_stock_map.get(material.id)) * _safe_float(material.price)
        for material in material_rows
    )

    stats = {
        'month_in_amount': float(month_in_amount),
        'month_out_amount': float(month_out_amount),
        'month_in_count': int(month_in_count),
        'month_out_count': int(month_out_count),
        'total_stock': float(total_stock),
        'material_count': int(material_count),
        'stock_value': float(stock_value),
        'last_month_in_amount': float(last_month_in_amount),
        'last_month_out_amount': float(last_month_out_amount),
        'last_month_in_count': int(last_month_in_count),
        'last_month_out_count': int(last_month_out_count),
        'in_amount_mom': in_amount_mom,
        'out_amount_mom': out_amount_mom,
        'in_count_mom': in_count_mom,
        'out_count_mom': out_count_mom,
    }

    trend_start = today - timedelta(days=9)
    in_trend_rows = db.session.query(
        InOrder.date,
        func.coalesce(func.sum(InOrderItem.quantity), 0)
    ).join(InOrderItem, InOrderItem.in_order_id == InOrder.id).filter(
        InOrder.date >= trend_start,
        InOrder.date <= today,
        InOrder.warehouse == warehouse_name,
    ).group_by(InOrder.date).all()
    out_trend_rows = db.session.query(
        OutOrder.date,
        func.coalesce(func.sum(OutOrderItem.quantity), 0)
    ).join(OutOrderItem, OutOrderItem.out_order_id == OutOrder.id).filter(
        OutOrder.date >= trend_start,
        OutOrder.date <= today,
        OutOrder.warehouse == warehouse_name,
    ).group_by(OutOrder.date).all()
    in_trend_map = {row[0]: float(row[1] or 0) for row in in_trend_rows}
    out_trend_map = {row[0]: float(row[1] or 0) for row in out_trend_rows}

    trend_labels = []
    trend_in_qty = []
    trend_out_qty = []
    for offset in range(10):
        current_day = trend_start + timedelta(days=offset)
        trend_labels.append(current_day.strftime('%m-%d'))
        trend_in_qty.append(in_trend_map.get(current_day, 0))
        trend_out_qty.append(out_trend_map.get(current_day, 0))

    category_rows = db.session.query(
        MaterialCategory.name,
        func.count(Material.id)
    ).join(Material, Material.category_id == MaterialCategory.id).filter(
        Material.id.in_(stocked_material_ids)
    ).group_by(
        MaterialCategory.id,
        MaterialCategory.name
    ).all()
    uncategorized_count = sum(1 for material in material_rows if material.category_id is None)
    category_labels = []
    category_values = []
    for name, count in category_rows:
        category_labels.append(name or 'Unnamed')
        category_values.append(int(count or 0))
    if uncategorized_count:
        category_labels.append('Uncategorized')
        category_values.append(int(uncategorized_count))

    top_stock_rows = sorted(
        material_rows,
        key=lambda material: (_safe_float(warehouse_stock_map.get(material.id)), material.id),
        reverse=True,
    )[:10]
    top_stock_labels = [m.code or m.name or f'Material-{m.id}' for m in top_stock_rows]
    top_stock_values = [_safe_float(warehouse_stock_map.get(m.id)) for m in top_stock_rows]

    monthly_start = _shift_month_start(month_start, -5)
    in_amount_rows = db.session.query(InOrder.date, InOrder.total_amount).filter(
        InOrder.date >= monthly_start,
        InOrder.date < next_month_start,
        InOrder.warehouse == warehouse_name,
    ).all()
    out_amount_rows = db.session.query(OutOrder.date, OutOrder.total_amount).filter(
        OutOrder.date >= monthly_start,
        OutOrder.date < next_month_start,
        OutOrder.warehouse == warehouse_name,
    ).all()
    in_amount_map = {}
    out_amount_map = {}
    for row_date, amount in in_amount_rows:
        key = row_date.strftime('%Y-%m')
        in_amount_map[key] = in_amount_map.get(key, 0) + float(amount or 0)
    for row_date, amount in out_amount_rows:
        key = row_date.strftime('%Y-%m')
        out_amount_map[key] = out_amount_map.get(key, 0) + float(amount or 0)

    monthly_labels = []
    monthly_in_amount = []
    monthly_out_amount = []
    for offset in range(6):
        current_month = _shift_month_start(monthly_start, offset)
        key = current_month.strftime('%Y-%m')
        monthly_labels.append(key)
        monthly_in_amount.append(in_amount_map.get(key, 0))
        monthly_out_amount.append(out_amount_map.get(key, 0))

    chart_data = {
        'trend': {
            'labels': trend_labels,
            'in_qty': trend_in_qty,
            'out_qty': trend_out_qty,
        },
        'category': {
            'labels': category_labels,
            'values': category_values,
        },
        'top_stock': {
            'labels': top_stock_labels,
            'values': top_stock_values,
        },
        'monthly_amount': {
            'labels': monthly_labels,
            'in_amount': monthly_in_amount,
            'out_amount': monthly_out_amount,
        },
    }
    return stats, chart_data

def _safe_float(value):
    try:
        return float(value or 0)
    except (TypeError, ValueError):
        return 0.0

def _parse_date_arg(name):
    value = (request.args.get(name) or '').strip()
    if not value:
        return None
    try:
        return datetime.strptime(value, '%Y-%m-%d').date()
    except ValueError as exc:
        raise ValueError(f'{name} format is invalid') from exc

def _parse_positive_int(value, default):
    try:
        parsed = int(value)
    except (TypeError, ValueError):
        return default
    return parsed if parsed > 0 else default

def _build_report_filters():
    # BUG-2026-08-02-014：报表仓库必填筛选，未指定时带入默认仓库
    warehouse_id = _parse_positive_int(request.args.get('warehouse_id'), 0)
    warehouse_name = ''
    warehouse_code = ''
    if not warehouse_id:
        default_wh = get_default_warehouse()
        if default_wh:
            warehouse_id = default_wh.id
            warehouse_name = default_wh.name
            warehouse_code = default_wh.code or ''
    else:
        wh = Warehouse.query.get(warehouse_id)
        if wh:
            warehouse_name = wh.name
            warehouse_code = wh.code or ''
    raw_business_type = (request.args.get('business_type') or '').strip()
    # BUG-2026-08-18-004：入库明细报表此前硬编码只查"采购入库"，
    # 手机端"产品入库"、网页端"其他入库"永远查不出来。改为可选筛选，
    # 空值表示全部入库类型。
    if raw_business_type not in ('采购入库', '产品入库', '其他入库'):
        raw_business_type = ''
    return {
        'start_date': _parse_date_arg('start_date'),
        'end_date': _parse_date_arg('end_date'),
        'warehouse_id': warehouse_id,
        'warehouse': warehouse_name,
        'warehouse_code': warehouse_code,
        'business_type': raw_business_type,
        'material_code': (request.args.get('material_code') or '').strip(),
        'supplier_id': _parse_positive_int(request.args.get('supplier_id'), 0),
        'supplier': (request.args.get('supplier') or '').strip(),
        'customer': (request.args.get('customer') or '').strip(),
        'status': (request.args.get('status') or '').strip(),
        'sort_field': (request.args.get('sort_field') or '').strip(),
        'sort_order': 'desc' if (request.args.get('sort_order') or '').lower() == 'desc' else 'asc',
        'page': _parse_positive_int(request.args.get('page'), 1),
        'page_size': min(_parse_positive_int(request.args.get('page_size'), 20), 500),
        'hide_zero': request.args.get('hide_zero', '').lower() in ('1', 'true', 'on'),
        'export': (request.args.get('export') or '').strip().lower(),
    }

def _keyword_tokens(keyword):
    return [token for token in str(keyword or '').split() if token]

def _material_filter_clause(keyword):
    clauses = []
    for token in _keyword_tokens(keyword):
        pattern = f'%{token}%'
        clauses.append(db.or_(
            Material.code.ilike(pattern),
            Material.name.ilike(pattern),
            Material.spec.ilike(pattern),
        ))
    return db.and_(*clauses) if clauses else None

def _supplier_filter_clause(keyword):
    clauses = []
    for token in _keyword_tokens(keyword):
        pattern = f'%{token}%'
        clauses.append(db.or_(
            Supplier.code.ilike(pattern),
            Supplier.name.ilike(pattern),
        ))
    return db.and_(*clauses) if clauses else None

def _material_matches(material, keyword):
    if not keyword:
        return True
    if material is None:
        return False
    haystack = ' '.join(
        str(part or '').lower()
        for part in (material.code, material.name, material.spec)
    )
    return all(token.lower() in haystack for token in keyword.split() if token)

def _supplier_matches(supplier, keyword):
    if not keyword:
        return True
    if supplier is None:
        return False
    haystack = ' '.join(
        str(part or '').lower()
        for part in (supplier.code, supplier.name)
    )
    return all(token.lower() in haystack for token in keyword.split() if token)

def _within_date_range(value, start_date=None, end_date=None):
    if value is None:
        return False
    if start_date and value < start_date:
        return False
    if end_date and value > end_date:
        return False
    return True

def _status_label(status):
    return STATUS_LABELS.get(status, status or '-')

def _report_detail_url(endpoint, doc_id):
    if not endpoint or not doc_id:
        return ''
    try:
        return url_for(endpoint, id=doc_id)
    except Exception:
        return ''

def _report_reference_info(reference_type, reference_id, fallback_no=''):
    config = REPORT_REFERENCE_LINKS.get(reference_type or '')
    fallback_no = fallback_no or ''
    if not config or not reference_id:
        return fallback_no, ''

    doc = db.session.get(config['model'], reference_id)
    if not doc:
        return fallback_no, ''

    number = getattr(doc, config['number'], None) or fallback_no or f'{reference_type}-{reference_id}'
    return str(number), _report_detail_url(config['endpoint'], doc.id)

def _serialize_excel_value(column, row):
    value = row.get(column['field'])
    if value is None:
        return ''
    if column.get('type') == 'status':
        return _status_label(value)
    return value

def _build_excel_response(report_type, columns, rows):
    from openpyxl import Workbook

    definition = _get_report_definition(report_type)
    workbook = Workbook()
    worksheet = workbook.active
    worksheet.title = 'Report'
    worksheet.append([column['title'] for column in columns])
    for row in rows:
        worksheet.append([_serialize_excel_value(column, row) for column in columns])

    output = io.BytesIO()
    workbook.save(output)
    output.seek(0)
    filename = f'{report_type}_report.xlsx'
    if definition:
        filename = f"{report_type}_{datetime.now().strftime('%Y%m%d_%H%M%S')}.xlsx"
    return send_file(
        output,
        download_name=filename,
        as_attachment=True,
        mimetype='application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'
    )

def _sort_rows(rows, sort_field, sort_order):
    if not sort_field or not rows or sort_field not in rows[0]:
        return rows

    def sort_key(row):
        value = row.get(sort_field)
        if value is None:
            return (1, '')
        if isinstance(value, (int, float)):
            return (0, value)
        return (0, str(value).lower())

    return sorted(rows, key=sort_key, reverse=(sort_order == 'desc'))

def _paginate_rows(rows, page, page_size):
    start = (page - 1) * page_size
    end = start + page_size
    return rows[start:end]

