def _collect_inventory_rows(filters):
    # BUG-2026-08-02-014：AGENTS.md 报表仓库必填，无仓库不返回数据
    if not filters.get('warehouse_id') and not filters.get('warehouse'):
        return []
    # BUG-2026-08-17-00X：库存报表按仓库级口径展示（与库存查询一致），
    # 不再使用跨仓的 Material.stock 全局数。
    warehouse = None
    if filters.get('warehouse_id'):
        warehouse = Warehouse.query.get(filters['warehouse_id'])
    warehouse_stock_map = get_warehouse_stock_quantities(warehouse) if warehouse else {}
    query = Material.query.order_by(Material.code.asc(), Material.id.asc())
    if filters['supplier_id']:
        query = query.filter(Material.supplier_id == filters['supplier_id'])
    supplier_clause = _supplier_filter_clause(filters.get('supplier'))
    if supplier_clause is not None:
        query = query.join(Material.supplier).filter(supplier_clause)
    material_clause = _material_filter_clause(filters.get('material_code'))
    if material_clause is not None:
        query = query.filter(material_clause)

    rows = []
    for material in query.all():
        stock = _safe_float(warehouse_stock_map.get(material.id) or 0)
        price = _safe_float(material.price)
        # BUG-2026-08-18-00X：hide_zero 选项过滤掉库存为 0 的行
        if filters.get('hide_zero') and stock == 0:
            continue
        rows.append({
            'code': material.code or '',
            'name': material.name or '',
            'spec': material.spec or '',
            'category': material.category.name if material.category else '',
            'unit': material.unit.name if material.unit else '',
            'supplier': material.supplier.name if material.supplier else '',
            'stock': stock,
            'price': price,
            'stock_value': stock * price,
            'min_stock': _safe_float(material.min_stock),
            'max_stock': _safe_float(material.max_stock),
        })
    return rows

def _collect_in_detail_rows(filters):
    # BUG-2026-08-02-014：AGENTS.md 报表仓库必填，无仓库不返回数据
    if not filters.get('warehouse_id') and not filters.get('warehouse'):
        return []
    query = InOrderItem.query.join(InOrder).join(Material, InOrderItem.material_id == Material.id).options(
        joinedload(InOrderItem.in_order).joinedload(InOrder.supplier),
        joinedload(InOrderItem.in_order).joinedload(InOrder.customer),
        joinedload(InOrderItem.in_order).joinedload(InOrder.operator),
        joinedload(InOrderItem.material).joinedload(Material.unit)
    ).order_by(
        InOrder.date.desc(),
        InOrder.order_no.desc(),
        InOrderItem.id.desc()
    )
    # BUG-2026-08-18-004：此前硬编码只查"采购入库"，手机端"产品入库"、
    # 网页端"其他入库"在入库明细报表里永远查不出来。改为可选筛选，
    # business_type 为空表示全部入库类型。
    business_type = (filters.get('business_type') or '').strip()
    if business_type:
        query = query.filter(InOrder.business_type == business_type)
    # BUG-2026-08-02-014：入库明细按仓库过滤；兼容历史数据仓库名/编号不统一
    if filters.get('warehouse') or filters.get('warehouse_code'):
        # 用户手机端手工录入仓库编号（如 WH001）、网页端用仓库名，
        # 单据 warehouse 字段可能存名称也可能存编号，任一匹配。
        match_any = [InOrder.warehouse == filters['warehouse']] if filters.get('warehouse') else []
        if filters.get('warehouse_code'):
            match_any.append(InOrder.warehouse == filters['warehouse_code'])
        if match_any:
            query = query.filter(db.or_(*match_any))
    if filters['start_date']:
        query = query.filter(InOrder.date >= filters['start_date'])
    if filters['end_date']:
        query = query.filter(InOrder.date <= filters['end_date'])
    if filters['supplier_id']:
        query = query.filter(InOrder.supplier_id == filters['supplier_id'])
    supplier_clause = _supplier_filter_clause(filters.get('supplier'))
    if supplier_clause is not None:
        query = query.join(Supplier, InOrder.supplier_id == Supplier.id).filter(supplier_clause)
    if filters['status']:
        query = query.filter(InOrder.status == filters['status'])
    material_clause = _material_filter_clause(filters.get('material_code'))
    if material_clause is not None:
        query = query.filter(material_clause)

    items = query.limit(5000).all()

    rows = []
    for item in items:
        order = item.in_order
        material = item.material
        if material is None:
            continue
        rows.append({
            'date': order.date.isoformat() if order.date else '',
            'order_no': order.order_no or '',
            'order_url': _report_detail_url('in_order_detail', order.id),
            'business_type': order.business_type or '采购入库',
            'supplier': order.supplier.name if order.supplier else '',
            'customer': order.customer.name if order.customer else '',
            'warehouse': order.warehouse or '',
            'location': order.location or '',
            'is_customer_supplied': '是' if item.is_customer_supplied else '否',
            'material_code': material.code or '',
            'material_name': material.name or '',
            'spec': material.spec or '',
            'unit': material.unit.name if material.unit else '',
            'quantity': _safe_float(item.quantity),
            'price': _safe_float(item.price),
            'amount': _safe_float(item.amount),
            'status': order.status or '',
            'operator': order.operator.username if order.operator else '',
            'purpose': order.purpose or '',
            'remark': order.remark or '',
        })
    return rows

