# ==================== Sales management ====================
def generate_sales_order_no():
    prefix = 'SO'
    month = datetime.now().strftime('%y%m')
    last = SalesOrder.query.filter(SalesOrder.order_no.like(f'{prefix}{month}%')).order_by(SalesOrder.id.desc()).first()
    sequence = 1
    if last:
        try:
            sequence = int(last.order_no[-4:]) + 1
        except (TypeError, ValueError):
            sequence = SalesOrder.query.filter(SalesOrder.order_no.like(f'{prefix}{month}%')).count() + 1
    return f'{prefix}{month}{sequence:04d}'

def sales_status_label(status):
    return {
        'draft': '草稿',
        'confirmed': '已确认',
        'closed': '已完成',
        'cancelled': '已取消',
    }.get(status, status or '-')

def sales_shipment_status_label(status):
    return {'pending': '待发货', 'partial': '部分发货', 'shipped': '已发货'}.get(status, status or '-')

def recalculate_sales_order(order):
    """重新计算销售订单的金额、税额和发货状态。

    - price 视为含税单价；tax_included_amount = quantity * price
    - untaxed_price = price / (1 + tax_rate)；untaxed_amount = tax_included_amount / (1 + tax_rate)
    - tax_amount = tax_included_amount - untaxed_amount
    - amount 字段保留为含税金额，兼容旧逻辑
    """
    total_included = 0
    total_untaxed = 0
    total_tax = 0
    shipped_total_qty = 0
    total_quantity = 0
    shipped_amount = 0
    for item in order.items:
        qty = max(item.quantity or 0, 0)
        price = item.price or 0
        tax_rate = item.tax_rate if item.tax_rate is not None else 0.13
        if tax_rate < 0:
            tax_rate = 0
        included = round_to_2_decimals(qty * price)
        untaxed = round_to_2_decimals(included / (1 + tax_rate)) if (1 + tax_rate) > 0 else included
        tax = round_to_2_decimals(included - untaxed)
        untaxed_price = round(price / (1 + tax_rate), 4) if (1 + tax_rate) > 0 and qty > 0 else 0
        item.untaxed_price = untaxed_price
        item.untaxed_amount = untaxed
        item.tax_amount = tax
        item.tax_included_amount = included
        item.amount = included  # 兼容旧逻辑：amount = 含税金额
        item.shipped_quantity = min(max(item.shipped_quantity or 0, 0), qty)
        total_included += included
        total_untaxed += untaxed
        total_tax += tax
        total_quantity += qty
        shipped_total_qty += item.shipped_quantity or 0
        shipped_amount += round_to_2_decimals((item.shipped_quantity or 0) * price)
    order.total_amount = round_to_2_decimals(total_included)
    order.untaxed_amount = round_to_2_decimals(total_untaxed)
    order.tax_amount = round_to_2_decimals(total_tax)
    order.shipped_amount = round_to_2_decimals(shipped_amount)
    order.remaining_amount = round_to_2_decimals(total_included - shipped_amount)
    # SALES-AUDIT-001：partial/shipped 分支同样不得覆盖 cancelled 状态，
    # 否则「确认→下推草稿→取消订单→完成草稿」会让 cancelled 订单被出库完成静默复活
    if total_quantity <= 0 or shipped_total_qty <= 0:
        order.shipment_status = 'pending'
        if order.status not in ('draft', 'cancelled'):
            order.status = 'confirmed'
    elif shipped_total_qty + STOCK_COMPARE_EPSILON >= total_quantity:
        order.shipment_status = 'shipped'
        if order.status not in ('draft', 'cancelled'):
            order.status = 'closed'
    else:
        order.shipment_status = 'partial'
        if order.status not in ('draft', 'cancelled'):
            order.status = 'confirmed'

def sync_sales_order_shipment(outbound, quantity_sign=1):
    # 优先使用外键关联，兜底 purpose 字符串解析
    order = None
    if outbound.source_sales_order_id:
        order = SalesOrder.query.get(outbound.source_sales_order_id)
    if not order:
        source_match = re.search(r'来源销售订单\s+([^\s]+)', outbound.purpose or '')
        if source_match:
            order = SalesOrder.query.filter_by(order_no=source_match.group(1)).first()
    if not order and not any(item.source_sales_order_item_id for item in outbound.items):
        return None
    # SALES-AUDIT-001 防御纵深：已取消的销售订单禁止再回写发货进度，
    # 防止 cancelled 订单通过完成出库草稿被静默复活。
    if order and order.status == 'cancelled':
        return None
    items_by_material = {}
    if order:
        for item in order.items:
            items_by_material.setdefault(item.material_id, []).append(item)
    affected_orders = {}
    for outbound_item in outbound.items:
        sales_item = None
        if outbound_item.source_sales_order_item_id:
            candidate = db.session.get(SalesOrderItem, outbound_item.source_sales_order_item_id)
            if candidate and candidate.material_id == outbound_item.material_id and (not order or candidate.sales_order_id == order.id):
                sales_item = candidate
        if sales_item is None:
            candidates = items_by_material.get(outbound_item.material_id, [])
            # Legacy rows without a source line are safe only when the
            # material identifies one and only one sales order line.
            if len(candidates) == 1:
                sales_item = candidates[0]
        if not sales_item:
            continue
        # SALES-AUDIT-004：原子回写 shipped_quantity，避免并发完成引用同一销售
        # 订单的多张出库单时发生 read-modify-write 丢失更新（lost update）。
        # 对照 deduct_stock_atomic 的条件 UPDATE 模式。
        delta = quantity_sign * (outbound_item.quantity or 0)
        db.session.execute(
            sa_update(SalesOrderItem)
            .where(SalesOrderItem.id == sales_item.id)
            .values(shipped_quantity=func.max(0, SalesOrderItem.shipped_quantity + delta))
        )
        # 让 ORM 实例与 DB 一致，供后续 recalculate_sales_order 读取
        db.session.expire(sales_item, ['shipped_quantity'])
        affected_orders[sales_item.sales_order_id] = sales_item.sales_order
    for affected_order in affected_orders.values():
        recalculate_sales_order(affected_order)
    return order or next(iter(affected_orders.values()), None)

def sales_outbound_remaining_check(outbound):
    """SALES-AUDIT-006：完成出库单前校验每条明细数量不超过来源销售订单行未发货数量。

    返回 (ok, error_msg)：
    - ok=True：所有有来源的明细数量都在 remaining 范围内。
    - ok=False：存在超量明细，error_msg 描述第一条违规。
    无来源的明细（source_sales_order_item_id 为空）跳过校验。
    """
    from sqlalchemy.orm import selectinload
    if not outbound or not outbound.items:
        return True, ''
    source_item_ids = [
        item.source_sales_order_item_id
        for item in outbound.items
        if getattr(item, 'source_sales_order_item_id', None)
    ]
    if not source_item_ids:
        return True, ''
    sales_items = {
        si.id: si
        for si in SalesOrderItem.query.options(
            selectinload(SalesOrderItem.sales_order)
        ).filter(SalesOrderItem.id.in_(source_item_ids)).all()
    }
    for item in outbound.items:
        sid = getattr(item, 'source_sales_order_item_id', None)
        if not sid:
            continue
        si = sales_items.get(sid)
        if not si:
            continue
        remaining = round_to_2_decimals((si.quantity or 0) - (si.shipped_quantity or 0))
        outbound_qty = round_to_2_decimals(item.quantity or 0)
        if outbound_qty - remaining > STOCK_COMPARE_EPSILON:
            so_no = si.sales_order.order_no if si.sales_order else f'item#{sid}'
            return False, f'出库数量 {outbound_qty} 超过销售订单 {so_no} 的未发货数量 {remaining:.2f}'
    return True, ''


def build_sales_outbound_draft(order, selected_qty_by_item_id=None):
    # 优先通过外键查找待完成草稿，兜底 purpose 字符串
    pending_draft = OutOrder.query.filter(
        db.or_(
            OutOrder.source_sales_order_id == order.id,
            OutOrder.purpose == f'来源销售订单 {order.order_no}',
        ),
        OutOrder.status == 'pending',
    ).order_by(OutOrder.id.desc()).first()
    if pending_draft:
        return pending_draft, 'existing'
    remaining_by_id = {
        item.id: round_to_2_decimals((item.quantity or 0) - (item.shipped_quantity or 0))
        for item in order.items
        if (item.quantity or 0) - (item.shipped_quantity or 0) > STOCK_COMPARE_EPSILON
    }
    if not remaining_by_id:
        recalculate_sales_order(order)
        return None, 'completed'
    if selected_qty_by_item_id is None:
        selected_qty_by_item_id = remaining_by_id
    else:
        selected_qty_by_item_id = {
            item_id: round_to_2_decimals(quantity)
            for item_id, quantity in selected_qty_by_item_id.items()
            if item_id in remaining_by_id and quantity > STOCK_COMPARE_EPSILON
        }
        if not selected_qty_by_item_id:
            return None, 'invalid_selection'
        for item_id, quantity in selected_qty_by_item_id.items():
            if quantity - remaining_by_id[item_id] > STOCK_COMPARE_EPSILON:
                return None, 'over_quantity'
    remaining_items = [item for item in order.items if item.id in selected_qty_by_item_id]
    outbound = OutOrder(order_no=generate_order_no('OU'), date=order.date, customer=order.customer.name if order.customer else '', business_type='销售出库', warehouse=order.warehouse, purpose=f'来源销售订单 {order.order_no}', source_sales_order_id=order.id, remark=order.remark, status='pending', operator_id=current_user.id)
    db.session.add(outbound)
    db.session.flush()
    for item in remaining_items:
        remaining_quantity = selected_qty_by_item_id[item.id]
        db.session.add(OutOrderItem(
            out_order_id=outbound.id,
            material_id=item.material_id,
            source_sales_order_item_id=item.id,
            quantity=remaining_quantity,
            price=item.price,
            amount=round_to_2_decimals(remaining_quantity * (item.price or 0)),
            remark=f'来源销售订单 {order.order_no}',
        ))
    order.shipment_order_no = outbound.order_no
    order.shipment_status = 'pending'
    return outbound, 'created'





@app.route('/api/sales_order/selectable')
@require_role('warehouse', 'purchase', 'sales')
@login_required
def api_sales_order_selectable():
    customer_id = request.args.get('customer_id', type=int) or 0
    salesperson_id = request.args.get('salesperson_id', type=int) or 0
    warehouse = (request.args.get('warehouse') or '').strip()
    search = (request.args.get('search') or '').strip().lower()
    limit = min(max(request.args.get('limit', 150, type=int), 1), 300)

    query = SalesOrder.query.options(
        joinedload(SalesOrder.customer),
        joinedload(SalesOrder.items).joinedload(SalesOrderItem.material).joinedload(Material.unit),
    ).filter(
        SalesOrder.status == 'confirmed',
        SalesOrder.shipment_status != 'shipped',
    )
    if customer_id:
        query = query.filter(SalesOrder.customer_id == customer_id)
    if salesperson_id:
        query = query.filter(SalesOrder.salesperson_id == salesperson_id)
    if warehouse:
        query = query.filter(SalesOrder.warehouse == warehouse)
    query = query.order_by(SalesOrder.delivery_date.asc().nullslast(), SalesOrder.date.asc(), SalesOrder.id.asc()).limit(limit)

    items = []
    for order in query:
        customer_name = order.customer.name if order.customer else ''
        order_match = not search or search in (order.order_no or '').lower() or search in customer_name.lower()
        for item in order.items:
            remaining = round_to_2_decimals((item.quantity or 0) - (item.shipped_quantity or 0))
            if remaining <= STOCK_COMPARE_EPSILON:
                continue
            material = item.material
            material_code = material.code if material else ''
            material_name = material.name if material else ''
            spec = material.spec if material else ''
            if search and not order_match:
                if search not in ' '.join((material_code, material_name, spec)).lower():
                    continue
            items.append({
                'sales_order_id': order.id,
                'sales_order_no': order.order_no,
                'sales_order_item_id': item.id,
                'customer_id': order.customer_id,
                'customer_name': customer_name,
                'warehouse': order.warehouse or '',
                'salesperson_id': order.salesperson_id,
                'date': order.date.strftime('%Y-%m-%d') if order.date else '',
                'delivery_date': order.delivery_date.strftime('%Y-%m-%d') if order.delivery_date else '',
                'is_overdue': bool(order.delivery_date and order.delivery_date < date.today()),
                'material_id': item.material_id,
                'material_code': material_code,
                'material_name': material_name,
                'spec': spec,
                'unit': material.unit.name if material and material.unit else '',
                'quantity': round_to_2_decimals(item.quantity or 0),
                'shipped_quantity': round_to_2_decimals(item.shipped_quantity or 0),
                'remaining_quantity': remaining,
                'price': round_to_2_decimals(item.price or 0),
                'amount': round_to_2_decimals(remaining * (item.price or 0)),
            })
    return jsonify({'status': 'success', 'items': items})





@app.route('/api/ai/sales_order/<int:id>/anomaly_analysis')
# AI_TASK: AI-SALES-F01-FIX-03
@login_required
def api_ai_sales_order_anomaly_analysis(id):
    """Read-only AI sales order anomaly analysis; never mutates any document.

    Covers: overdue shipment, shortage of inbound material, over-shipped quantity,
    missing sales source linkage, abnormal sales price, partial-shipment stall.
    Aligned with /api/ai/out_order/<id>/anomaly_analysis read-only contract.
    """
    order = SalesOrder.query.options(
        joinedload(SalesOrder.customer),
        joinedload(SalesOrder.items).joinedload(SalesOrderItem.material).joinedload(Material.unit),
    ).get_or_404(id)
    anomalies: list[dict] = []
    summary_parts: list[str] = []

    # 1. 逾期未发货
    if order.delivery_date and order.delivery_date < date.today() and order.status in ('draft', 'confirmed') and order.shipment_status != 'shipped':
        anomalies.append({
            'kind': '逾期未发货',
            'severity': 'high',
            'message': f'交货日期 {order.delivery_date} 已过，当前发货状态：{order.shipment_status}',
        })
        summary_parts.append('逾期未发货')

    # 2. 行级超发检查
    over_shipped_items = []
    for item in order.items:
        shipped = float(item.shipped_quantity or 0)
        qty = float(item.quantity or 0)
        if shipped > qty + 1e-6:
            over_shipped_items.append(f'{item.material.code if item.material else item.material_id}: 已发 {shipped} > 订单 {qty}')
    if over_shipped_items:
        anomalies.append({
            'kind': '行级超发',
            'severity': 'high',
            'message': '; '.join(over_shipped_items),
        })
        summary_parts.append('行级超发')

    # 3. 部分发货停滞（部分发货但近 7 天无新出库）
    if order.shipment_status == 'partial':
        last_outbound = OutOrder.query.filter(
            OutOrder.source_sales_order_id == order.id,
            OutOrder.business_type == '销售出库',
        ).order_by(OutOrder.date.desc()).first()
        if last_outbound and last_outbound.date:
            days_stall = (date.today() - last_outbound.date).days
            if days_stall > 7:
                anomalies.append({
                    'kind': '部分发货停滞',
                    'severity': 'medium',
                    'message': f'最近一次出库 {last_outbound.date}，已停滞 {days_stall} 天',
                })
                summary_parts.append(f'部分发货停滞 {days_stall} 天')

    # 4. 价格异常（行含税单价 ≤ 0 或与同物料历史均值偏离 50%）
    abnormal_price_items = []
    for item in order.items:
        if not item.material:
            continue
        price = float(item.price or 0)
        if price <= 0:
            abnormal_price_items.append(f'{item.material.code}: 单价 {price} 异常')
            continue
        # 同物料历史均价（不含当前订单）
        historical_avg = db.session.query(db.func.avg(SalesOrderItem.price)).join(
            SalesOrder, SalesOrderItem.sales_order_id == SalesOrder.id
        ).filter(
            SalesOrderItem.material_id == item.material_id,
            SalesOrder.id != order.id,
            SalesOrder.status.in_(['confirmed', 'closed']),
        ).scalar()
        if historical_avg and abs(price - float(historical_avg)) / float(historical_avg) > 0.5:
            abnormal_price_items.append(
                f'{item.material.code}: 当前 {price:.2f} vs 历史 {float(historical_avg):.2f}（偏离 {(abs(price - float(historical_avg)) / float(historical_avg) * 100):.0f}%）'
            )
    if abnormal_price_items:
        anomalies.append({
            'kind': '价格异常',
            'severity': 'medium',
            'message': '; '.join(abnormal_price_items),
        })
        summary_parts.append('价格异常')

    # 5. 缺货风险（订单已确认但库存不足）
    if order.status == 'confirmed' and order.shipment_status != 'shipped':
        shortage_items = []
        for item in order.items:
            if not item.material:
                continue
            remaining = float(item.quantity or 0) - float(item.shipped_quantity or 0)
            if remaining <= 0:
                continue
            current_stock = float(item.material.stock or 0)
            if current_stock < remaining:
                shortage_items.append(f'{item.material.code}: 待发 {remaining} vs 库存 {current_stock}')
        if shortage_items:
            anomalies.append({
                'kind': '缺货风险',
                'severity': 'high',
                'message': '; '.join(shortage_items),
            })
            summary_parts.append('缺货风险')

    summary = '；'.join(summary_parts) if summary_parts else '未检测到异常'
    return jsonify({
        'status': 'success',
        'data': {
            'order': {
                'id': order.id,
                'order_no': order.order_no,
                'status': order.status,
                'shipment_status': order.shipment_status,
                'customer_name': order.customer.name if order.customer else '',
            },
            'anomalies': anomalies,
            'summary': summary,
        },
    })

@app.route('/api/ai/sales/<int:id>/draft_check', methods=['POST'])
# AI_TASK: AI-SALES-F01-FIX-01
@require_role('admin', 'warehouse', 'sales')
@login_required
def api_ai_sales_draft_check(id):
    """Read-only AI sales draft check; never confirms, completes, or mutates a document."""
    order = SalesOrder.query.options(selectinload(SalesOrder.items)).get_or_404(id)
    lines = tuple(SalesLineInfo(
        line_id=item.id,
        material_id=item.material_id,
        material_code=item.material.code if item.material else '',
        material_name=item.material.name if item.material else '',
        quantity=float(item.quantity or 0),
        shipped_quantity=float(item.shipped_quantity or 0),
        price=float(item.price or 0),
        tax_rate=float(item.tax_rate or 0.13),
    ) for item in order.items)
    sales_info = SalesOrderInfo(
        order_id=order.id,
        order_no=order.order_no,
        status=order.status,
        shipment_status=order.shipment_status,
        customer_name=order.customer.name if order.customer else '',
        lines=lines,
        total_amount=float(order.total_amount or 0),
        shipped_amount=float(order.shipped_amount or 0),
    )
    outbound_infos = []
    for outbound in order.outbound_orders:
        outbound_infos.append(OutboundDraftInfo(
            outbound_id=outbound.id,
            order_no=outbound.order_no,
            status=outbound.status,
            source_sales_order_id=outbound.source_sales_order_id or order.id,
            source_sales_order_no=order.order_no,
            customer_name=outbound.customer or '',
            lines=tuple({'material_id': item.material_id, 'quantity': float(item.quantity or 0), 'price': float(item.price or 0)} for item in outbound.items),
            business_type=outbound.business_type or '',
        ))
    evidence = build_sales_draft_evidence(
        evidence_id=f'sales-check-{order.id}-{uuid.uuid4().hex[:12]}',
        operation='check_draft', operator_id=str(current_user.id), operator_role=current_user.role,
        source='ai_assistant', sales_order=sales_info,
        outbound_draft=outbound_infos[0] if outbound_infos else None,
        confidence=1.0,
        created_at=datetime.now().isoformat(),
    )
    allowed, message = validate_ai_only_draft(evidence=evidence)
    if not allowed:
        return jsonify({'status': 'error', 'msg': message}), 400
    return jsonify({'status': 'success', 'message': message, 'evidence': evidence.to_dict(), 'sales_order': sales_info.to_dict(), 'outbound_drafts': [item.to_dict() for item in outbound_infos]})

























def _require_report_warehouse():
    """SALES-AUDIT-007：报表仓库必填门禁。

    依据 AGENTS.md「库存查询、出入库报表、库存台账的查询入口必须将仓库
    作为必填条件，后端未收到仓库参数时返回空结果或 400」。

    解析顺序：warehouse_id > warehouse 名称 > 默认仓库。
    返回 (warehouse, error_msg)：
    - 成功：(Warehouse 实例, None)
    - 失败：(None, '请选择仓库')
    """
    warehouse_id = request.args.get('warehouse_id', type=int)
    if warehouse_id:
        wh = db.session.get(Warehouse, warehouse_id)
        if wh:
            return wh, None
    warehouse_name = (request.args.get('warehouse') or '').strip()
    if warehouse_name:
        wh = resolve_active_sales_warehouse(warehouse_name)
        if wh:
            return wh, None
    default_wh = get_default_warehouse()
    if default_wh:
        return default_wh, None
    return None, '请选择仓库'

def _sales_report_orders():
    """Return the common filtered order set used by sales execution reports."""
    # SALES-AUDIT-007：仓库必填，未提供且无默认仓库时返回空列表
    required_wh, _ = _require_report_warehouse()
    if not required_wh:
        return []
    query = SalesOrder.query.filter(SalesOrder.status != 'cancelled')
    date_start = request.args.get('date_start') or ''
    date_end = request.args.get('date_end') or ''
    customer_id = request.args.get('customer_id', type=int)
    material_code = (request.args.get('material_code') or '').strip()
    if date_start:
        parsed = parse_date_value(date_start)
        if parsed:
            query = query.filter(SalesOrder.date >= parsed)
    if date_end:
        parsed = parse_date_value(date_end)
        if parsed:
            query = query.filter(SalesOrder.date <= parsed)
    if customer_id:
        query = query.filter(SalesOrder.customer_id == customer_id)
    query = query.filter(db.or_(SalesOrder.warehouse_id == required_wh.id, db.and_(SalesOrder.warehouse_id.is_(None), SalesOrder.warehouse == required_wh.name)))
    if material_code:
        query = query.join(SalesOrderItem).join(Material).filter(
            db.or_(Material.code.ilike(f'%{material_code}%'), Material.name.ilike(f'%{material_code}%'))
        ).distinct()
    return query.options(
        joinedload(SalesOrder.customer),
        selectinload(SalesOrder.items).joinedload(SalesOrderItem.material),
    ).order_by(SalesOrder.date.desc(), SalesOrder.id.desc()).all()

def _sales_report_filters_context():
    required_wh, _ = _require_report_warehouse()
    return {
        'date_start': request.args.get('date_start') or '',
        'date_end': request.args.get('date_end') or '',
        'customer_id': request.args.get('customer_id', type=int) or '',
        'material_code': request.args.get('material_code') or '',
        'warehouse_id': required_wh.id if required_wh else '',
        'warehouse': required_wh.name if required_wh else '',
    }





